const a={"les-n4-u09-01":{pedagogical_framework:{what:{summary:"Membentuk kalimat pasif langsung (直接受身 chokusetsu ukemi: verba Gol 1 -areru, Gol 2 -rareru, Gol 3 sareru/korareru) untuk fakta publik, sejarah, serta bahan pembuatan karya (~kara tsukuru / ~de dekite iru).",canDo:"Bisa memandu rekan kerja mengenai sejarah pabrik atau bangunan bersejarah dan asal bahan baku produk.",targetPatterns:["[Verba-reru / rareru] (bentuk pasif umum)","[Kata Benda] は [Tahun / Tokoh] に [Verba Pasif] (didirikan / dibangun / ditemukan)","[Bahan Terlihat Fisik] で できている (terbuat dari bahan padat)","[Bahan Olahan Kimia] から 作【つく】られる (dibuat dari bahan mentah/fermentasi)"],coreVocabSample:["たてられる","はっけんされる","ゆしゅつされる","せきゆ","プラスチック","げんりょう"]},sensei_context:{sceneIntro:"Di museum sejarah industri pabrik otomotif Nagoya. Kenji memandu Budi melihat pameran lini perakitan mobil pertama di Jepang.",dailyMission:"Gunakan bentuk pasif (ukemi) untuk menjelaskan peristiwa bersejarah yang tidak berfokus pada subjek manusia tunggal.",whyOrder:"Setelah menguasai kalimat aktif di level N5, pembelajar N4 harus mampu membaca artikel berita objektif, papan informasi sejarah museum, dan manual spesifikasi produk."},cultural_notes:{title:"Pasif Objektif dalam Narasi Publik & Media Jepang (客観的事実の受身)",etiquette:"Ketika menjelaskan sejarah gedung atau produk perusahaan, bahasa Jepang formal selalu memakai kalimat pasif (tateraremashita, seizou sarete imasu) agar terdengar berwibawa dan tidak berpusat pada ego perseorangan.",taboos:"Perhatikan perbedaan bahan: jika bentuk aslinya masih terlihat jelas (seperti kayu pada meja), gunakan でできている. Jika sudah berubah zat (seperti beras menjadi sake), gunakan から作られる."},pronunciation_tips:{title:"Konjugasi Halus Bunyi Pasif Vokal -A + Reru",moraNote:"Golongan 1: kaku -> kak-areru; tsukuru -> tsukur-areru; nomu -> nom-areru.",soundTip:"Pada Golongan 2 (taberareru, homerareta), jaga artikulasi mora -ra-re- agar tidak terdengar tergesa."},common_pitfalls:[{title:'Tertukar Antara "De dekite iru" (Bahan Kasat Mata) vs "Kara tsukurareru" (Bahan Kimia/Proses)',caseScenario:"Mengatakan bahwa kecap asin dibuat dari kedelai.",pitfallWarning:'"醤油【しょうゆ】は 大豆【だいず】で できて います。"',rightSolution:'"醤油【しょうゆ】は 大豆【だいず】から 作【つく】られます。"',explanation:"Bahan yang mengalami transformasi wujud fisik/kimia (seperti kedelai menjadi cairan kecap) wajib menggunakan から. Jika wujud aslinya masih tampak (seperti meja kayu), gunakan で."},{title:"Salah Konjugasi Pasif Verba Golongan 1 Berakhiran Vokal U (Suara Wa-reru)",caseScenario:"Mengubah kata kerja kauf/kau (membeli) menjadi pasif.",pitfallWarning:'"買【か】あれる (ka-areru)"',rightSolution:'"買【か】われる (ka-wareru)"',explanation:"Verba Golongan 1 yang berakhiran huruf u (seperti 買う, 言う, 使う) berubah menjadi baris -wa: 買われる, 言われる, 使われる."}],who_and_when:{situational_context:"Pemanduan tur pabrik bagi tamu mitra kerja, presentasi materi produk di ruang seminar, membaca papan petunjuk cagar budaya.",social_relations:"Ragam narasi formal dan objektif yang sangat profesional di hadapan publik.",when_not_to_use:"Jangan gunakan pada percakapan kasual santai yang membicarakan aktivitas pribadi sehari-hari."},scenario:{title:"Pemanduan Sejarah Pabrik Otomotif Pertama",setting:"Museum Sejarah Pabrik Nagoya, pukul 13.30",narrative:"Kenji menjelaskan kepada Budi bahwa pabrik ini didirikan pada tahun 1950 dan mobil buatannya diekspor ke seluruh dunia."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Senior Pabrik",avatar:"🧑‍💻",jp:"ブディ、この 工場【こうじょう】は いつ 建【た】てられたか 知【し】っている？",furigana:"ブディ、この 工場は いつ 建てられたか 知っている？",romaji:"Budi, kono koujou wa itsu taterareta ka shitte iru?",idText:"Budi, kamu tahu kapan pabrik ini pertama kali dibangun?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"看板【かんばん】に １９５０年【せんきゅうひゃくごじゅうねん】に 創設【そうせつ】されたと 書【か】いて あります！",furigana:"看板に １９５０年に 創設されたと 書いて あります！",romaji:"Kanban ni sen-kyuuhyaku-gojuunen ni sousetsu sareta to kaite arimasu!",idText:"Di papan tertulis bahwa pabrik ini didirikan pada tahun 1950!"},{id:"d3",speaker:"Kenji",speakerRole:"Senior Pabrik",avatar:"🧑‍💻",jp:"そうなんだ。ここで 作【つく】られた 車【くるま】は、世界中【せかいじゅう】に 輸出【ゆしゅつ】されているんだよ。",furigana:"そうなんだ。ここで 作られた 車は、世界中に 輸出されているんだよ。",romaji:"Sou na n da. Koko de tsukurareta kuruma wa, sekaijuu ni yushutsu sarete iru n da yo.",idText:"Betul sekali. Mobil yang diproduksi di sini diekspor ke seluruh penjuru dunia lho."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"車【くるま】の バンパーは 軽【かる】い プラスチックで できているんですね。",furigana:"車の バンパーは 軽い プラスチックで できているんですね。",romaji:"Kuruma no banpa- wa karui purasuchikku de dekite iru n desu ne.",idText:"Bumper mobilnya ternyata terbuat dari bahan plastik yang ringan ya."},{id:"d5",speaker:"Kenji",speakerRole:"Senior Pabrik",avatar:"🧑‍💻",jp:"プラスチックは 石油【せきゆ】から 作【つく】られるから、加工【かこう】が しやすいんだ。",furigana:"プラスチックは 石油から 作られるから、加工が しやすいんだ。",romaji:"Purasuchikku wa sekiyu kara tsukurareru kara, kakou ga shiyasui n da.",idText:"Karena plastik dibuat dari minyak bumi melalui proses kimia, pengolahannya menjadi sangat mudah."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"技術【ぎじゅつ】の 歴史【れきし】が よく 分【わ】かりました。見学【けんがく】できて よかったです！",furigana:"技術の 歴史が よく 分かりました。見学できて よかったです！",romaji:"Gijutsu no rekishi ga yoku wakarimashita. Kengaku dekite yokatta desu!",idText:"Saya jadi sangat memahami sejarah perkembangannya. Syukurlah bisa ikut tur studi orientasi ini!"}],vocab_breakdown:[{id:"vg-n4-00006",word:"運転",reading:"うんてん",romaji:"unten",meaning:"mengemudi",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"父は毎朝車を運転して会社に行きます。",furigana:"父は毎朝車を運転して会社に行きます。",romaji:"",idText:"Ayah mengemudikan mobil setiap pagi untuk pergi ke kantor."}},{id:"vg-n4-00135",word:"選択",reading:"せんたく",romaji:"sentaku",meaning:"pilihan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"正しい答えを四つの中から一つ選択してください。",furigana:"正しい答えを四つの中から一つ選択してください。",romaji:"",idText:"Pilihlah satu jawaban yang benar dari empat pilihan yang ada."}},{id:"vg-n4-00226",word:"いただく",reading:"いただく",romaji:"itadaku",meaning:"menerima",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"先輩から素敵な本をいただいて嬉しかったです。",furigana:"先輩から素敵な本をいただいて嬉しかったです。",romaji:"",idText:"Saya senang sekali menerima buku yang bagus dari senior."}},{id:"vg-n4-00227",word:"くださる",reading:"くださる",romaji:"kudasaru",meaning:"memberi",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"先生が丁寧に日本語の文法を教えてくださいました。",furigana:"先生が丁寧に日本語の文法を教えてくださいました。",romaji:"",idText:"Guru dengan teliti mengajarkan tata bahasa Jepang kepada saya."}},{id:"vg-n4-00395",word:"いらっしゃる",reading:"いらっしゃる",romaji:"irassharu",meaning:"ada",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"田中先生はただいま研究室にいらっしゃいます。",furigana:"田中先生はただいま研究室にいらっしゃいます。",romaji:"",idText:"Sensei Tanaka saat ini sedang berada di ruang risetnya."}},{id:"vg-n4-00420",word:"探す",reading:"さがす",romaji:"sagasu",meaning:"mencari",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"落とした鍵を部屋の中でずっと探しています。",furigana:"落とした鍵を部屋の中でずっと探しています。",romaji:"",idText:"Saya seharian mencari anak kunci yang terjatuh di kamar."}},{id:"vg-n4-00536",word:"戦争",reading:"せんそう",romaji:"sensou",meaning:"perang",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"世界から戦争がなくなり平和になることを願っています。",furigana:"世界から戦争がなくなり平和になることを願っています。",romaji:"",idText:"Saya mendambakan peperangan musnah dari muka bumi agar kedamaian abadi."}},{id:"vg-n4-00659",word:"確認する",reading:"かくにんする",romaji:"kakuninsuru",meaning:"mengkonfirmasi, mengecek",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"メールを送信する前に宛先のアドレスを確認してください。",furigana:"メールを送信する前に宛先のアドレスを確認してください。",romaji:"",idText:"Teliti kembali deretan alamat surat elektronik tujuan sebelum menekan kirim."}},{id:"vg-n4-00679",word:"運転する",reading:"うんてんする",romaji:"untensuru",meaning:"mengemudi",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"免許を取ってから自分で車を運転して通勤しています。",furigana:"免許を取ってから自分で車を運転して通勤しています。",romaji:"",idText:"Semenjak mengantongi izin mengemudi, saya pulang-pergi menyetir kendaraan pribadi."}},{id:"vg-n4-00754",word:"飾る",reading:"かざる",romaji:"kazaru",meaning:"menghias, memajang, mendekorasi",pos:"verb-u",nuance:"Kata kerja transitif godan yang bermakna memajang atau menghiasi ruangan dengan benda hiasan agar tampak indah dan semarak. Berbeda dengan 片付ける (katadukeru / membereskan barang agar rapi tersimpan).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"友達の誕生日パーティーのためにみんなで部屋をきれいに飾りました。",furigana:"友達の誕生日パーティーのためにみんなで部屋をきれいに飾りました。",romaji:"",idText:"Kami bersama-sama menghias kamar dengan indah demi pesta ulang tahun teman."}}],explanations:[{id:"exp-1",grammarId:"gn4-00028",title:"Pola: Vられる (pasif)",formula:"V-ない-form → replace ない dengan れる/られる",meaning:"di- / dilakukan kepada ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vられる (pasif)",idText:"di- / dilakukan kepada ..."}],examples:[{jp:"財布を盗まれました。",romaji:"",idText:"Dompet saya dicuri."},{jp:"先生にほめられました。",romaji:"",idText:"Saya dipuji oleh guru."},{jp:"雨に降られて、困りました。",romaji:"",idText:"Diguyur hujan, saya kewalahan."}]},{id:"exp-2",grammarId:"gn4-00067",title:"Pola: 〜から作る / 〜でできている",formula:"N (bahan) + から作る / N + でできている",meaning:"dibuat dari ... / terbuat dari ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜から作る / 〜でできている",idText:"dibuat dari ... / terbuat dari ..."}],examples:[{jp:"ワインはぶどうから作られます。",romaji:"",idText:"Wine dibuat dari anggur."},{jp:"このカバンは革でできています。",romaji:"",idText:"Tas ini terbuat dari kulit."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:'Langkah 1 (Konsep Pasif Sejarah): Pilihlah kata kerja pasif yang bermakna "didirikan / dibangun".',sentencePrompt:"Bentuk pasif dari kata kerja 建てる (membangun gedung) adalah:",options:["建【た】てられる (Dibangun)","建【た】たせる (Menyuruh membangun)","建【た】ち始【はじ】める (Mulai dibangun)","建【た】てておく (Mempersiapkan bangunan)"],correctAnswer:"建【た】てられる (Dibangun)",explanation:"Verba Golongan 2: 建てる -> buang -ru + rareru = 建てられる (dibangun).",diagnosticFeedback:{"建たせる (Menyuruh membangun)":"Salah: Ini adalah bentuk kausatif (shieki).","立ち始める (Mulai dibangun)":"Salah: Ini adalah bentuk permulaan.","建てておく (Mempersiapkan bangunan)":"Salah: Ini adalah bentuk persiapan te-oku.","建【た】たせる (Menyuruh membangun)":'Pilihan "建【た】たせる (Menyuruh membangun)" keliru karena tidak selaras dengan kaidah pola gn4-00028.',"建【た】ち始【はじ】める (Mulai dibangun)":'Jebakan Partikel: Pilihan "建【た】ち始【はじ】める (Mulai dibangun)" tidak tepat untuk peran gramatikal kalimat ini.',"建【た】てておく (Mempersiapkan bangunan)":'Pilihan "建【た】てておく (Mempersiapkan bangunan)" keliru karena tidak selaras dengan kaidah pola gn4-00028.'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Seleksi Bahan Pembuatan): Lengkapi kalimat asal bahan meja kayu.",sentencePrompt:"この 机【つくえ】は 丈夫【じょうぶ】な 木【き】（　　）できて います。",options:["で","から","に","を"],correctAnswer:"で",explanation:"Untuk bahan yang wujud fisiknya masih terlihat jelas kasat mata (kayu pada meja), gunakan partikel で (でできている).",diagnosticFeedback:{から:"Salah: から dipakai jika bahan mentah mengalami perubahan zat kimia (contoh: anggur menjadi wine).",に:"Salah: に menandai tujuan.",を:"Salah: を menandai objek kalimat aktif."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Pasif Konjugasi Golongan 1): Pilihlah bentuk pasif yang benar untuk kata 使う (memakai).",sentencePrompt:"日本【にほん】の アニメは 世界中【せかいじゅう】で（　　）います。",options:["見【み】られて","見【み】させて","見【み】て","見【み】えられて"],correctAnswer:"見【み】られて",explanation:"Verba Golongan 2 見る dalam bentuk pasif menjadi 見られる (見られています = ditonton oleh orang sedunia).",diagnosticFeedback:{見させて:"Salah: Ini bentuk kausatif (menyuruh menonton).",見て:"Salah: Ini bentuk aktif te.",見えられて:"Salah: Konjugasi salah.","見【み】させて":'Pilihan "見【み】させて" keliru karena tidak selaras dengan kaidah pola gn4-00028.',"見【み】て":'Pilihan "見【み】て" keliru karena tidak selaras dengan kaidah pola gn4-00028.',"見【み】えられて":'Pilihan "見【み】えられて" keliru karena tidak selaras dengan kaidah pola gn4-00028.'}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat sejarah candi Borobudur yang dibangun di Indonesia.",sentencePrompt:'Susunlah kata-kata: "Candi Borobudur dibangun di Indonesia".',options:["ボロブドゥールは インドネシアで 昔【むかし】 建【た】てられました。","インドネシアで 昔【むかし】 建【た】てられました ボロブドゥールは。","建【た】てられました ボロブドゥールは インドネシアで 昔【むかし】。","昔【むかし】 建【た】てられました インドネシアで ボロブドゥールは。"],correctAnswer:"ボロブドゥールは インドネシアで 昔【むかし】 建【た】てられました。",explanation:"Topik (ボロブドゥールは) + Tempat aksi (インドネシアで) + Waktu (昔) + Pasif lampau (建てられました).",diagnosticFeedback:{"インドネシアで 昔【むかし】 建【た】てられました ボロブドゥールは。":"Salah susun: Topik kalimat terlempar ke akhir.","建【た】てられました ボロブドゥールは インドネシアで 昔【むかし】。":"Salah posisi predikat.","昔【むかし】 建【た】てられました インドネシアで ボロブドゥールは。":"Salah struktur."},tokens:["ボロブドゥールは","インドネシアで","昔【むかし】","建【た】てられました"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Analisis Nuansa): Analisislah mengapa kalimat pasif sering dipakai dalam berita dan buku sejarah.",sentencePrompt:"Alasan utama kalimat pasif (Ukemi) sering dipakai dalam buku sejarah dan pemanduan museum adalah:",options:["Untuk menonjolkan objek fakta sejarah dan peristiwa penting tanpa berpusat pada subjek perseorangan yang subjektif","Karena dalam bahasa Jepang kalimat aktif dilarang untuk mendeskripsikan masa lalu","Karena kalimat pasif lebih pendek jumlah hurufnya daripada kalimat aktif","Agar pendengar merasa kebingungan mengenai siapa pelaku sesungguhnya"],correctAnswer:"Untuk menonjolkan objek fakta sejarah dan peristiwa penting tanpa berpusat pada subjek perseorangan yang subjektif",explanation:"Pasif langsung fakta publik (直接受身) menciptakan nada objektif, netral, dan fokus pada pencapaian peristiwanya.",diagnosticFeedback:{"Karena dalam bahasa Jepang kalimat aktif dilarang untuk mendeskripsikan masa lalu":"Salah: Kalimat aktif tentu saja boleh digunakan.","Karena kalimat pasif lebih pendek jumlah hurufnya daripada kalimat aktif":"Salah: Kalimat pasif justru memiliki konjugasi lebih panjang.","Agar pendengar merasa kebingungan mengenai siapa pelaku sesungguhnya":"Salah: Tujuannya bukan membingungkan."}}],can_do_challenge:{statement:"Bisa memandu rekan kerja mengenai sejarah pabrik atau bangunan budaya di kota.",situation:"Menjelaskan kepada tamu kunjungan bahwa pabrik ini dibangun 50 tahun yang lalu.",promptTask:"Katakan bahwa pabrik ini dibangun pada 50 tahun yang lalu!",modelAnswer:"この 工場【こうじょう】は ５０年【ごじゅうねん】前【まえ】に 建【た】てられました。",modelAnswerId:"Pabrik ini dibangun pada 50 tahun yang lalu.",culturalEtiquette:"Tunjuk ke arah bangunan dengan gestur telapak tangan terbuka mengarah ke atas.",skillUnlocked:["Menguasai formulasi pasif langsung verba reru/rareru","Mampu menjelaskan asal usul bahan produk (de dekite iru / kara tsukurareru)"]},pocket_summary:{keyFormula:"Verba Pasif (Ukemi) / [Bahan Tampak] で できている / [Bahan Kimia/Mentah] から 作られる",coreWords:["たてられる","はっけんされる","ゆしゅつされる","せきゆ"],coreWarning:"Meja dari kayu = ki DE dekite iru; sake dari beras = kome KARA tsukurareru.",quickDialogue:"A: これは木で？ → B: はい、木でできています。"}},"les-n4-u09-02":{pedagogical_framework:{what:{summary:"Menyatakan penanda agen penyebab atau metode penentu (~ni yotte / ni yoru), sikap perlakuan terhadap sasaran (~ni taishite), dan kedudukan peran status resmi (~to shite).",canDo:"Bisa berbicara mewakili posisi peserta magang teknis dalam sambutan resmi dan menjelaskan aturan berdasar regulasi.",targetPatterns:["[Kata Benda] によって (disebabkan oleh / tergantung pada / ditentukan oleh)","[Kata Benda] による [Kata Benda] (yang disebabkan oleh ...)","[Kata Benda] に 対【たい】して (terhadap / kepada sasaran)","[Kata Benda] として (sebagai / dalam kapasitas kedudukan)"],coreVocabSample:["じっしゅうせい","だいひょう","たいど","ほうりつ","きそく","えいきょう"]},sensei_context:{sceneIntro:"Di aula penyambutan peserta magang baru. Budi menyampaikan pidato perwakilan sambutan sebagai duta pembelajar Indonesia di hadapan direktur perusahaan.",dailyMission:"Gunakan 〜として untuk menyatakan peran kedudukan resmi, dan 〜に対して untuk sikap hormat terhadap senior dan mitra.",whyOrder:"Setelah memahami kalimat pasif di Lesson 1, pola 〜によって melengkapi agen pencipta karya pasif, dan 〜として memantapkan identitas formal di dunia kerja."},cultural_notes:{title:"Kesadaran Peran & Kedudukan Sosial di Jepang (立場と役割の意識)",etiquette:'Ungkapan "Kenshuusei to shite..." (Sebagai peserta pelatihan...) menunjukkan kesadaran tinggi akan batas tanggung jawab dan etos belajar yang sangat dihargai oleh pimpinan perusahaan Jepang.',taboos:"Jangan tertukar antara 〜に対して (sikap kepada pihak luar) vs 〜にとって (menurut sudut pandang penilaian diri)."},pronunciation_tips:{title:'Penjagaan Ketukan Frasa Formal "Ni yotte" & "To shite"',moraNote:"Ni yot-te memiliki konsonan ganda sokon (jeda 1 mora di tengah).",soundTip:'Ucapkan "to shite" dengan artikulasi tegas dan intonasi resmi berwibawa.'},common_pitfalls:[{title:"Tertukar Antara 〜として (Sebagai Peran Status) vs 〜にとって (Menurut Sudut Pandang)",caseScenario:'Ingin mengatakan "Bagi saya bahasa Jepang itu penting".',pitfallWarning:'"私【わたし】として 日本語【にほんご】は 大切【たいせつ】です。"',rightSolution:'"私【わたし】にとって 日本語【にほんご】は 大切【たいせつ】です。"',explanation:'〜にとって berarti "bagi / menurut sudut pandang penilaian". Sedangkan 〜として berarti "dalam peran / kedudukan resmi sebagai".'},{title:"Lupa Mengubah 〜によって Menjadi 〜による Sebelum Kata Benda",caseScenario:"Menyambungkan kata benda di belakang tanpa perubahan ke による.",pitfallWarning:'"台風【たいふう】によって 被害【ひがい】"',rightSolution:'"台風【たいふう】による 被害【ひがい】"',explanation:"Sebelum kata kerja gunakan 〜によって, tetapi sebelum kata benda wajib menggunakan bentuk penghubung 〜による [N]."}],who_and_when:{situational_context:"Pidato sambutan kedatangan peserta magang, pemaparan evaluasi kerja bulanan, koordinasi penegakan disiplin K3.",social_relations:"Ragam resmi formal tinggi yang biasa digunakan dalam forum resmi perusahaan.",when_not_to_use:"Jangan gunakan bahasa kaku ini untuk obrolan santai membeli camilan di toserba konbini."},scenario:{title:"Pidato Sambutan Mewakili Peserta Magang Indonesia",setting:"Aula serbaguna perusahaan, pukul 09.00",narrative:"Budi berbicara di depan podium mewakili 10 rekan magang dan berjanji akan bersungguh-sungguh belajar sebagai pembelajar teknis."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"皆様【みなさま】、技能【ぎのう】実習生【じっしゅうせい】の 代表【だいひょう】として 一言【ひとこと】 ご挨拶【あいさつ】いたします。",furigana:"皆様、技能実習生の 代表として 一言 ご挨拶いたします。",romaji:"Minasama, ginou jisshuusei no daihyou to shite hitokoto go-aisatsu itashimasu.",idText:"Hadirin sekalian, sebagai perwakilan peserta pemagangan teknis, izinkan saya menyampaikan sepatah kata sambutan."},{id:"d2",speaker:"Tanaka",speakerRole:"Kepala Divisi",avatar:"🧑‍💼",jp:"立派【りっぱ】な 挨拶【あいさつ】ですね。指導員【しどういん】の 皆【みな】さんも 喜【よろこ】んでいますよ。",furigana:"立派な 挨拶ですね。指導員の 皆さんも 喜んでいますよ。",romaji:"Rippa na aisatsu desu ne. Shidouin no minasan mo yorokonde imasu yo.",idText:"Sambutan yang sangat mengagumkan. Para instruktur pembimbing pun merasa sangat bahagia lho."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"仕事【しごと】の やり方【かた】は 国【くに】によって 違【ちが】いますが、しっかり ルールを 守【まも】ります。",furigana:"仕事の やり方は 国によって 違いますが、しっかり ルールを 守ります。",romaji:"Shigoto no yarikata wa kuni ni yotte chigaimasu ga, shikkari ru-ru o mamorimasu.",idText:"Meskipun metode kerja berbeda-beda tergantung negaranya, kami akan mematuhi aturan kerja dengan disiplin."},{id:"d4",speaker:"Tanaka",speakerRole:"Kepala Divisi",avatar:"🧑‍💼",jp:"安全【あんぜん】規則【きそく】に対【たい】して、真剣【しんけん】に 取【と】り組【く】む 姿勢【しせい】が 一番【いちばん】 大切【たいせつ】ですよ。",furigana:"安全規則に対して、真剣に 取り組む 姿勢が 一番 大切ですよ。",romaji:"Anzen kisoku ni taishite, shinken ni torikumu shisei ga ichiban taisetsu desu yo.",idText:"Sikap bersungguh-sungguh terhadap regulasi keselamatan kerja adalah hal yang paling berharga."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 不注意【ふちゅうい】による 事故【じこ】が 起【お】きないように、確認【かくにん】を 徹底【てってい】します。",furigana:"はい！ 不注意による 事故が 起きないように、確認を 徹底します。",romaji:"Hai! Fuchuui ni yoru jiko ga okinai you ni, kakunin o tettei shimasu.",idText:"Baik! Agar tidak terjadi kecelakaan kerja yang disebabkan oleh kecerobohan, kami akan menerapkan pengecekan tuntas."},{id:"d6",speaker:"Tanaka",speakerRole:"Kepala Divisi",avatar:"🧑‍💼",jp:"頼【たの】もしいですね。これから 一緒【いっしょ】に 頑張【がんば】りましょう！",furigana:"頼もしいですね。これから 一緒に 頑張りましょう！",romaji:"Tanomoshii desu ne. Kore kara issho ni gambarimashou!",idText:"Sangat bisa diandalkan. Mulai sekarang mari kita bersemangat bersama!"}],vocab_breakdown:[{id:"vg-n4-00584",word:"品物",reading:"しなもの",romaji:"shinamono",meaning:"barang; produk",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"注文した品物が予定通り午前中に配達されました。",furigana:"注文した品物が予定通り午前中に配達されました。",romaji:"",idText:"Barang pesanan telah dikirim tiba pada pagi hari sesuai jadwal."}},{id:"vg-n4-00591",word:"サンドイッチ",reading:"サンドイッチ",romaji:"sandoicchi",meaning:"sandwich; roti lapis",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"コンビニでたまごとハムのサンドイッチを買いました。",furigana:"コンビニでたまごとハムのサンドイッチを買いました。",romaji:"",idText:"Saya membeli roti lapis telur dan daging ham di minimarket."}},{id:"vg-n4-00605",word:"伯父さん",reading:"おじさん",romaji:"ojisan",meaning:"paman; bapak-bapak",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"夏休みに田舎の伯父さんの家に泊まりに行きました。",furigana:"夏休みに田舎の伯父さんの家に泊まりに行きました。",romaji:"",idText:"Saat liburan musim panas saya pergi menginap di rumah paman di desa."}},{id:"vg-n4-00606",word:"伯母さん",reading:"おばさん",romaji:"obasan",meaning:"bibi; ibu-ibu",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"伯母さんは昔からお菓子作りがとても得意です。",furigana:"伯母さんは昔からお菓子作りがとても得意です。",romaji:"",idText:"Bibi saya sejak dahulu sangat mahir membuat kue-kue manis."}},{id:"vg-n4-00694",word:"～区",reading:"～く",romaji:"~ku",meaning:"distrik ..., wilayah kota ..., distrik administratif ...",pos:"counter",nuance:"Akhiran pembagian administratif untuk distrik atau wilayah bagian dalam kota besar di Jepang (seperti 23 distrik khusus Tokyo: 新宿区/Shinjuku-ku, 渋谷区/Shibuya-ku). Berfungsi mirip kecamatan atau daerah khusus setingkat munisipalitas.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私の会社は東京都港区にあります。",furigana:"私の会社は東京都港区にあります。",romaji:"",idText:"Kantor saya berada di distrik Minato, Tokyo."}},{id:"vg-n4-00701",word:"漫画",reading:"まんが",romaji:"manga",meaning:"komik, manga, kartun",pos:"noun",nuance:"Buku cerita bergambar gaya Jepang (komik/manga). Sering dijadikan bahan bacaan menyenangkan bagi pembelajar bahasa Jepang. Orang yang menggambar manga disebut 漫画家 (mangaka).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"子供の頃は毎週日本の漫画を夢中で読んでいました。",furigana:"子供の頃は毎週日本の漫画を夢中で読んでいました。",romaji:"",idText:"Waktu kecil saya asyik membaca komik Jepang setiap minggu."}},{id:"vg-n4-00703",word:"～会",reading:"～かい",romaji:"~kai",meaning:"pertemuan ..., perkumpulan ..., pesta ..., asosiasi ...",pos:"noun",nuance:"Akhiran pembentuk kata benda yang menyatakan suatu acara kumpul bersama, perkumpulan, atau organisasi. Contoh umum: 送別会 (soubetsu-kai / pesta perpisahan), 歓迎会 (kangei-kai / pesta penyambutan), 運動会 (undou-kai / festival olahraga), 勉強会 (benkyou-kai / kelompok belajar).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"来週の金曜日に新入社員のための歓迎会を開きます。",furigana:"来週の金曜日に新入社員のための歓迎会を開きます。",romaji:"",idText:"Pada hari Jumat minggu depan kami akan mengadakan pesta penyambutan untuk karyawan baru."}},{id:"vg-n4-00717",word:"正月",reading:"しょうがつ",romaji:"shougatsu",meaning:"Tahun Baru (khususnya bulan Januari / libur awal tahun di Jepang)",pos:"noun",nuance:"Perayaan tahun baru di Jepang, biasanya merujuk pada tiga hari pertama bulan Januari (三が日 / sanganichi) atau keseluruhan bulan Januari. Sering diucapkan dengan awalan hormat お正月 (oshougatsu). Tradisi khasnya meliputi makan osechi (おせち料理), berkunjung ke kuil (初詣 / hatsumoude), dan memberi uang saku tahun baru kepada anak-anak (お年玉 / otoshidama).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"お正月には実家に帰って家族とゆっくり過ごします。",furigana:"お正月には実家に帰って家族とゆっくり過ごします。",romaji:"",idText:"Saat Tahun Baru saya pulang ke kampung halaman dan menghabiskan waktu santai bersama keluarga."}},{id:"vg-n4-00720",word:"屋上",reading:"おくじょう",romaji:"okujou",meaning:"atap gedung, lantai paling atas (rooftop)",pos:"noun",nuance:"Bagian permukaan atas yang datar dari suatu bangunan bertingkat atau gedung sekolah/kantor/departemen store, sering dijadikan taman atap, tempat istirahat terbuka, atau arena bermain. Berbeda dengan 屋根 (yane) yang merujuk pada konstruksi fisik atap miring penutup rumah.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"天気がいいので、ビルの屋上でお弁当を食べました。",furigana:"天気がいいので、ビルの屋上でお弁当を食べました。",romaji:"",idText:"Karena cuacanya cerah, saya makan bekal di atap gedung."}},{id:"vg-n4-00724",word:"布団",reading:"ふとん",romaji:"futon",meaning:"futon, kasur/selimut tradisional Jepang",pos:"noun",nuance:"Perlengkapan tidur tradisional Jepang yang digelar di atas tatami. Terdiri dari 敷布団 (shikibuton / kasur alas bawah) dan 掛布団 (kakebuton / selimut tebal atas). Kolokasi penting: 布団を敷く (menggelar futon), 布団をたたむ (melipat futon), dan 布団を干す (menjemur futon).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"夜寝る前に、畳の部屋に布団を敷きます。",furigana:"夜寝る前に、畳の部屋に布団を敷きます。",romaji:"",idText:"Sebelum tidur malam, saya menggelar futon di kamar beralas tatami."}}],explanations:[{id:"exp-1",grammarId:"gn4-00007",title:"Pola: 〜によって / 〜による",formula:"N + によって / N + による + N",meaning:"tergantung ... / disebabkan oleh ... / berdasarkan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜によって / 〜による",idText:"tergantung ... / disebabkan oleh ... / berdasarkan ..."}],examples:[{jp:"国によって文化が違います。",romaji:"",idText:"Budaya berbeda-beda tergantung negaranya."},{jp:"病気によって命を失った人がいます。",romaji:"",idText:"Ada orang yang kehilangan nyawa karena penyakit."}]},{id:"exp-2",grammarId:"gn4-00008",title:"Pola: 〜に対して",formula:"N + に対して",meaning:"terhadap ... / kepada ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜に対して",idText:"terhadap ... / kepada ..."}],examples:[{jp:"すべての人に対して公平に接してください。",romaji:"",idText:"Tolong bersikap adil terhadap semua orang."},{jp:"アンケートに対して答えてください。",romaji:"",idText:"Tolong jawab kuesioner ini."}]},{id:"exp-3",grammarId:"gn4-00009",title:"Pola: 〜として",formula:"N + として",meaning:"sebagai ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜として",idText:"sebagai ..."}],examples:[{jp:"先生として、生徒に優しく接します。",romaji:"",idText:"Sebagai guru, saya bersikap ramah kepada murid."},{jp:"ボランティアとして参加しました。",romaji:"",idText:"Saya berpartisipasi sebagai relawan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk status kedudukan sebagai peserta pemagangan resmi.",sentencePrompt:"Istilah resmi bahasa Jepang untuk peserta pemagangan teknis kerja adalah:",options:["技能【ぎのう】実習生【じっしゅうせい】","留学生【りゅうがくせい】 (Pelajar asing)","観光客【かんこうきゃく】 (Wisatawan)","案内係【あんないがかり】 (Petugas informasi)"],correctAnswer:"技能【ぎのう】実習生【じっしゅうせい】",explanation:"技能実習生 (ginou jisshuusei) adalah sebutan resmi bagi peserta magang kerja industri di Jepang.",diagnosticFeedback:{"留学生【りゅうがくせい】 (Pelajar asing)":"Salah: 留学生 adalah mahasiswa atau pelajar sekolah.","観光客【かんこうきゃく】 (Wisatawan)":"Salah: 観光客 adalah turis pelancong.","案内係【あんないがかり】 (Petugas informasi)":"Salah: 案内係 adalah pemandu loket resepsionis."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kedudukan Peran): Lengkapi kalimat berbicara dalam kapasitas sebagai perwakilan kelompok.",sentencePrompt:"クラスの 代表【だいひょう】（　　）、先生【せんせい】に お礼【れい】を 言【い】いました。",options:["として","にとって","に対して","によって"],correctAnswer:"として",explanation:'Pola [Kata Benda] + として menyatakan kedudukan, fungsi, atau kapasitas peran resmi ("sebagai perwakilan").',diagnosticFeedback:{にとって:"Salah: にとって berarti menurut sudut pandang penilaian pribadi.",に対して:"Salah: に対して berarti terhadap suatu pihak/sasaran.",によって:"Salah: によって berarti disebabkan oleh atau tergantung."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Pola Modifikasi Agen Sebelum Kata Benda): Pilihlah bentuk penghubung yang tepat sebelum kata benda kecelakaan.",sentencePrompt:"大雨【おおあめ】（　　）被害【ひがい】が 広【ひろ】がって います。",options:["による","によって","として","に対して"],correctAnswer:"による",explanation:"Di depan kata benda (被害 higai = kerusakan), pola penanda sebab wajib berbentuk 〜による [N].",diagnosticFeedback:{によって:"Salah: によって digunakan langsung di depan kata kerja, bukan sebelum kata benda.",として:"Salah: として bermakna sebagai peran.",に対して:"Salah: に対して bermakna terhadap."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat bahwa kebiasaan hidup berbeda tergantung budayanya.",sentencePrompt:'Susunlah kata-kata: "Kebiasaan hidup berbeda tergantung negaranya".',options:["生活【せいかつ】の 習慣【しゅうかん】は 国【くに】に よって 違【ちが】います。","国【くに】に 生活【せいかつ】の 習慣【しゅうかん】は 違【ちが】います よって。","違【ちが】います 国【くに】に よって 生活【せいかつ】の 習慣【しゅうかん】は。","よって 国【くに】に 生活【せいかつ】の 習慣【しゅうかん】は 違【ちが】います。"],correctAnswer:"生活【せいかつ】の 習慣【しゅうかん】は 国【くに】に よって 違【ちが】います。",explanation:"Topik (生活の習慣は) + Kuni ni yotte (tergantung negaranya) + Chigaimasu (berbeda).",diagnosticFeedback:{"国【くに】に 生活【せいかつ】の 習慣【しゅうかん】は 違【ちが】います よって。":"Salah susun konektor di akhir.","違【ちが】います 国【くに】に よって 生活【せいかつ】の 習慣【しゅうかん】は。":"Salah posisi verba.","よって 国【くに】に 生活【せいかつ】の 習慣【しゅうかん】は 違【ちが】います。":"Salah susun frasa awal."},tokens:["生活【せいかつ】の 習慣【しゅうかん】は","国【くに】に","よって","違【ちが】います"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah makna kalimat "お客様に対して丁寧に話します".',sentencePrompt:'Kalimat "お客様【きゃくさま】に 対【たい】して 丁寧【ていねい】に 話【はな】します" menekankan:',options:["Sikap sopan dan perlakuan santun yang ditujukan kepada pihak pelanggan sebagai sasaran interaksi","Berbicara santai seperti kepada teman sebaya","Membicarakan keburukan pelanggan di belakang mereka","Menolak untuk melayani pembeli yang datang"],correctAnswer:"Sikap sopan dan perlakuan santun yang ditujukan kepada pihak pelanggan sebagai sasaran interaksi",explanation:"〜に対して menandai pihak atau sasaran penerima sikap, perlakuan, atau respon moral.",diagnosticFeedback:{"Berbicara santai seperti kepada teman sebaya":"Salah: Justru ditekankan berbicara sopan (丁寧に話します).","Membicarakan keburukan pelanggan di belakang mereka":"Salah: Bertolak belakang dengan arti teks.","Menolak untuk melayani pembeli yang datang":"Salah: Tidak ada makna penolakan."}}],can_do_challenge:{statement:"Bisa berbicara mewakili posisi peserta magang teknis dalam sambutan resmi.",situation:"Diminta memperkenalkan diri dan menyampaikan komitmen pada hari pertama masuk kerja.",promptTask:"Katakan bahwa sebagai peserta magang kamu akan berjuang sekuat tenaga!",modelAnswer:"実習生【じっしゅうせい】として 一生懸命【いっしょうけんめい】 頑張【がんば】ります。",modelAnswerId:"Sebagai peserta pemagangan saya akan berusaha dengan sungguh-sungguh sekuat tenaga.",culturalEtiquette:"Berdirilah tegak, tatap hadirin dengan senyum mantap, dan bungkukkan badan 30 derajat usai berucap.",skillUnlocked:["Menguasai identitas kedudukan formal via N + to shite","Mampu menghubungkan relasi sebab variasi via ni yotte / ni yoru"]},pocket_summary:{keyFormula:"[N] として (sebagai peran) / [N] によって (tergantung / oleh) / [N] による [N] / [N] に対して (terhadap sasaran)",coreWords:["じっしゅうせい","だいひょう","きそく","たいど"],coreWarning:"N to shite = kapasitas resmi; N ni totte = menurut sudut pandang opini.",quickDialogue:"A: 代表として？ → B: はい、代表として挨拶します。"}}},n={"les-n4-u10-01":{pedagogical_framework:{what:{summary:"Mengekspresikan kontras kekecewaan antara harapan vs kenyataan yang bertolak belakang (~noni) dan konjungsi kejutan tak terduga (tokoroga = namun di luar dugaan).",canDo:"Bisa menceritakan kronologi kendala kiriman paket yang tidak kunjung tiba padahal sudah dipesan sejak lama.",targetPatterns:["[Verba/Adjektiva Bentuk Biasa / N + na] のに (padahal ... / mengharapkan A tapi malah terjadi B)","文１。ところが、文２。 (Namun di luar dugaan, ...)","約束【やくそく】したのに、来【こ】なかった (padahal sudah janji, tapi tidak datang)"],coreVocabSample:["にもつ","とどく","れんらく","へんじ","ちゅうもん","ざんねん"]},sensei_context:{sceneIntro:"Di kantor divisi logistik asrama. Budi menunggu paket buku pelajaran yang dipesan seminggu lalu dengan layanan kilat tetapi belum juga sampai di depan pintu.",dailyMission:"Gunakan partikel penegas kekecewaan 〜のに untuk menceritakan kesenjangan antara fakta riil dan ekspektasi.",whyOrder:"Dalam kehidupan nyata, tidak semua hal berjalan mulus sesuai rencana. Pembelajar harus mampu mengungkapkan rasa kecewa atau anomali tanpa terdengar mengumpat kasar."},cultural_notes:{title:"Ekspresi Kekecewaan Halus dalam Budaya Keluhan Jepang (不満の遠回しな表現)",etiquette:"Ketika mengajukan komplain atau menanyakan pesanan yang tertunda, gunakan akhiran 〜のに... dengan nada menggantung halus agar terkesan mengundang klarifikasi, bukan menuduh.",taboos:"Jangan menggunakan kata benda langsung sebelum noni tanpa partikel な (seperti 雨のに - salah!). Kata benda dan kata sifat-na wajib menggunakan な: 雨なのに, 暇なのに."},pronunciation_tips:{title:'Nada Menggantung pada Partikel Kontras "Noni"',moraNote:'Pada akhir kalimat bernuansa kecewa, vokal [i] pada "noni..." diucapkan sedikit memanjang dan merendah lembut.',soundTip:'Kata sambung "Tokoroga" diucapkan dengan jeda tegas setelah koma untuk menandai titik balik kejadian.'},common_pitfalls:[{title:'Lupa Menambahkan "Na" untuk Kata Benda dan Sifat-Na Sebelum "Noni"',caseScenario:'Mengatakan "padahal hari Minggu" langsung menempelkan noni.',pitfallWarning:'"日曜日【にちようび】のに、仕事【しごと】が あります。"',rightSolution:'"日曜日【にちようび】なのに、仕事【しごと】が あります。"',explanation:"Kata benda (N) dan Adjektiva-na wajib menyisipkan な sebelum noni: 日曜日なのに (padahal hari Minggu)."},{title:"Tertukar Antara 〜のに (Kekecewaan Kontras) vs 〜ても (Meskipun Netral)",caseScenario:"Mengungkapkan rasa heran kecewa karena sudah minum obat tapi belum sembuh.",pitfallWarning:'"薬【くすり】を 飲【の】んでも、熱【ねつ】が 下【さ】がりません。" (Ini netral objektif)',rightSolution:'"薬【くすり】を 飲【の】んだのに、熱【ねつ】が 下【さ】がりません。" (Menekankan kekecewaan emosional)',explanation:"〜ても bersifat konsesi logis umum. 〜のに sarat dengan emosi subjektif kekecewaan, kejutan, atau rasa tidak puas dari pembicara."}],who_and_when:{situational_context:"Menanyakan status pesanan toko online yang molor, menceritakan sudah belajar giat tapi nilai ujian turun, kendala janji temu.",social_relations:"Sangat lazim dipakai saat curhat kepada rekan kerja, mentor asrama, maupun pengajuan keluhan sopan.",when_not_to_use:"Jangan gunakan 〜のに untuk hal-hal yang hasilnya justru sangat menyenangkan (tidak dipakai untuk berita gembira)."},scenario:{title:"Komplain Kiriman Buku Pelajaran yang Terlambat",setting:"Lobi kantor pos asrama, pukul 17.00",narrative:"Budi menceritakan kepada Sakura bahwa paket bukunya belum tiba padahal sudah dijanjikan sampai kemarin sore."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Mentor Asrama",avatar:"👩‍🏫",jp:"ブディさん、浮【う】かない 顔【かお】を していますね。どうしたの？",furigana:"ブディさん、浮かない 顔を していますね。どうしたの？",romaji:"Budi-san, ukanai kao o shite imasu ne. Dou shita no?",idText:"Budi-san, wajahmu tampak murung ya. Ada apa gerangan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"先週【せんしゅう】 頼【たの】んだ 専門書【せんもんしょ】が、まだ 届【とど】かないんです。",furigana:"先週 頼んだ 専門書が、まだ 届かないんです。",romaji:"Senshuu tanonda senmonsho ga, mada todokanai n desu.",idText:"Buku referensi kejuruan yang saya pesan minggu lalu belum sampai juga."},{id:"d3",speaker:"Sakura",speakerRole:"Mentor Asrama",avatar:"👩‍🏫",jp:"速達【そくたつ】で 送【おく】ってもらったんじゃなかった？",furigana:"速達で 送ってもらったんじゃなかった？",romaji:"Sokutatsu de okutte morattan janakatta?",idText:"Bukankah kemarin kamu minta dikirimkan pakai pos kilat khusus?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい。昨日【きのう】 着【つ】く はずだったのに、まだ 配達【はいたつ】中【ちゅう】の ままなんです。",furigana:"はい。昨日 着く はずだったのに、まだ 配達中の ままなんです。",romaji:"Hai. Kinou tsuku hazu datta noni, mada haitatsu-chuu no mama na n desu.",idText:"Iya. Padahal seharusnya kemarin sudah sampai, tetapi statusnya masih tertahan dalam pengiriman."},{id:"d5",speaker:"Sakura",speakerRole:"Mentor Asrama",avatar:"👩‍🏫",jp:"追跡【ついせき】番号【ばんごう】で 調【しら】べてみた？",furigana:"追跡番号で 調べてみた？",romaji:"Tsuiseki bangou de shirabete mita?",idText:"Sudah coba kamu lacak dengan nomor resi pelacakannya?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"電話【でんわ】した ところ、大雪【おおゆき】で トラックが 止【と】まっているそうです。",furigana:"電話した ところ、大雪で トラックが 止まっているそうです。",romaji:"Denwa shita tokoro, ooyuki de torakku ga tomatte iru sou desu.",idText:"Saat saya menelepon, kabarnya truk pengangkut tertahan karena badai salju lebat."}],vocab_breakdown:[{id:"vg-n4-00056",word:"労働",reading:"ろうどう",romaji:"roudou",meaning:"buruh, pekerjaan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎日の長時間の労働で少し疲れています。",furigana:"毎日の長時間の労働で少し疲れています。",romaji:"",idText:"Saya merasa agak lelah karena bekerja berjam-jam setiap hari."}},{id:"vg-n4-00061",word:"受ける",reading:"うける",romaji:"ukeru",meaning:"menerima, mengikuti (ujian)",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"来月日本語能力試験を受けるつもりです。",furigana:"来月日本語能力試験を受けるつもりです。",romaji:"",idText:"Saya berencana mengikuti ujian JLPT bulan depan."}},{id:"vg-n4-00062",word:"受け取る",reading:"うけとる",romaji:"uketoru",meaning:"menerima",pos:"verb-u",nuance:"受け取る = menerima (barang/dokumen). Berbeda: もらう = menerima (hadiah dari orang).",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"荷物を受け取りました。",furigana:"荷物を受け取りました。",romaji:"",idText:"Saya sudah menerima paketnya."}},{id:"vg-n4-00114",word:"連れる",reading:"つれる",romaji:"tsureru",meaning:"membawa (seseorang)",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"休日に弟を動物園へ連れて行きました。",furigana:"休日に弟を動物園へ連れて行きました。",romaji:"",idText:"Pada hari libur saya mengajak adik ke kebun binatang."}},{id:"vg-n4-00116",word:"頼む",reading:"たのむ",romaji:"tanomu",meaning:"meminta tolong, memohon",pos:"verb-u",nuance:"頼む = meminta tolong/memesan. 仕事を頼む = minta bantu kerja.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"引っ越しの手伝いを友だちに頼みました。",furigana:"引っ越しの手伝いを友だちに頼みました。",romaji:"",idText:"Saya minta tolong teman untuk bantu pindahan."}},{id:"vg-n4-00117",word:"頼る",reading:"たよる",romaji:"tayoru",meaning:"bergantung pada, mengandalkan",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"困ったときはいつでも私を頼ってください。",furigana:"困ったときはいつでも私を頼ってください。",romaji:"",idText:"Jika dalam kesulitan, andalkan saya kapan saja."}},{id:"vg-n4-00130",word:"決める",reading:"きめる",romaji:"kimeru",meaning:"memutuskan, menentukan",pos:"verb-ru",nuance:"決める = memutuskan/menentukan (transitif). Intransitif: 決まる. 決心する = bertekad.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"旅行の日程を決めました。",furigana:"旅行の日程を決めました。",romaji:"",idText:"Saya sudah menentukan jadwal perjalanan."}},{id:"vg-n4-00131",word:"決まる",reading:"きまる",romaji:"kimaru",meaning:"diputuskan, menjadi pasti",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"来週の会議の時間がようやく決まりました。",furigana:"来週の会議の時間がようやく決まりました。",romaji:"",idText:"Waktu pertemuan minggu depan akhirnya telah diputuskan."}},{id:"vg-n4-00231",word:"壊す",reading:"こわす",romaji:"kowasu",meaning:"merusak, menghancurkan (transitif)",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"弟が遊んでいておもちゃを壊してしまいました。",furigana:"弟が遊んでいておもちゃを壊してしまいました。",romaji:"",idText:"Adik merusak mainan saat sedang bermain."}},{id:"vg-n4-00232",word:"壊れる",reading:"こわれる",romaji:"kowareru",meaning:"rusak (intransitif)",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"長年使っていた洗濯機が急に壊れました。",furigana:"長年使っていた洗濯機が急に壊れました。",romaji:"",idText:"Mesin cuci yang dipakai bertahun-tahun tiba-tiba rusak."}}],explanations:[{id:"exp-1",grammarId:"gn4-00059",title:"Pola: 〜のに (kontras/kekecewaan)",formula:"V/Adj plain / N + なのに + 文",meaning:"padahal ... / meskipun ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜のに (kontras/kekecewaan)",idText:"padahal ... / meskipun ..."}],examples:[{jp:"あんなに練習したのに、試合に負けました。",romaji:"",idText:"Padahal sudah berlatih keras, tapi kalah dalam pertandingan."},{jp:"今日は休みなのに、仕事の電話が来た。",romaji:"",idText:"Padahal hari ini libur, tapi ada telepon kerja."}]},{id:"exp-2",grammarId:"gn4-00060",title:"Pola: ところが",formula:"文1。ところが、文2。",meaning:"namun / akan tetapi (kontras tidak terduga)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"ところが",idText:"namun / akan tetapi (kontras tidak terduga)"}],examples:[{jp:"試験は簡単だと思っていた。ところが、とても難しかった。",romaji:"",idText:"Saya pikir ujiannya mudah. Tapi ternyata sangat sulit."},{jp:"急いで駅に行った。ところが、電車はもう出ていた。",romaji:"",idText:"Buru-buru pergi ke stasiun. Tapi ternyata kereta sudah berangkat."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata yang mencerminkan rasa kecewa atau sayang sekali atas hasil yang tidak terwujud.",sentencePrompt:"Ungkapan perasaan kecewa atau disayangkan dalam bahasa Jepang adalah:",options:["残念【ざんねん】です (Sangat disayangkan/kecewa)","安心【あんしん】です (Merasa lega)","満足【まんぞく】です (Sangat puas)","楽しみです (Sangat menantikan)"],correctAnswer:"残念【ざんねん】です (Sangat disayangkan/kecewa)",explanation:"残念 (zannen) sering berpadu dengan kalimat berpartikel 〜のに untuk mengutarakan rasa kecewa.",diagnosticFeedback:{"安心です (Merasa lega)":"Salah: 安心 berarti tenang melegakan hati.","満足です (Sangat puas)":"Salah: 満足 berarti puas atas hasil baik.","楽しみです (Sangat menantikan)":"Salah: 楽しみ berarti antusias menunggu masa depan.","安心【あんしん】です (Merasa lega)":'Jebakan Partikel: Pilihan "安心【あんしん】です (Merasa lega)" tidak tepat untuk peran gramatikal kalimat ini.',"満足【まんぞく】です (Sangat puas)":'Jebakan Partikel: Pilihan "満足【まんぞく】です (Sangat puas)" tidak tepat untuk peran gramatikal kalimat ini.'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Sambung Noni): Lengkapi kalimat rasa heran badan belum sembuh padahal sudah minum obat.",sentencePrompt:"薬【くすり】を（　　）のに、まだ 熱【ねつ】が 下【さ】がりません。",options:["飲【の】んだ","飲【の】みます","飲【の】んで","飲【の】もう"],correctAnswer:"飲【の】んだ",explanation:"Pola kontras kekecewaan adalah [Verba Bentuk Biasa (Futsuukei)] + のに (飲んだのに = padahal sudah minum obat).",diagnosticFeedback:{飲みます:"Salah: Bentuk masu tidak disambung langsung ke noni.",飲んで:"Salah: Bentuk te tidak bersambung langsung ke noni.",飲もう:"Salah: Bentuk ikoukei tidak cocok untuk aksi yang sudah terlaksana.","飲【の】みます":'Jebakan Konjugasi: Bentuk predikat "飲【の】みます" tidak sesuai dengan kala waktu atau tingkat kesantunan.',"飲【の】んで":'Jebakan Partikel: Pilihan "飲【の】んで" tidak tepat untuk peran gramatikal kalimat ini.',"飲【の】もう":'Pilihan "飲【の】もう" keliru karena tidak selaras dengan kaidah pola gn4-00059.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel Kata Sifat-Na & Benda Sebelum Noni): Tentukan penyambung kata sifat-na yang benar.",sentencePrompt:"彼【かれ】は 日本語【にほんご】が 上手【じょうず】（　　）のに、全然【ぜんぜん】 話【はな】そうと しません。",options:["な","の","だ","に"],correctAnswer:"な",explanation:"Untuk Kata Sifat-Na dan Kata Benda, wajib menggunakan な sebelum partikel のに (上手なのに).",diagnosticFeedback:{の:"Salah: の dipakai sebelum tame ni, bukan sebelum noni.",だ:"Salah: だ berubah menjadi な sebelum noni.",に:"Salah: に bukan partikel penyambung sebelum noni."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat konjungsi kontras kejutan tak terduga.",sentencePrompt:'Susunlah kata-kata: "Saya sudah menunggu di stasiun. Namun di luar dugaan, teman saya tidak kunjung datang".',options:["駅【えき】で 待【ま】っていました。 ところが、 友達【ともだち】が 来【こ】なかったのです。","ところが、 駅【えき】で 待【ま】っていました。 友達【ともだち】が 来【こ】なかったのです。","友達【ともだち】が 駅【えき】で 待【ま】っていました。 来【こ】なかったのです。 ところが、","来【こ】なかったのです。 ところが、 友達【ともだち】が 駅【えき】で 待【ま】っていました。"],correctAnswer:"駅【えき】で 待【ま】っていました。 ところが、 友達【ともだち】が 来【こ】なかったのです。",explanation:"Kalimat harapan 1 (待っていました) + Konjungsi kontras (ところが、) + Fakta tak terduga (友達が来なかった).",diagnosticFeedback:{"ところが、 駅【えき】で 待【ま】っていました。 友達【ともだち】が 来【こ】なかったのです。":"Salah penempatan konjungsi di awal.","友達【ともだち】が 駅【えき】で 待【ま】っていました。 来【こ】なかったのです。 ところが、":"Salah urutan konjungsi di akhir.","来【こ】なかったのです。 ところが、 友達【ともだち】が 駅【えき】で 待【ま】っていました。":"Salah susun urutan logis cerita."},tokens:["駅【えき】で 待【ま】っていました。","ところが、","友達【ともだち】が","来【こ】なかったのです。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah beban emosional pada kalimat berakhiran "...noni".',sentencePrompt:'Kalimat "今日【きょう】は 日曜日【にちようび】なのに…" yang terhenti di tengah menyiratkan:',options:["Rasa kecewa atau mengeluh karena hari Minggu yang seharusnya libur malah harus tetap bekerja atau tertimpa urusan lain","Rasa gembira luar biasa karena bisa berlibur seharian","Pertanyaan tentang hari apa besok pagi","Kepastian bahwa hari Minggu adalah hari ibadah"],correctAnswer:"Rasa kecewa atau mengeluh karena hari Minggu yang seharusnya libur malah harus tetap bekerja atau tertimpa urusan lain",explanation:"Kalimat yang diakhiri dengan 〜のに... mencerminkan keluhan halus atas kenyataan yang tidak adil atau bertentangan dengan harapan wajar.",diagnosticFeedback:{"Rasa gembira luar biasa karena bisa berlibur seharian":"Salah: のに tidak dipakai untuk merayakan kegembiraan.","Pertanyaan tentang hari apa besok pagi":"Salah: Ini bukan kalimat tanya.","Kepastian bahwa hari Minggu adalah hari ibadah":"Salah: Ini bukan makna kontekstualnya."}}],can_do_challenge:{statement:"Bisa menceritakan kronologi kendala kiriman barang yang tidak kunjung tiba padahal sudah dipesan.",situation:"Melaporkan kepada instruktur asrama bahwa pesanan suku cadang seragam kerja belum kunjung tiba.",promptTask:"Katakan bahwa padahal kamu sudah memesannya minggu lalu, tetapi belum sampai juga!",modelAnswer:"先週【せんしゅう】 注文【ちゅうもん】したのに、まだ 届【とど】かないんです。",modelAnswerId:"Padahal saya sudah memesannya minggu lalu, tetapi belum sampai juga.",culturalEtiquette:"Gunakan nada suara mengadu ramah dan tunjukkan bukti struk pemesanan dari ponsel.",skillUnlocked:["Menguasai ekspresi kontras kekecewaan 〜のに","Mampu menghubungkan peralihan tak terduga via ところが"]},pocket_summary:{keyFormula:"[Bentuk Biasa / N+な] + のに (padahal) / 文1。ところが、文2。 (namun di luar dugaan)",coreWords:["にもつ","とどく","ちゅうもん","ざんねん"],coreWarning:"Ingat partikel な sebelum noni untuk kata benda: 雨なのに (bukan 雨のに).",quickDialogue:"A: 薬飲んだ？ → B: 飲んだのに治りません。"}},"les-n4-u10-02":{pedagogical_framework:{what:{summary:"Menyatakan konsesi pantang menyerah meski dalam rintangan berat (~te mo / Adj-kute mo / N-demo), konfirmasi retoris atau kejutan pembuktian (~janai ka / dewa nai ka), dan partikel penegas ekstrem (~demo = bahkan ... sekalipun).",canDo:"Bisa menegaskan semangat kerja pantang menyerah meski kondisi hujan deras dan mengonfirmasi pencapaian tim.",targetPatterns:["[Verba-te] も / [I-Adj -> kute] も (meskipun / walaupun ... tetap)","[Kata Benda / Na-Adj] でも (meskipun berupa ... / bahkan ... sekalipun)","[Kalimat Biasa] じゃないか / ではないか (bukankah ... ?! / ternyata ... !)","どんなに 大変【たいへん】でも (betapa pun beratnya)"],coreVocabSample:["あめ","たいへん","あきらめない","せいこう","どりょく","がんばる"]},sensei_context:{sceneIntro:"Di lokasi pelatihan luar ruangan pabrik saat hujan rintik. Budi dan Kenji tetap antusias menyelesaikan modul simulasi pemadam api darurat.",dailyMission:"Gunakan 〜ても untuk menyatakan tekad pantang menyerah dan 〜じゃないか untuk memberikan semangat kejutan.",whyOrder:"Pekerja dan pembelajar di Jepang sangat menghargai etos gigih (Ganbari). Pola konsesi 〜ても adalah kalimat wajib untuk menunjukkan komitmen tinggi."},cultural_notes:{title:"Etos Ketekunan Pantang Menyerah (不屈の精神 - Nanakorobi Yaoki)",etiquette:'Ungkapan "Ame ga futte mo gambarimasu" (Meski hujan turun saya akan tetap bersemangat) dipandang sangat positif oleh atasan sebagai cerminan jiwa bertanggung jawab.',taboos:'Jangan menggunakan kata "janai ka!" dengan nada membentak marah kepada orang yang lebih tua. Nada intonasi menentukan apakah ini pujian hangat atau teguran ketus.'},pronunciation_tips:{title:'Intonasi Penegasan pada Pola Konsesi "-Te mo"',moraNote:'Tekankan sedikit kata penguat seperti "donna ni" atau "tatoe" di awal kalimat.',soundTip:'Pada frasa pujian kejutan "...janai ka!", akhiri dengan nada naik ceria.'},common_pitfalls:[{title:"Salah Mengubah Kata Sifat-i ke Bentuk Konsesi (Kutemo)",caseScenario:'Ingin mengatakan "meskipun mahal saya tetap ingin beli".',pitfallWarning:'"高【たか】いでも、買【か】いたいです。"',rightSolution:'"高【たか】くても、買【か】いたいです。"',explanation:"Kata sifat-i diubah menjadi bentuk [kute] sebelum partikel mo: 高い -> 高くても. Partikel でも hanya untuk kata benda dan kata sifat-na."},{title:"Tertukar Antara 〜ても (Kondisi Hipotetis Walaupun) vs 〜のに (Fakta Realita Padahal)",caseScenario:"Mengatakan tekad bahwa besok sekalipun hujan akan tetap pergi.",pitfallWarning:'"明日【あした】 雨【あめ】が 降【ふ】るのに、行【い】きます。"',rightSolution:'"明日【あした】 雨【あめ】が 降【ふ】っても、行【い】きます。"',explanation:"〜のに hanya dipakai untuk fakta yang SUDAH atau SEDANG terjadi secara nyata. Untuk pengandaian masa depan yang belum tentu terjadi, wajib memakai 〜ても."}],who_and_when:{situational_context:"Pernyataan komitmen kerja proyek lapangan, menyemangati rekan yang lelah, merayakan hasil simulasi yang ternyata sukses.",social_relations:"Sangat sering diucapkan sesama rekan seperjuangan untuk saling menguatkan mental tim.",when_not_to_use:'Jangan gunakan konsesi 〜ても untuk alasan yang membenarkan kecerobohan K3 (misal: "meski bahaya saya tetap terobos" - terlarang!).'},scenario:{title:"Simulasi Tanggap Darurat di Tengah Hujan",setting:"Lapangan uji keselamatan K3 pabrik, pukul 16.00",narrative:"Budi dan Kenji berhasil menyelesaikan latihan pemadaman api tepat waktu meskipun cuaca diguyur hujan gerimis."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Rekan Kerja Senior",avatar:"🧑‍💻",jp:"ブディ、雨【あめ】が 強【つよ】く なってきたよ。大丈夫【だいじょうぶ】かい？",furigana:"ブディ、雨が 強く なってきたよ。大丈夫かい？",romaji:"Budi, ame ga tsuyoku natte kita yo. Daijoubu kai?",idText:"Budi, hujannya mulai bertambah deras lho. Kamu tidak apa-apa?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 雨【あめ】が 降【ふ】っても、最後【さいご】まで やり抜【ぬ】きます！",furigana:"はい！ 雨が 降っても、最後まで やり抜きます！",romaji:"Hai! Ame ga futte mo, saigo made yarinukimasu!",idText:"Iya! Walaupun hujan turun, saya akan tetap menuntaskannya sampai titik akhir!"},{id:"d3",speaker:"Kenji",speakerRole:"Rekan Kerja Senior",avatar:"🧑‍💻",jp:"よし、ホースの バルブを 開【あ】けて！ 標的【ひょうてき】に 水【みず】を 当【あ】てるんだ。",furigana:"よし、ホースの バルブを 開けて！ 標的に 水を 当てるんだ。",romaji:"Yoshi, ho-su no barubu o akete! Hyouteki ni mizu o ateru n da.",idText:"Bagus, buka katup selang pemadamnya! Arahkan semprotan air tepat ke sasaran."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"標的【ひょうてき】が 倒【たお】れました！ タイムは どうですか。",furigana:"標的が 倒れました！ タイムは どうですか。",romaji:"Hyouteki ga taoremashita! Taimu wa dou desu ka.",idText:"Targetnya sudah berhasil roboh! Bagaimana catatan waktunya?"},{id:"d5",speaker:"Kenji",speakerRole:"Rekan Kerja Senior",avatar:"🧑‍💻",jp:"すごい！ 目標【もくひょう】の ３分【さんぷん】以内【いない】に 終【お】わったじゃないか！ 合格【ごうかく】だよ。",furigana:"すごい！ 目標の ３分以内に 終わったじゃないか！ 合格だよ。",romaji:"Sugoi! Mokuhyou no sanpun inai ni owatta janai ka! Goukaku da yo.",idText:"Hebat sekali! Bukankah kamu berhasil menuntaskannya dalam waktu kurang dari target 3 menit?! Kamu lulus!"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"やった！ どんなに 難【むずか】しくても、諦【あきら】めずに 努力【どりょく】して よかったです！",furigana:"やった！ どんなに 難しくても、諦めずに 努力して よかったです！",romaji:"Yatta! Donna ni muzukashikute mo, akiramezu ni doryoku shite yokatta desu!",idText:"Hore berhasil! Betapa pun sulitnya, syukurlah saya berusaha tanpa menyerah!"}],vocab_breakdown:[{id:"vg-n4-00991",word:"思う",reading:"おもう",romaji:"omou",meaning:"berpikir",pos:"verb-u",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"晴れだと思うよ。",furigana:"晴れだと思うよ。",romaji:"",idText:"I think it will be sunny."}},{id:"vg-n4-01007",word:"乾く",reading:"かわく",romaji:"kawaku",meaning:"menjadi kering",pos:"verb-u",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"そのぬれたシャツはすぐに乾くだろう。",furigana:"そのぬれたシャツはすぐに乾くだろう。",romaji:"",idText:"The wet shirt will soon dry up."}},{id:"vg-n4-01041",word:"原因",reading:"げんいん",romaji:"gen'in",meaning:"penyebab; sumber",pos:"verb-suru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"火事の原因はだいたいわかっている。",furigana:"火事の原因はだいたいわかっている。",romaji:"",idText:"Hampir tidak ada keraguan tentang penyebab kebakaran itu."}},{id:"vg-n4-01050",word:"故障",reading:"こしょう",romaji:"koshou",meaning:"kerusakan",pos:"verb-suru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"車が故障したので遅れました。",furigana:"車が故障したので遅れました。",romaji:"",idText:"I was late because my car broke down."}},{id:"vg-n4-01105",word:"心配",reading:"しんぱい",romaji:"shinpai",meaning:"khawatir",pos:"verb-suru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"その男の子は心配して病気になった。",furigana:"その男の子は心配して病気になった。",romaji:"",idText:"Anak laki-laki itu jatuh sakit karena rasa cemas."}},{id:"vg-n4-01125",word:"説明",reading:"せつめい",romaji:"setsumei",meaning:"penjelasan",pos:"verb-suru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あなたはそれをどう説明しますか。",furigana:"あなたはそれをどう説明しますか。",romaji:"",idText:"Bagaimana Anda menjelaskan hal itu?"}},{id:"vg-n4-01127",word:"世話",reading:"せわ",romaji:"sewa",meaning:"menjaga",pos:"verb-suru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あなたはペットの世話ができない。",furigana:"あなたはペットの世話ができない。",romaji:"",idText:"You can't care for pets."}},{id:"vg-n4-01133",word:"育てる",reading:"そだてる",romaji:"sodateru",meaning:"belakang",pos:"verb-ru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"クッキーはケイトによって育てられた。",furigana:"クッキーはケイトによって育てられた。",romaji:"",idText:"Cookie was raised by Kate."}},{id:"vg-n4-01134",word:"卒業",reading:"そつぎょう",romaji:"sotsugyou",meaning:"kelulusan",pos:"verb-suru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私はポップ・ミュージックはそろそろ卒業しようと思っているの。",furigana:"私はポップ・ミュージックはそろそろ卒業しようと思っているの。",romaji:"",idText:"I feel I'm growing out of pop music."}},{id:"vg-n4-01175",word:"連れる",reading:"つれる",romaji:"tsureru",meaning:"memimpin",pos:"verb-ru",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"でもさ、母を連れて行かなくてはいけないんだ。",furigana:"でもさ、母を連れて行かなくてはいけないんだ。",romaji:"",idText:"But, I have to take my mother."}}],explanations:[{id:"exp-1",grammarId:"gn4-00037",title:"Pola: 〜ても / 〜でも (konsesi)",formula:"Vて + も / Adj-くて + も / N + でも",meaning:"meskipun ... / walaupun ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ても / 〜でも (konsesi)",idText:"meskipun ... / walaupun ..."}],examples:[{jp:"雨が降っても、試合は続けます。",romaji:"",idText:"Meskipun hujan, pertandingan dilanjutkan."},{jp:"忙しくても、健康に気をつけてください。",romaji:"",idText:"Walaupun sibuk, jaga kesehatan ya."}]},{id:"exp-2",grammarId:"gn4-00077",title:"Pola: 〜じゃないか / ではないか",formula:"V/Adj plain + じゃないか / ではないか",meaning:"bukankah ... ? / ternyata ... !",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜じゃないか / ではないか",idText:"bukankah ... ? / ternyata ... !"}],examples:[{jp:"もう少し考えれば分かるじゃないか。",romaji:"",idText:"Bukankah kalau dipikir lebih jauh pasti tahu?"},{jp:"あれ、田中さんじゃないか！",romaji:"",idText:"Eh, bukankah itu Tanaka-san!"}]},{id:"exp-3",grammarId:"gn4-00003",title:"Pola: 〜でも (bahkan)",formula:"N + でも",meaning:"bahkan ... pun / ... sekalipun",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜でも (bahkan)",idText:"bahkan ... pun / ... sekalipun"}],examples:[{jp:"これは子どもでもできます。",romaji:"",idText:"Bahkan anak-anak pun bisa melakukan ini."},{jp:"お茶でも飲みましょうか。",romaji:"",idText:"Bagaimana kalau minum teh atau sesuatu?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata yang tepat untuk usaha sungguh-sungguh pantang menyerah.",sentencePrompt:"Istilah dalam bahasa Jepang untuk usaha keras dan daya upaya maksimal adalah:",options:["努力【どりょく】 (Usaha keras/ikhtiar)","遠慮【えんりょ】 (Sikap sungkan)","後悔【こうかい】 (Penyesalan)","油断【ゆだん】 (Keteledoran)"],correctAnswer:"努力【どりょく】 (Usaha keras/ikhtiar)",explanation:"努力 (doryoku) adalah ikhtiar usaha keras berkesinambungan untuk mencapai tujuan.",diagnosticFeedback:{"遠慮【えんりょ】 (Sikap sungkan)":"Salah: 遠慮 adalah rasa sungkan atau menahan diri.","後悔【こうかい】 (Penyesalan)":"Salah: 後悔 adalah rasa menyesal.","油断【ゆだん】 (Keteledoran)":"Salah: 油断 adalah lengah atau ceroboh."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Konsesi Kata Sifat): Lengkapi kalimat tekad belajar meski materi sangat sulit.",sentencePrompt:"いくら 日本語【にほんご】が（　　）、最後【さいご】まで 諦【あきら】めません。",options:["難【むずか】しくても","難【むずか】しいでも","難【むずか】しくて","難【むずか】しいのに"],correctAnswer:"難【むずか】しくても",explanation:"Kata Sifat-i diubah menjadi bentuk [kute] + も: 難しくても = walaupun sulit.",diagnosticFeedback:{難しいでも:"Salah: でも hanya dipakai untuk kata benda dan kata sifat-na, bukan kata sifat-i.",難しくて:"Salah: Hanya bentuk sambung te biasa tanpa makna konsesi walaupun.",難しいのに:'Salah: のに tidak dipasangkan dengan kata penguat pengandaian "ikura".',"難【むずか】しいでも":'Jebakan Partikel: Pilihan "難【むずか】しいでも" tidak tepat untuk peran gramatikal kalimat ini.',"難【むずか】しくて":'Pilihan "難【むずか】しくて" keliru karena tidak selaras dengan kaidah pola gn4-00037.',"難【むずか】しいのに":'Jebakan Partikel: Pilihan "難【むずか】しいのに" tidak tepat untuk peran gramatikal kalimat ini.'}},{id:"drill-3",type:"trap_detect",instruction:'Langkah 3 (Pola Penegas Ekstrem): Pilihlah partikel yang tepat untuk "bahkan anak kecil sekalipun bisa".',sentencePrompt:"この スマホは 簡単【かんたん】ですから、子供【こども】（　　）使【つか】えます。",options:["でも","のに","より","ほど"],correctAnswer:"でも",explanation:'Partikel でも pada kata benda dapat berfungsi menegaskan contoh ekstrem: "bahkan anak kecil pun bisa menggunakannya".',diagnosticFeedback:{のに:"Salah: のに bermakna padahal.",より:"Salah: より menandai pembanding komparasi.",ほど:"Salah: ほど menandai tingkat perkiraan derajad."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat pujian kejutan bahwa masakan tersebut ternyata sangat lezat.",sentencePrompt:'Susunlah kata-kata: "Bukankah masakan ini ternyata sangat lezat?!".',options:["この 料理【りょうり】、 とても おいしい じゃないか！","とても おいしい じゃないか！ この 料理【りょうり】、","じゃないか！ とても おいしい この 料理【りょうり】、","この 料理【りょうり】、 じゃないか！ とても おいしい"],correctAnswer:"この 料理【りょうり】、 とても おいしい じゃないか！",explanation:"Topik (この料理) + Keterangan (とても) + Sifat (おいしい) + Janai ka (bukankah ternyata...!).",diagnosticFeedback:{"とても おいしい じゃないか！ この 料理【りょうり】、":"Salah susun terbalik.","じゃないか！ とても おいしい この 料理【りょうり】、":"Salah posisi partikel penutup.","この 料理【りょうり】、 じゃないか！ とても おいしい":"Salah struktur penegasan."},tokens:["この 料理【りょうり】、","とても","おいしい","じゃないか！"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah fungsi partikel "じゃないか" dalam obrolan sesama rekan kerja.',sentencePrompt:'Ketika Kenji berkata kepada Budi "目標に間に合ったじゃないか！", maknanya adalah:',options:["Pujian gembira yang mengonfirmasi bahwa Budi ternyata berhasil melampaui target dengan sukses","Kemarahan karena Budi datang terlambat melampaui target waktu","Pertanyaan formal yang meragukan apakah tugasnya sudah selesai","Larangan untuk tidak menyelesaikan tugas tepat waktu"],correctAnswer:"Pujian gembira yang mengonfirmasi bahwa Budi ternyata berhasil melampaui target dengan sukses",explanation:"〜じゃないか dalam intonasi ceria berfungsi sebagai ungkapan rasa kagum dan konfirmasi kejutan positif (ternyata kamu berhasil!).",diagnosticFeedback:{"Kemarahan karena Budi datang terlambat melampaui target waktu":"Salah: Ini bukan kalimat kemarahan.","Pertanyaan formal yang meragukan apakah tugasnya sudah selesai":"Salah: Ini ungkapan seruan penegasan, bukan keraguan.","Larangan untuk tidak menyelesaikan tugas tepat waktu":"Salah: Tidak ada makna larangan sama sekali."}}],can_do_challenge:{statement:"Bisa menegaskan semangat kerja pantang menyerah meski kondisi hujan deras.",situation:"Saat shift kerja diwarnai cuaca buruk dan rekan kerja bertanya apakah kamu masih kuat.",promptTask:"Tegaskan bahwa walaupun hujan deras kamu akan tetap berjuang sekuat tenaga!",modelAnswer:"雨【あめ】が 降【ふ】っても、一生懸命【いっしょうけんめい】 頑張【がんば】ります！",modelAnswerId:"Walaupun hujan turun, saya akan tetap berusaha sekuat tenaga!",culturalEtiquette:"Ucapkan dengan kepalan tangan mantap dan tatapan optimis penuh semangat.",skillUnlocked:["Menguasai ekspresi konsesi komitmen [V-te] mo","Mampu menggunakan seruan afirmatif kejutan 〜じゃないか"]},pocket_summary:{keyFormula:"[V-te] も / [Adj-kute] も / [N] でも (walaupun) / [Kalimat] じゃないか (bukankah ternyata!)",coreWords:["あめ","たいへん","どりょく","せいこう"],coreWarning:"Kata sifat-i = takakute mo (bukan takai demo). Partikel demo khusus kata benda/sifat-na.",quickDialogue:"A: 大変だよ？ → B: 大変でも頑張ります！"}}},e={"les-n4-u11-01":{pedagogical_framework:{what:{summary:"Bentuk kausatif (使役形 shiekikei: verba Gol 1 -aseru, Gol 2 -saseru, Gol 3 saseru/kosaseru), permohonan izin cuti diri sendiri (~sasete kudasai / moraitai), dan kewajiban mutlak (~nakereba naranai / nakya).",canDo:"Bisa memohon izin pulang lebih awal (soutai) kepada atasan saat sakit demam dan memahami aturan absensi.",targetPatterns:["[Verba Kausatif-te] ください / いただけませんか (izinkan saya melakukan ...)","[Verba-nai -> nakereba] ならない / いけない (wajib / harus melakukan)","[Verba-nai -> nakya / nakucha] (harus ... - kasual)","[Orang] に [Aksi] を させる (membuat / menyuruh seseorang melakukan)"],coreVocabSample:["そうたい","きゅうか","やすむ","ねつ","きょか","たいちょう"]},sensei_context:{sceneIntro:"Di ruang kantor kepala bagian (Kachou). Budi merasa badannya sangat panas menggigil saat jam kerja siang dan ingin memohon izin pulang lebih awal untuk berobat.",dailyMission:'Gunakan bentuk permohonan izin kausatif "Yasumasete itadakemasen ka" untuk memohon izin pulang secara profesional.',whyOrder:"Memohon izin cuti darurat (soutai/yuukyuu) menuntut etika Keigo dan kausatif tingkat tinggi agar atasan memahami kondisi kesehatan bawahan dengan empati."},cultural_notes:{title:"Tata Cara Izin Pulang Cepat (早退 - Soutai) di Perusahaan Jepang",etiquette:'Ketika sakit di tempat kerja, jangan langsung berkemas pulang. Temui atasan langsung, laporkan suhu tubuh, dan katakan: "Taichou ga suguremasen node, soutai sasete itadakemasen ka?".',taboos:"Jangan memakai bentuk kausatif perintah kepada atasan. Bentuk kausatif V-sasete HANYA dipakai untuk merendahkan diri sendiri saat memohon izin melakukan sesuatu."},pronunciation_tips:{title:'Pelafalan Kausatif Izin Lembut "-Sasete kudasai"',moraNote:"Ya-su-ma-se-te memiliki 5 mora teratur tanpa aksen kejut.",soundTip:'Pada saat mengucapkan "moushiwake arimasen", tundukkan kepala dengan santun.'},common_pitfalls:[{title:"Salah Memilih Subjek Pemohon dalam Pola Kausatif Izin",caseScenario:'Memohon izin pulang tapi keliru menggunakan bentuk perintah biasa "kaette kudasai".',pitfallWarning:'"早【はや】く 帰【かえ】って ください。" (Artinya: Menyuruh atasan pulang!)',rightSolution:'"早【はや】く 帰【かえ】らせて ください。" (Benar: Izinkan saya yang pulang)',explanation:"[V-te] ください berarti menyuruh lawan bicara melakukan aksi. [V-sasete] ください berarti memohon izin agar DIRI SENDIRI yang diizinkan melakukan aksi tersebut."},{title:"Tertukar Antara 〜なければならない (Wajib Formal) vs 〜なくてもいい (Boleh Tidak)",caseScenario:"Mengatakan harus minum obat 3 kali.",pitfallWarning:'"薬【くすり】を 飲【の】まなくても ならない。"',rightSolution:'"薬【くすり】を 飲【の】まなければ ならない。"',explanation:"Rumus keharusan wajib adalah [V-nai -> nakereba] + ならない / いけない."}],who_and_when:{situational_context:"Memohon izin pulang sakit (soutai), mengajukan cuti tahunan (yuukyuu kyuuka), menjelaskan kewajiban membawa paspor saat ke imigrasi.",social_relations:"Sangat vital dan baku diucapkan oleh bawahan kepada manajer/supervisor.",when_not_to_use:"Jangan memakai ragam kasual nakya kepada direktur utama perusahaan."},scenario:{title:"Permohonan Izin Pulang Cepat Karena Demam Tinggi",setting:"Meja manajer lantai 1, pukul 14.00",narrative:"Budi mengalami demam 38 derajat dan memohon izin kepada Tanaka-kachou untuk pulang lebih awal memeriksakan diri ke klinik."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"田中【たなか】課長【かちょう】、今【いま】 お時間【じかん】 よろしいでしょうか。",furigana:"田中課長、今 お時間 よろしいでしょうか。",romaji:"Tanaka-kachou, ima ojikan yoroshii deshou ka.",idText:"Tanaka-kachou, apakah saat ini Bapak ada waktu luang sebentar?"},{id:"d2",speaker:"Tanaka",speakerRole:"Kepala Bagian",avatar:"🧑‍💼",jp:"ええ、どうしましたか、ブディさん。顔【かお】が 赤【あか】いですよ。",furigana:"ええ、どうしましたか、ブディさん。顔が 赤いですよ。",romaji:"Ee, dou shimashita ka, Budi-san. Kao ga akai desu yo.",idText:"Iya, ada apa Budi-san? Wajahmu tampak memerah lho."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"熱【ねつ】を 測【はか】ったところ、３８度【さんじゅうはちど】 ありました。病院【びょういん】へ 行【い】かなければ なりません。",furigana:"熱を 測ったところ、３８度 ありました。病院へ 行かなければ なりません。",romaji:"Netsu o hakatta tokoro, sanjuuhachido arimashita. Byouin e ikanakereba narimasen.",idText:"Saat saya ukur suhu tubuh, ternyata mencapai 38 derajat. Saya harus pergi memeriksakan diri ke rumah sakit."},{id:"d4",speaker:"Tanaka",speakerRole:"Kepala Bagian",avatar:"🧑‍💼",jp:"それは 高熱【こうねつ】ですね！ 無理【むり】を しては いけませんよ。",furigana:"それは 高熱ですね！ 無理を しては いけませんよ。",romaji:"Sore wa kounetsu desu ne! Muri o shite wa ikemasen yo.",idText:"Wah itu demam tinggi! Kamu tidak boleh memaksakan diri bekerja lho."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"大変【たいへん】 申【もう】し訳【わけ】ありませんが、今日【きょう】は 早退【そうたい】させて いただけないでしょうか。",furigana:"大変 申し訳ありませんが、今日は 早退させて いただけないでしょうか。",romaji:"Taihen moushiwake arimasen ga, kyou wa soutai sasete itadakenai deshou ka.",idText:"Sungguh mohon maaf sebesar-besarnya, apakah kiranya hari ini saya diizinkan untuk pulang lebih awal?"},{id:"d6",speaker:"Tanaka",speakerRole:"Kepala Bagian",avatar:"🧑‍💼",jp:"もちろんです。すぐ 帰【かえ】って 診察【しんさつ】を 受【う】けてください。お大事【だいじ】に！",furigana:"もちろんです。すぐ 帰って 診察を 受けてください。お大事に！",romaji:"Mochiron desu. Sugu kaette shinsatsu o ukete kudasai. Odaiji ni!",idText:"Tentu saja boleh. Segeralah pulang dan periksakan diri ke dokter. Semoga lekas sembuh ya!"}],vocab_breakdown:[{id:"vg-n4-00003",word:"運動",reading:"うんどう",romaji:"undou",meaning:"olahraga, gerakan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"健康のために毎朝運動をしています。",furigana:"健康のために毎朝運動をしています。",romaji:"",idText:"Saya berolahraga setiap pagi demi kesehatan."}},{id:"vg-n4-00009",word:"走る",reading:"はしる",romaji:"hashiru",meaning:"berlari",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"電車に遅れそうなので急いで走りました。",furigana:"電車に遅れそうなので急いで走りました。",romaji:"",idText:"Saya berlari terburu-buru karena hampir terlambat naik kereta."}},{id:"vg-n4-00010",word:"走り回る",reading:"はしりまわる",romaji:"hashirimawaru",meaning:"berlarian",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"子どもたちが庭を元気に走り回っています。",furigana:"子どもたちが庭を元気に走り回っています。",romaji:"",idText:"Anak-anak berlarian dengan ceria di halaman."}},{id:"vg-n4-00012",word:"起こす",reading:"おこす",romaji:"okosu",meaning:"membangunkan",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎朝七時に母が私を起こしてくれます。",furigana:"毎朝七時に母が私を起こしてくれます。",romaji:"",idText:"Setiap pagi jam tujuh ibu membangunkan saya."}},{id:"vg-n4-00013",word:"起こる",reading:"おこる",romaji:"okoru",meaning:"terjadi",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"この交差点で大きな事故が起こりました。",furigana:"この交差点で大きな事故が起こりました。",romaji:"",idText:"Sebuah kecelakaan besar terjadi di persimpangan jalan ini."}},{id:"vg-n4-00175",word:"落ち着く",reading:"おちつく",romaji:"ochitsuku",meaning:"tenang, stabil",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"深呼吸をして気持ちを落ち着けました。",furigana:"深呼吸をして気持ちを落ち着けました。",romaji:"",idText:"Saya menarik napas dalam-dalam untuk menenangkan perasaan."}},{id:"vg-n4-00434",word:"楽しむ",reading:"たのしむ",romaji:"tanoshimu",meaning:"menikmati",pos:"verb-u",nuance:"楽しむ = menikmati (aktif). Berbeda: 楽しい (adj) = menyenangkan.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"旅行を思いっきり楽しみました。",furigana:"旅行を思いっきり楽しみました。",romaji:"",idText:"Saya benar-benar menikmati perjalanan itu."}},{id:"vg-n4-00444",word:"挨拶",reading:"あいさつ",romaji:"aisatsu",meaning:"salam; sapaan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎朝近所の人に笑顔で挨拶をしています。",furigana:"毎朝近所の人に笑顔で挨拶をしています。",romaji:"",idText:"Setiap pagi saya menyapa warga tetangga sekitar dengan senyum ramah."}},{id:"vg-n4-00456",word:"教育",reading:"きょういく",romaji:"kyouiku",meaning:"pendidikan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"親は子どもの教育のためにたくさんのお金を使います。",furigana:"親は子どもの教育のためにたくさんのお金を使います。",romaji:"",idText:"Orang tua menyisihkan banyak biaya untuk membiayai edukasi anak-anaknya."}},{id:"vg-n4-00458",word:"競争",reading:"きょうそう",romaji:"kyousou",meaning:"persaingan; kompetisi",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"運動会でクラスメートと足の速さを競争しました。",furigana:"運動会でクラスメートと足の速さを競争しました。",romaji:"",idText:"Kami saling bersaing adu ketangkasan lari bersama teman di festival olahraga."}}],explanations:[{id:"exp-1",grammarId:"gn4-00029",title:"Pola: Vさせる (kausatif)",formula:"V-ない-form → replace ない dengan せる/させる",meaning:"menyuruh ... / membiarkan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vさせる (kausatif)",idText:"menyuruh ... / membiarkan ..."}],examples:[{jp:"母は子どもに野菜を食べさせます。",romaji:"",idText:"Ibu menyuruh anaknya makan sayur."},{jp:"彼女に好きな仕事を選ばせました。",romaji:"",idText:"Saya membiarkan dia memilih pekerjaan yang disukai."}]},{id:"exp-2",grammarId:"gn4-00030",title:"Pola: Vさせられる (kausatif-pasif)",formula:"Vさせる → Vさせられる",meaning:"terpaksa/dipaksa melakukan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"Vさせられる (kausatif-pasif)",idText:"terpaksa/dipaksa melakukan ..."}],examples:[{jp:"残業をさせられました。",romaji:"",idText:"Saya dipaksa lembur."},{jp:"子どもの頃、嫌いな野菜を食べさせられました。",romaji:"",idText:"Waktu kecil, saya dipaksa makan sayur yang tidak saya suka."}]},{id:"exp-3",grammarId:"gn4-00023",title:"Pola: 〜なければならない (dan variasinya)",formula:"Vない → Vなければ + ならない/いけない",meaning:"harus ... / wajib ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜なければならない (dan variasinya)",idText:"harus ... / wajib ..."}],examples:[{jp:"明日は早く起きなければなりません。",romaji:"",idText:"Besok saya harus bangun pagi."},{jp:"今週は残業しなくてはいけない。",romaji:"",idText:"Minggu ini harus lembur."}]},{id:"exp-4",grammarId:"gn4-00024",title:"Pola: 〜なきゃ / 〜なくちゃ (kasual)",formula:"Vない → Vなきゃ / Vなくちゃ",meaning:"harus ... (kasual)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜なきゃ / 〜なくちゃ (kasual)",idText:"harus ... (kasual)"}],examples:[{jp:"もう行かなきゃ。",romaji:"",idText:"Harus pergi sekarang."},{jp:"宿題やらなくちゃいけない。",romaji:"",idText:"Harus kerjakan PR."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk pulang kerja lebih awal sebelum jam selesai shift.",sentencePrompt:"Istilah resmi dalam dunia kerja Jepang untuk izin pulang mendahului jam kerja adalah:",options:["早退【そうたい】 (Pulang cepat)","遅刻【ちこく】 (Terlambat datang)","残業【ざんぎょう】 (Lembur kerja)","出張【しゅっちょう】 (Dinas luar)"],correctAnswer:"早退【そうたい】 (Pulang cepat)",explanation:"早退 (soutai) adalah istilah sah kepegawaian untuk izin meninggalkan tempat kerja lebih awal.",diagnosticFeedback:{"遅刻【ちこく】 (Terlambat datang)":"Salah: 遅刻 adalah datang terlambat.","残業【ざんぎょう】 (Lembur kerja)":"Salah: 残業 adalah lembur bekerja melewati jam reguler.","出張【しゅっちょう】 (Dinas luar)":"Salah: 出張 adalah perjalanan dinas tugas kantor."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Permohonan Izin Kausatif): Lengkapi permohonan santun agar diri sendiri diizinkan beristirahat.",sentencePrompt:"体調【たいちょう】が 悪【わる】いので、今日【きょう】は（　　）いただけませんか。",options:["休【やす】ませて","休【やす】んで","休【やす】まされて","休【やす】む"],correctAnswer:"休【やす】ませて",explanation:"Verba Golongan 1: 休む -> kausatif 休ませる -> bentuk te 休ませて いただけませんか = sudikah kiranya mengizinkan saya istirahat.",diagnosticFeedback:{休んで:"Salah: 休んでいただけませんか berarti memohon lawan bicara yang beristirahat.",休まされて:"Salah: Ini bentuk pasif kausatif (dipaksa istirahat).",休む:"Salah: Bentuk kamus tidak bersambung ke itadakemasen ka.","休【やす】んで":'Jebakan Partikel: Pilihan "休【やす】んで" tidak tepat untuk peran gramatikal kalimat ini.',"休【やす】まされて":'Pilihan "休【やす】まされて" keliru karena tidak selaras dengan kaidah pola gn4-00029.',"休【やす】む":'Pilihan "休【やす】む" keliru karena tidak selaras dengan kaidah pola gn4-00029.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Formula Keharusan Mutlak): Pilihlah rumus yang tepat untuk kewajiban mematuhi aturan kerja.",sentencePrompt:"会社【かいしゃ】の ルールは 絶対【ぜったい】に 守【まも】ら（　　）なりません。",options:["なければ","なくても","ないで","ないなら"],correctAnswer:"なければ",explanation:"Pola keharusan mutlak hukum/aturan adalah [V-nai -> nakereba] + ならない (守らなければなりません).",diagnosticFeedback:{なくても:"Salah: なくてもいい bermakna tidak perlu/opsional.",ないで:"Salah: ないで bermakna tanpa melakukan.",ないなら:"Salah: bukan rumus keharusan narimasen."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat memohon izin untuk mengemukakan pendapat dalam rapat.",sentencePrompt:'Susunlah kata-kata: "Izinkan saya menyampaikan pendapat sebentar".',options:["私【わたし】に 意見【いけん】を 言【い】わせて ください。","意見【いけん】を 私【わたし】に ください 言【い】わせて。","言【い】わせて 私【わたし】に 意見【いけん】を ください。","ください 私【わたし】に 意見【いけん】を 言【い】わせて。"],correctAnswer:"私【わたし】に 意見【いけん】を 言【い】わせて ください。",explanation:"Subjek izin (私に) + Objek (意見を) + Kausatif-te (言わせて) + ください.",diagnosticFeedback:{"意見【いけん】を 私【わたし】に ください 言【い】わせて。":"Salah susun predikat.","言【い】わせて 私【わたし】に 意見【いけん】を ください。":"Salah posisi verba sambung.","ください 私【わたし】に 意見【いけん】を 言【い】わせて。":"Salah penempatan kata permohonan di awal."},tokens:["私【わたし】に","意見【いけん】を","言【い】わせて","ください"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Bedakan fungsi "帰ってください" vs "帰らせてください".',sentencePrompt:'Perbedaan mendasar antara "帰ってください" dan "帰らせてください" adalah:',options:['"帰ってください" menyuruh lawan bicara pulang, sedangkan "帰らせてください" memohon izin agar diri sendiri yang pulang',"Keduanya memiliki arti yang persis sama tanpa perbedaan",'"帰らせてください" adalah kalimat perintah kasar untuk mengusir tamu','"帰ってください" hanya boleh diucapkan di rumah sakit'],correctAnswer:'"帰ってください" menyuruh lawan bicara pulang, sedangkan "帰らせてください" memohon izin agar diri sendiri yang pulang',explanation:"Bentuk kausatif -sasete kudasai memindahkan agen tindakan kepada pembicara sebagai pihak yang memohon izin.",diagnosticFeedback:{"Keduanya memiliki arti yang persis sama tanpa perbedaan":"Salah: Subjek pelakunya bertolak belakang.",'"帰らせてください" adalah kalimat perintah kasar untuk mengusir tamu':"Salah: Justru permohonan izin santun untuk diri sendiri.",'"帰ってください" hanya boleh diucapkan di rumah sakit':"Salah: Bisa diucapkan di mana saja."}}],can_do_challenge:{statement:"Bisa memohon izin pulang lebih awal (soutai) kepada atasan saat sakit demam.",situation:"Merasa kepala pusing dan demam di tengah shift kerja kantor pabrik.",promptTask:"Mohonlah kepada atasan agar diizinkan pulang lebih awal hari ini!",modelAnswer:"体調【たいちょう】が 悪【わる】いので、早退【そうたい】させて いただけないでしょうか。",modelAnswerId:"Karena kondisi badan saya kurang sehat, sudikah kiranya mengizinkan saya pulang lebih awal?",culturalEtiquette:"Ucapkan dengan nada santun merendah dan bungkukkan badan tanda permohonan tulus.",skillUnlocked:["Menguasai permohonan izin kausatif V-sasete itadakemasen ka","Mampu mengekspresikan keharusan mutlak V-nakereba narimasen"]},pocket_summary:{keyFormula:"[V-Kausatif-te] + ください / いただけませんか (izinkan saya) / [V-nakereba] ならない (wajib)",coreWords:["そうたい","きゅうか","やすむ","ねつ"],coreWarning:"Kaette kudasai = menyuruh orang lain pulang; Kaerasete kudasai = memohon izin agar diri sendiri yang pulang.",quickDialogue:"A: どうしたの？ → B: 早退させていただけませんか。"}},"les-n4-u11-02":{pedagogical_framework:{what:{summary:"Larangan mutlak keselamatan K3 (~te wa ikenai), bentuk perintah tegas (命令形 meireikei), bentuk larangan keras (禁止形 kinshikei: V-ru + na), serta instruksi otoritatif santun (~nasai).",canDo:"Bisa membaca papan peringatan K3 di area konstruksi dan mematuhi instruksi keselamatan darurat seketika.",targetPatterns:["[Verba-te] は いけません / いけない (dilarang keras / tidak boleh)","[Verba Bentuk Perintah] (Meireikei: 押せ！ 逃げろ！ 止まれ！)","[Verba Kamus] + な！ (Kinshikei: 触るな！ 入るな！ 動かすな！)","[Verba Masu-stem] + なさい (lakukanlah - instruksi terarah)"],coreVocabSample:["きけん","ちゅうい","さわるな","はいってはいけない","ヘルメット","あんぜん"]},sensei_context:{sceneIntro:"Di area bengkel alat berat dan konstruksi. Tanaka memandu Budi mengenakan helm keselamatan dan membaca rambu-rambu bahaya tegangan tinggi.",dailyMission:"Pahami makna rambu Meireikei dan Kinshikei untuk menyelamatkan nyawa seketika dalam situasi darurat K3.",whyOrder:"Di pabrik dan lokasi konstruksi Jepang, instruksi keselamatan darurat tidak menggunakan kalimat sopan yang panjang. Pembelajar WAJIB mengenali bentuk perintah/larangan instan demi keselamatan jiwa."},cultural_notes:{title:"Komunikasi Keselamatan Kerja K3 Jepang (安全第一 - Anzen Daiichi)",etiquette:'Dalam kondisi darurat kebakaran atau mesin macet, teriakan seperti "Nigero!" (Lari!) atau "Sawaru na!" (Jangan sentuh!) bukan tanda kemarahan, melainkan instruksi penyelamatan nyawa darurat.',taboos:"Jangan pernah menggunakan Meireikei (perintah kasar) dalam percakapan kerja sehari-hari yang tenang kepada siapa pun."},pronunciation_tips:{title:'Artikulasi Rambu Larangan Singkat "Kinshikei"',moraNote:"Bentuk kamus + な diucapkan dengan nada tegas menghentak: Sa-wa-ru-na! Ha-i-ru-na!",soundTip:"Bentuk 〜てはいけません diucapkan dengan nada datar tegas tanpa intonasi keraguan."},common_pitfalls:[{title:'Tertukar Antara Partikel Larangan "Na!" vs Partikel Afirmatif Santai "Naa"',caseScenario:'Mendengar teriakan "Sawaru na!" tetapi mengiranya sebagai obrolan santai.',pitfallWarning:'"触【さわ】るな (Sawaru na)" dianggap obrolan santai.',rightSolution:'"触【さわ】るな！" adalah larangan mutlak: "Dilarang menyentuh sama sekali!".',explanation:"Verba kamus + な pendek menghentak adalah bentuk larangan keras (禁止形 kinshikei) yang menandakan bahaya maut."},{title:'Memakai Bentuk "~Nasai" Kepada Atasan atau Senior',caseScenario:'Meminta atasan membaca laporan: "Yominasai".',pitfallWarning:'"課長【かちょう】、この 報告書【ほうこくしょ】を 読【よ】みなさい。"',rightSolution:'"課長【かちょう】、この 報告書【ほうこくしょ】を お読【よ】みください。"',explanation:"〜なさい adalah perintah dari figur berwenang (orang tua ke anak, dokter ke pasien, guru ke murid). Kepada atasan, wajib menggunakan Keigo."}],who_and_when:{situational_context:"Papan rambu peringatan area konstruksi, prosedur evakuasi gempa/kebakaran, briefing K3 sebelum masuk bengkel perakitan.",social_relations:"Digunakan oleh instruktur K3 dan supervisor pabrik saat mengarahkan keselamatan teknis.",when_not_to_use:"Jangan gunakan bentuk Meireikei/Kinshikei dalam pergaulan santai normal."},scenario:{title:"Inspeksi Rambu K3 di Bengkel Alat Berat",setting:"Area fabrikasi logam pabrik, pukul 08.15",narrative:'Tanaka mengajarkan arti rambu bahaya "Sawaru na" dan memastikan Budi memakai helm keselamatan sebelum melangkah ke area mesin pres.'}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor K3",avatar:"🧑‍💼",jp:"ブディさん、作業場【さぎょうば】に 入【はい】る 前【まえ】に、ヘルメットを 着用【ちゃくよう】しなさい。",furigana:"ブディさん、作業場に 入る 前に、ヘルメットを 着用しなさい。",romaji:"Budi-san, sagyouba ni hairu mae ni, herumetto o chakuyou shinasai.",idText:"Budi-san, sebelum masuk ke area bengkel kerja, kenakanlah helm keselamatanmu."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ あご紐【ひも】も しっかり 締【し】めました。安全【あんぜん】第一【だいいち】ですね。",furigana:"はい！ あご紐も しっかり 締めました。安全第一ですね。",romaji:"Hai! Agohimo mo shikkari shimemashita. Anzen daiichi desu ne.",idText:"Baik! Tali dagu helm juga sudah saya kencangkan dengan rapat. Utamakan keselamatan ya."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor K3",avatar:"🧑‍💼",jp:"あそこに「立入【たちい】り禁止【きんし】・入【はい】るな」と 書【か】いて ありますね。何【なに】が あっても 入【はい】っては いけませんよ。",furigana:"あそこに「立入り禁止・入るな」と 書いて ありますね。何が あっても 入っては いけませんよ。",romaji:'Asoko ni "Tachiiri kinshi, hairu na" to kaite arimasu ne. Nani ga atte mo haitte wa ikemasen yo.',idText:'Di sebelah sana tertulis "Dilarang Masuk (Hairu na)" kan ya. Apa pun yang terjadi, kamu tidak boleh masuk ke sana lho.'},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました。黄色【きいろ】い 線【せん】の 外側【そとがわ】を 歩【ある】きます。",furigana:"承知しました。黄色い 線の 外側を 歩きます。",romaji:"Shouchi shimashita. Kiiroi sen no sotogawa o arukimasu.",idText:"Saya pahami. Saya akan selalu berjalan di sisi luar garis penanda kuning."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor K3",avatar:"🧑‍💼",jp:"機械【きかい】が 動【うご】いている 時【とき】は、絶対に 触【さわ】るな！ 挟【はさ】まれる 危険【きけん】が あるからね。",furigana:"機械が 動いている 時は、絶対に 触るな！ 挟まれる 危険が あるからね。",romaji:"Kikai ga ugoite iru toki wa, zettai ni sawaru na! Hasamareru kiken ga aru kara ne.",idText:"Saat mesin sedang bergerak, jangan sekali-kali menyentuhnya! Karena ada bahaya terjepit."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 指差【ゆびさ】し呼称【こしょう】で 確認【かくにん】してから 行動【こうどう】します。",furigana:"はい！ 指差し呼称で 確認してから 行動します。",romaji:"Hai! Yubisashi koshou de kakunin shite kara koudou shimasu.",idText:"Baik! Saya akan memastikan dengan tunjuk-sebut (Yubisashi Koshou) baru bertindak."}],vocab_breakdown:[{id:"vg-n4-00070",word:"医療",reading:"いりょう",romaji:"iryou",meaning:"perawatan medis",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本の医療技術はとても高いです。",furigana:"日本の医療技術はとても高いです。",romaji:"",idText:"Teknologi perawatan medis di Jepang sangat tinggi."}},{id:"vg-n4-00071",word:"薬",reading:"くすり",romaji:"kusuri",meaning:"obat",pos:"noun",nuance:"薬 (くすり) = obat. 薬を飲む = minum obat. 薬が効く = obat manjur.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"熱があるので薬を飲みました。",furigana:"熱があるので薬を飲みました。",romaji:"",idText:"Saya demam jadi minum obat."}},{id:"vg-n4-00072",word:"薬局",reading:"やっきょく",romaji:"yakkyoku",meaning:"apotek",pos:"noun",nuance:"薬局 = apotek. 薬局で薬を買う = beli obat di apotek.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"駅の前に薬局があります。",furigana:"駅の前に薬局があります。",romaji:"",idText:"Ada apotek di depan stasiun."}},{id:"vg-n4-00073",word:"薬指",reading:"くすりゆび",romaji:"kusuriyubi",meaning:"jari manis",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"左手の薬指に結婚指輪をはめました。",furigana:"左手の薬指に結婚指輪をはめました。",romaji:"",idText:"Saya mengenakan cincin pernikahan di jari manis tangan kiri."}},{id:"vg-n4-00075",word:"頭痛",reading:"ずつう",romaji:"zutsuu",meaning:"sakit kepala",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"ひどい頭痛がするので少し休みます。",furigana:"ひどい頭痛がするので少し休みます。",romaji:"",idText:"Saya ingin istirahat sebentar karena mengalami sakit kepala yang parah."}},{id:"vg-n4-00076",word:"腹痛",reading:"ふくつう",romaji:"fukutsuu",meaning:"sakit perut",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"冷たいものを食べすぎて腹痛になりました。",furigana:"冷たいものを食べすぎて腹痛になりました。",romaji:"",idText:"Saya sakit perut karena kebanyakan makan makanan dingin."}},{id:"vg-n4-00119",word:"地区",reading:"ちく",romaji:"chiku",meaning:"distrik, wilayah",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この地区は夜になるととても静かになります。",furigana:"この地区は夜になるととても静かになります。",romaji:"",idText:"Distrik kawasan ini menjadi sangat tenang jika malam tiba."}},{id:"vg-n4-00121",word:"地図",reading:"ちず",romaji:"chizu",meaning:"peta",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"スマホの地図を見ながら目的地へ歩きました。",furigana:"スマホの地図を見ながら目的地へ歩きました。",romaji:"",idText:"Saya berjalan menuju tempat tujuan sambil melihat peta di ponsel pintar."}},{id:"vg-n4-00285",word:"ストレス",reading:"ストレス",romaji:"sutoresu",meaning:"stres",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"散歩をして仕事のストレスを発散しました。",furigana:"散歩をして仕事のストレスを発散しました。",romaji:"",idText:"Saya berjalan-jalan santai untuk melepaskan stres akibat pekerjaan."}},{id:"vg-n4-00325",word:"ぐっすり",reading:"ぐっすり",romaji:"gussuri",meaning:"tidur nyenyak",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"昨日は疲れていたので朝までぐっすり眠りました。",furigana:"昨日は疲れていたので朝までぐっすり眠りました。",romaji:"",idText:"Karena kemarin lelah, saya tidur sangat pulas sampai pagi."}}],explanations:[{id:"exp-1",grammarId:"gn4-00027",title:"Pola: 〜てはいけない",formula:"Vて + はいけません / はいけない",meaning:"tidak boleh ... / dilarang ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜てはいけない",idText:"tidak boleh ... / dilarang ..."}],examples:[{jp:"テストのとき、辞書を使ってはいけません。",romaji:"",idText:"Saat ujian, tidak boleh menggunakan kamus."},{jp:"嘘をついてはいけないよ。",romaji:"",idText:"Tidak boleh berbohong."}]},{id:"exp-2",grammarId:"gn4-00056",title:"Pola: 命令形 (bentuk perintah)",formula:"V1 (godan): Vう-row (e.g. 書く→書け); V2 (ichidan): Vる→Vろ",meaning:"lakukan! (perintah)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"命令形 (bentuk perintah)",idText:"lakukan! (perintah)"}],examples:[{jp:"ここに座れ！",romaji:"",idText:"Duduk di sini!"},{jp:"早く起きろ！",romaji:"",idText:"Bangun cepat!"}]},{id:"exp-3",grammarId:"gn4-00057",title:"Pola: 禁止形 (bentuk larangan)",formula:"Vる (dictionary form) + な",meaning:"jangan! / dilarang!",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"禁止形 (bentuk larangan)",idText:"jangan! / dilarang!"}],examples:[{jp:"入るな！",romaji:"",idText:"Jangan masuk!"},{jp:"ここに車を止めるな。",romaji:"",idText:"Jangan parkir mobil di sini."}]},{id:"exp-4",grammarId:"gn4-00058",title:"Pola: 〜なさい",formula:"V-ます語幹 + なさい",meaning:"lakukan! (perintah sopan/otoritatif)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜なさい",idText:"lakukan! (perintah sopan/otoritatif)"}],examples:[{jp:"早く宿題をしなさい。",romaji:"",idText:"Cepat kerjakan PR."},{jp:"もっとゆっくり食べなさい。",romaji:"",idText:"Makan lebih pelan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah slogan keselamatan kerja terpenting di Jepang.",sentencePrompt:"Slogan keselamatan nomor satu di seluruh pabrik dan lokasi konstruksi Jepang adalah:",options:["安全【あんぜん】第一【だいいち】 (Utamakan keselamatan)","利益【りえき】第一 (Utamakan laba)","能率【のうりつ】第一 (Utamakan kecepatan)","遠慮【えんりょ】第一 (Utamakan rasa sungkan)"],correctAnswer:"安全【あんぜん】第一【だいいち】 (Utamakan keselamatan)",explanation:"安全第一 (Anzen Daiichi = Safety First) adalah nilai mutlak tanpa kompromi di industri Jepang.",diagnosticFeedback:{"利益第一 (Utamakan laba)":"Salah: Keselamatan jiwa selalu berada di atas laba bisnis.","能率第一 (Utamakan kecepatan)":"Salah: Kecepatan tidak boleh mengorbankan keselamatan.","遠慮第一 (Utamakan rasa sungkan)":"Salah: Dalam bahaya K3 tidak boleh sungkan melapor.","利益【りえき】第一 (Utamakan laba)":'Pilihan "利益【りえき】第一 (Utamakan laba)" keliru karena tidak selaras dengan kaidah pola gn4-00027.',"能率【のうりつ】第一 (Utamakan kecepatan)":'Pilihan "能率【のうりつ】第一 (Utamakan kecepatan)" keliru karena tidak selaras dengan kaidah pola gn4-00027.',"遠慮【えんりょ】第一 (Utamakan rasa sungkan)":'Pilihan "遠慮【えんりょ】第一 (Utamakan rasa sungkan)" keliru karena tidak selaras dengan kaidah pola gn4-00027.'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Rambu Larangan Keras): Pilihlah bentuk larangan keras (Kinshikei) dari kata 触る (menyentuh).",sentencePrompt:'Papan tanda bahaya listrik tegangan tinggi: "危【あぶ】ない！ （　　）！"',options:["触【さわ】るな","触【さわ】りなさい","触【さわ】らないで","触【さわ】れ"],correctAnswer:"触【さわ】るな",explanation:"Bentuk Larangan Keras (Kinshikei): Verba Kamus + な！ (触るな = Jangan sentuh!).",diagnosticFeedback:{触りなさい:'Salah: Ini adalah instruksi "sentuhlah!".',触らないで:"Salah: Ini adalah permohonan santun, bukan rambu peringatan instan.",触れ:'Salah: Ini adalah bentuk perintah "sentuh!".',"触【さわ】りなさい":'Pilihan "触【さわ】りなさい" keliru karena tidak selaras dengan kaidah pola gn4-00027.',"触【さわ】らないで":'Jebakan Partikel: Pilihan "触【さわ】らないで" tidak tepat untuk peran gramatikal kalimat ini.',"触【さわ】れ":'Pilihan "触【さわ】れ" keliru karena tidak selaras dengan kaidah pola gn4-00027.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Formula Larangan Formal): Lengkapi kalimat larangan mengambil foto di area militer/pabrik rahasia.",sentencePrompt:"ここで 写真【しゃしん】を 撮【と】って（　　）いけません。",options:["は","も","が","を"],correctAnswer:"は",explanation:"Pola larangan formal tertulis adalah [Verba-te] + は いけません (撮ってはいけません).",diagnosticFeedback:{も:"Salah: 撮ってもいい bermakna boleh mengambil foto.",が:"Salah: bukan rumus tata bahasa larangan.",を:"Salah: bukan partikel larangan."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai instruksi ibu/guru agar anak segera tidur.",sentencePrompt:'Susunlah kata-kata: "Sudah larut malam, segeralah tidur!".',options:["もう 夜【よる】遅【おそ】いから、 早【はや】く 寝【ね】なさい ！","早【はや】く もう 夜【よる】遅【おそ】いから、 ！ 寝【ね】なさい","寝【ね】なさい もう 夜【よる】遅【おそ】いから、 早【はや】く ！","！ 寝【ね】なさい 早【はや】く もう 夜【よる】遅【おそ】いから、"],correctAnswer:"もう 夜【よる】遅【おそ】いから、 早【はや】く 寝【ね】なさい ！",explanation:"Alasan (夜遅いから) + Keterangan (早く) + Perintah terarah (寝なさい).",diagnosticFeedback:{"早【はや】く もう 夜【よる】遅【おそ】いから、 ！ 寝【ね】なさい":"Salah urutan anak kalimat.","寝【ね】なさい もう 夜【よる】遅【おそ】いから、 早【はや】く ！":"Salah posisi predikat di depan.","！ 寝【ね】なさい 早【はや】く もう 夜【よる】遅【おそ】いから、":"Salah susun total."},tokens:["もう 夜【よる】遅【おそ】いから、","早【はや】く","寝【ね】なさい","！"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:"Langkah 5 (Analisis Nuansa): Analisislah mengapa rambu darurat memakai bentuk perintah singkat (Meireikei/Kinshikei).",sentencePrompt:'Alasan rambu darurat K3 di pabrik memakai kata "逃げろ" (Nigero!) atau "入るな" (Hairu na!) adalah:',options:["Karena dalam detik-detik genting bahaya maut, instruksi harus dipahami dalam tempo 0,1 detik tanpa distorsi kesopanan","Karena pengelola pabrik tidak menghormati pekerja","Karena huruf kanjinya sudah habis dari percetakan","Karena bahasa Jepang tidak memiliki kata sopan untuk api dan kebakaran"],correctAnswer:"Karena dalam detik-detik genting bahaya maut, instruksi harus dipahami dalam tempo 0,1 detik tanpa distorsi kesopanan",explanation:"Kejelasan mutlak dan kecepatan reaksi instan adalah kunci penyelamatan jiwa dalam K3.",diagnosticFeedback:{"Karena pengelola pabrik tidak menghormati pekerja":"Salah: Ini murni faktor keselamatan nyawa.","Karena huruf kanjinya sudah habis dari percetakan":"Salah: Alasan mengada-ada.","Karena bahasa Jepang tidak memiliki kata sopan untuk api dan kebakaran":"Salah: Bahasa Jepang tentu memiliki kosakata sopan."}}],can_do_challenge:{statement:"Bisa membaca papan peringatan K3 di area konstruksi atau pabrik manufaktur.",situation:"Melihat rambu bahaya di dekat panel gardu listrik tegangan tinggi bengkel.",promptTask:"Bacakan dan jelaskan peringatan bahwa dilarang keras menyentuh panel itu!",modelAnswer:"「触【さわ】るな」と 書【か】いて あります。危険【きけん】ですから 触【さわ】っては いけません。",modelAnswerId:'Tertulis "Jangan Sentuh!". Karena berbahaya, kita tidak boleh menyentuhnya.',culturalEtiquette:"Tunjuk rambu bahaya dengan jari telunjuk mantap tanda konfirmasi K3 (Yubisashi Koshou).",skillUnlocked:["Mampu membaca dan merespons rambu darurat Meireikei dan Kinshikei","Menguasai penegakan aturan keselamatan kerja V-te wa ikemasen"]},pocket_summary:{keyFormula:"[V-te] は いけません (larangan formal) / [V-ru] + な！ (larangan keras K3) / [V-Masu] + なさい (perintah terarah)",coreWords:["きけん","ちゅうい","さわるな","ヘルメット"],coreWarning:"Kinshikei (V-ru + na) = peringatan bahaya maut. Jangan tertukar dengan partikel santai naa.",quickDialogue:"A: あの看板は？ → B: 「入るな」と書いてあります！"}}},i={"les-n4-u12-01":{pedagogical_framework:{what:{summary:"Kondisi pengandaian kasus khusus (~nara), klausul situasi darurat (~baai wa), syarat tunggal esensial (~sae ... ba), representasi aksi variatif (~tari ~tari), dan enumerasi fleksibel (~toka ~toka).",canDo:"Bisa memberikan petunjuk tindakan jika terjadi gempa bumi atau keadaan darurat di tempat kerja.",targetPatterns:["[Kata Benda / Bentuk Biasa] なら (kalau tentang / jika kasusnya)","[Kata Benda] の 場合は / [Verba Kamus] 場合は (dalam hal / jika terjadi situasi)","[Kata Benda] さえ [Verba-ba] (asalkan saja ...)","[Verba-ta] り、[Verba-ta] り する (melakukan hal-hal seperti ... dan ...)","[Kata Benda] とか [Kata Benda] とか (seperti ... atau ... dan lain-lain)"],coreVocabSample:["じしん","ひなん","ばあい","あんぜん","ひ","けす","つくえ"]},sensei_context:{sceneIntro:"Di ruang pelatihan tanggap bencana gempa bumi kantor. Tanaka mengajarkan SOP evakuasi dan tindakan awal saat sirine alarm gempa berbunyi.",dailyMission:'Gunakan frasa "Jishin no baai wa..." untuk memberikan instruksi darurat, dan "~sae sureba" untuk syarat keselamatan utama.',whyOrder:"Jepang adalah negeri rawan gempa. Memahami klausul syarat kondisional darurat (baai wa / nara) adalah keterampilan bertahan hidup yang mutlak."},cultural_notes:{title:"SOP Tanggap Bencana Gempa di Tempat Kerja Jepang (地震防災マニュアル)",etiquette:'Ketika alarm peringatan gempa dini (Kinkyuu Jishin Sokuhou) berbunyi di ponsel, teriakkan petunjuk tenang: "Jishin no baai wa, tsukue no shita ni haitte!".',taboos:"Jangan menggunakan kata sambung 〜たら atau 〜と untuk judul klausul resmi manual K3. Dokumen resmi selalu menggunakan [N] の場合は."},pronunciation_tips:{title:'Intonasi Pembuka Klausul Bersyarat "Baai wa"',moraNote:"Ba-a-i-wa terdiri dari 4 mora datar teratur.",soundTip:'Beri jeda koma lembut setelah kata "baai wa" agar instruksi keselamatan terdengar lugas.'},common_pitfalls:[{title:"Tertukar Antara 〜なら (Topik Khusus) vs 〜と (Hasil Otomatis Alami)",caseScenario:"Memberikan saran kepada teman yang ingin membeli kamera murah.",pitfallWarning:'"カメラを 買【か】うと、秋葉原【あきはばら】が いいですよ。"',rightSolution:'"カメラを 買【か】うなら、秋葉原【あきはばら】が いいですよ。"',explanation:"Untuk saran, permintaan, atau rekomendasi atas topik yang diangkat lawan bicara, gunakan 〜なら (bukan 〜と yang terikat pada hukum alam/mesin)."},{title:'Lupa Partikel の untuk Kata Benda Sebelum "Baai wa"',caseScenario:"Menyambungkan kata bencana gempa ke baai wa tanpa no.",pitfallWarning:'"地震【じしん】 場合は"',rightSolution:'"地震【じしん】の 場合は"',explanation:"Kata benda wajib menggunakan partikel の sebelum 場合は (地震の 場合は)."}],who_and_when:{situational_context:"Instruksi evakuasi bencana kantor, panduan syarat garansi barang elektronik, menyarankan tempat belanja terbaik kepada teman.",social_relations:"Sangat lazim dipakai supervisor saat memandu SOP K3 dan antarrekan kerja.",when_not_to_use:"Jangan gunakan syarat ketat ini pada ramalan cuaca umum."},scenario:{title:"Simulasi Tanggap Bencana Gempa Bumi di Kantor",setting:"Ruang kerja lantai 2, pukul 10.00",narrative:"Tanaka melatih Budi langkah awal saat gempa: padamkan kompor dapur dan sembunyi di bawah meja kokoh."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor K3",avatar:"🧑‍💼",jp:"ブディさん、もし 大【おお】きな 地震【じしん】が 起【お】きた 場合は どうしますか。",furigana:"ブディさん、もし 大きな 地震が 起きた 場合は どうしますか。",romaji:"Budi-san, moshi ookina jishin ga okita baai wa dou shimasu ka.",idText:"Budi-san, seandainya terjadi gempa bumi besar, apa yang akan kamu lakukan?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"地震【じしん】の 場合は、まず 頑丈【がんじょう】な 机【つくえ】の 下【した】に 隠【かく】れます。",furigana:"地震の 場合は、まず 頑丈な 机の 下に 隠れます。",romaji:"Jishin no baai wa, mazu ganjou na tsukue no shita ni kakuremasu.",idText:"Dalam hal terjadi gempa, pertama-tama saya akan bersembunyi di bawah meja yang kokoh."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor K3",avatar:"🧑‍💼",jp:"正解【せいかい】です！ 給湯室【きゅうとうしつ】で 火【ひ】を 使【つか】って いるときは？",furigana:"正解です！ 給湯室で 火を 使って いるときは？",romaji:"Seikai desu! Kyuutoushitsu de hi o tsukatte iru toki wa?",idText:"Tepat sekali! Kalau sedang menyalakan api kompor di ruang dapur air bagaimana?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"揺【ゆ】れが 収【おさ】まったら、火【ひ】を 消【け】したり 窓【まど】を 開【あ】けたり します。",furigana:"揺れが 収まったら、火を 消したり 窓を 開けたり します。",romaji:"Yure ga osamattara, hi o keshitari mado o aketari shimasu.",idText:"Begitu guncangan mereda, saya akan mematikan kompor dan membuka pintu/jendela untuk jalur keluar."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor K3",avatar:"🧑‍💼",jp:"落【お】ち着【つ】いて 行動【こうどう】さえ すれば、怪我【けが】を 防【ふせ】ぐ ことが できますよ。",furigana:"落ち着いて 行動さえ すれば、怪我を 防ぐ ことが できますよ。",romaji:"Ochitsuite koudou sae sureba, kega o fusegu koto ga dekimasu yo.",idText:"Asalkan kita bertindak dengan tenang, kita pasti bisa mencegah terjadinya cedera."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"避難【ひなん】場所【ばしょ】なら、近【ちか】くの 公園【こうえん】ですね。しっかり 覚【おぼ】えて おきます！",furigana:"避難場所なら、近くの 公園ですね。しっかり 覚えて おきます！",romaji:"Hinanbasho nara, chikaku no kouen desu ne. Shikkari oboete okimasu!",idText:"Kalau lokasi evakuasi berkumpul, di taman dekat sini kan ya. Akan saya ingat dengan baik!"}],vocab_breakdown:[{id:"vg-n4-00126",word:"建築",reading:"けんちく",romaji:"kenchiku",meaning:"arsitektur, konstruksi",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"彼は大学で日本の伝統的な建築を研究しています。",furigana:"彼は大学で日本の伝統的な建築を研究しています。",romaji:"",idText:"Dia meneliti arsitektur tradisional Jepang di universitas."}},{id:"vg-n4-00133",word:"選ぶ",reading:"えらぶ",romaji:"erabu",meaning:"memilih",pos:"verb-u",nuance:"選ぶ = memilih (dari beberapa pilihan). 選択する lebih formal.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"たくさんの中から一つ選んでください。",furigana:"たくさんの中から一つ選んでください。",romaji:"",idText:"Tolong pilih satu dari banyak pilihan."}},{id:"vg-n4-00179",word:"計画",reading:"けいかく",romaji:"keikaku",meaning:"rencana, proyek",pos:"verb-suru",nuance:"計画 = rencana/proyek (lebih detail dari 予定). 計画を立てる = membuat rencana.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"旅行の計画を立てましょう。",furigana:"旅行の計画を立てましょう。",romaji:"",idText:"Mari kita buat rencana perjalanan."}},{id:"vg-n4-00225",word:"差し上げる",reading:"さしあげる",romaji:"sashiageru",meaning:"memberikan",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"先生にお土産のお菓子を差し上げました。",furigana:"先生にお土産のお菓子を差し上げました。",romaji:"",idText:"Saya memberikan kue oleh-oleh kepada guru."}},{id:"vg-n4-00274",word:"書き直す",reading:"かきなおす",romaji:"kakinaosu",meaning:"menulis ulang",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"字が汚かったので先生に作文を書き直すように言われました。",furigana:"字が汚かったので先生に作文を書き直すように言われました。",romaji:"",idText:"Karena tulisannya jelek, guru menyuruh saya menulis ulang karangan."}},{id:"vg-n4-00276",word:"聞き取る",reading:"ききとる",romaji:"kikitoru",meaning:"menangkap (ucapan), memahami dengan mendengar",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"早いスピードの日本語を聞き取るのは難しいです。",furigana:"早いスピードの日本語を聞き取るのは難しいです。",romaji:"",idText:"Memahami bahasa Jepang yang berkecepatan cepat itu sulit."}},{id:"vg-n4-00431",word:"尋ねる",reading:"たずねる",romaji:"tazuneru",meaning:"bertanya; menanyakan",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"道が分からなくなったので近くの交番で尋ねました。",furigana:"道が分からなくなったので近くの交番で尋ねました。",romaji:"",idText:"Saya menanyakan rute tujuan di pos polisi terdekat karena tersesat."}},{id:"vg-n4-00436",word:"捕まえる",reading:"つかまえる",romaji:"tsukamaeru",meaning:"menangkap",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"逃げる泥棒を警察官が走って捕まえました。",furigana:"逃げる泥棒を警察官が走って捕まえました。",romaji:"",idText:"Aparat polisi mengejar dan meringkus pencuri yang berusaha kabur."}},{id:"vg-n4-00437",word:"伝える",reading:"つたえる",romaji:"tsutaeru",meaning:"menyampaikan",pos:"verb-ru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"田中さんが戻ったらこの伝言を伝えていただけますか。",furigana:"田中さんが戻ったらこの伝言を伝えていただけますか。",romaji:"",idText:"Maukah Anda menyampaikan titipan pesan ini bilamana Tanaka sudah tiba?"}},{id:"vg-n4-00463",word:"出発",reading:"しゅっぱつ",romaji:"shuppatsu",meaning:"keberangkatan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"旅行のバスは明日の朝七時に駅前を出発します。",furigana:"旅行のバスは明日の朝七時に駅前を出発します。",romaji:"",idText:"Bus wisata dijadwalkan bertolak dari stasiun jam tujuh pagi besok."}}],explanations:[{id:"exp-1",grammarId:"gn4-00035",title:"Pola: 〜なら",formula:"V/Adj plain / N + なら",meaning:"kalau memang ... / jika kasusnya ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜なら",idText:"kalau memang ... / jika kasusnya ..."}],examples:[{jp:"東京へ行くなら、ここに寄ってみてください。",romaji:"",idText:"Kalau memang pergi ke Tokyo, coba mampir ke sini."},{jp:"本当に困っているなら、助けますよ。",romaji:"",idText:"Kalau memang benar-benar kesulitan, saya bantu."}]},{id:"exp-2",grammarId:"gn4-00016",title:"Pola: 〜場合は / 〜場合に (ばあい)",formula:"N + の + 場合は / Vる/Vた + 場合は",meaning:"dalam hal ... / jika terjadi ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜場合は / 〜場合に (ばあい)",idText:"dalam hal ... / jika terjadi ..."}],examples:[{jp:"緊急の場合は、このボタンを押してください。",romaji:"",idText:"Dalam keadaan darurat, tekan tombol ini."},{jp:"遅刻する場合は、必ず連絡してください。",romaji:"",idText:"Jika terlambat, pastikan untuk memberi kabar."}]},{id:"exp-3",grammarId:"gn4-00036",title:"Pola: 〜さえ〜ば",formula:"N + さえ + Adj-ければ / Vさえ + すれば",meaning:"asalkan ... / asal saja ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜さえ〜ば",idText:"asalkan ... / asal saja ..."}],examples:[{jp:"お金さえあれば、何でも買えます。",romaji:"",idText:"Asalkan ada uang, bisa beli apa saja."},{jp:"健康でさえあれば、それで十分です。",romaji:"",idText:"Asalkan sehat, itu sudah cukup."}]},{id:"exp-4",grammarId:"gn4-00046",title:"Pola: 〜たり〜たりする",formula:"Vた → Vたり + (Vたり) + する",meaning:"melakukan hal-hal seperti ... dan ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜たり〜たりする",idText:"melakukan hal-hal seperti ... dan ..."}],examples:[{jp:"休みの日はDVDを見たり本を読んだりしています。",romaji:"",idText:"Di hari libur saya menonton DVD atau membaca buku."},{jp:"最近、寒かったり暑かったりしていますね。",romaji:"",idText:"Akhir-akhir ini silih berganti dingin dan panas ya."}]},{id:"exp-5",grammarId:"gn4-00004",title:"Pola: 〜とか〜とか",formula:"N/V + とか + N/V + とか",meaning:"... atau ... dan sebagainya",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜とか〜とか",idText:"... atau ... dan sebagainya"}],examples:[{jp:"休みの日は映画とか本を読むとかしています。",romaji:"",idText:"Di hari libur saya nonton film atau baca buku dan sebagainya."},{jp:"スポーツとか音楽とかが好きです。",romaji:"",idText:"Saya suka olahraga, musik, dan sebagainya."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk tempat berkumpul evakuasi saat bencana.",sentencePrompt:"Lokasi aman yang ditetapkan sebagai titik kumpul pengungsian saat terjadi gempa disebut:",options:["避難【ひなん】場所【ばしょ】 (Tempat evakuasi)","給湯室【きゅうとうしつ】 (Dapur air)","駐車場【ちゅうしゃじょう】 (Tempat parkir)","更衣室【こういしつ】 (Ruang ganti)"],correctAnswer:"避難【ひなん】場所【ばしょ】 (Tempat evakuasi)",explanation:"避難場所 (hinanbasho) adalah zona terbuka aman yang ditentukan pemerintah daerah untuk titik evakuasi bencana.",diagnosticFeedback:{"給湯室【きゅうとうしつ】 (Dapur air)":"Salah: Dapur air bukan tempat evakuasi karena ada bahaya kompor.","駐車場【ちゅうしゃじょう】 (Tempat parkir)":"Salah: Tempat parkir bukan titik evakuasi resmi.","更衣室【こういしつ】 (Ruang ganti)":"Salah: Ruang ganti berada di dalam gedung."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Syarat Esensial): Lengkapi kalimat syarat asalkan ada paspor maka bisa bepergian.",sentencePrompt:"パスポート（　　）あれば、いつでも 海外【かいがい】へ 行【い】けます。",options:["さえ","しか","だけ","ほど"],correctAnswer:"さえ",explanation:'Pola [Kata Benda] + さえ + [Verba-ba] menyatakan satu-satunya syarat mutlak yang mencukupi ("asalkan saja ada paspor").',diagnosticFeedback:{しか:"Salah: しか harus berpasangan dengan bentuk sangkalan negatif (shika nai).",だけ:"Salah: だけ hanya membatasi kuantitas tanpa nuansa kondisional syarat ba.",ほど:"Salah: ほど menandai perkiraan derajad komparasi."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel Klausul Keadaan Darurat): Pilihlah partikel penyambung kata benda sebelum 場合は.",sentencePrompt:"火事【かじ】（　　）場合は、１１９番【ばん】に 電話【でんわ】して ください。",options:["の","な","に","で"],correctAnswer:"の",explanation:"Kata benda wajib disambung dengan partikel の sebelum kata 場合は (火事の 場合は = jika terjadi kebakaran).",diagnosticFeedback:{な:"Salah: な dipakai untuk kata sifat-na (例: 危険な場合は).",に:"Salah: bukan partikel penyambung kata benda ke baai.",で:"Salah: で tidak menyambung kata benda ke baai."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat aktivitas liburan yang bervariasi.",sentencePrompt:'Susunlah kata-kata: "Pada akhir pekan saya melakukan hal-hal seperti menonton film dan membaca buku".',options:["週末【しゅうまつ】は 映画【えいが】を 見【み】たり 本【ほん】を 読【よ】んだり します。","映画【えいが】を 見【み】たり 週末【しゅうまつ】は します 本【ほん】を 読【よ】んだり。","本【ほん】を 読【よ】んだり します 週末【しゅうまつ】は 映画【えいが】を 見【み】たり。","します 週末【しゅうまつ】は 映画【えいが】を 見【み】たり 本【ほん】を 読【よ】んだり。"],correctAnswer:"週末【しゅうまつ】は 映画【えいが】を 見【み】たり 本【ほん】を 読【よ】んだり します。",explanation:"Waktu (週末は) + [V-tari] (映画を見たり) + [V-tari] (本を読んだり) + Shimasu.",diagnosticFeedback:{"映画【えいが】を 見【み】たり 週末【しゅうまつ】は します 本【ほん】を 読【よ】んだり。":"Salah susun verba terpotong.","本【ほん】を 読【よ】んだり します 週末【しゅうまつ】は 映画【えいが】を 見【み】たり。":"Salah posisi shimasu.","します 週末【しゅうまつ】は 映画【えいが】を 見【み】たり 本【ほん】を 読【よ】んだり。":"Predikat salah tempat di awal."},tokens:["週末【しゅうまつ】は","映画【えいが】を 見【み】たり","本【ほん】を 読【よ】んだり","します"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah fungsi pola "〜なら" dalam merespons topik lawan bicara.',sentencePrompt:'Ketika seseorang berkata "日本の美味しいラーメンが食べたい", lalu Anda menjawab "ラーメンなら、あの店がいいですよ", fungsi "なら" adalah:',options:["Mengangkat topik mi ramen yang dibicarakan lawan bicara untuk diberikan saran rekomendasi spesifik","Menolak ajakan makan mi ramen karena tidak suka","Menyatakan bahwa mi ramen dibuat secara otomatis oleh mesin","Menanyakan harga semangkuk mi ramen kepada kasir"],correctAnswer:"Mengangkat topik mi ramen yang dibicarakan lawan bicara untuk diberikan saran rekomendasi spesifik",explanation:"[Topik] なら mengangkat isu yang baru disebut lawan bicara sebagai dasar memberikan masukan atau rekomendasi.",diagnosticFeedback:{"Menolak ajakan makan mi ramen karena tidak suka":"Salah: Justru merekomendasikan tempat makan yang enak.","Menyatakan bahwa mi ramen dibuat secara otomatis oleh mesin":"Salah: Ini bukan konteks mesin.","Menanyakan harga semangkuk mi ramen kepada kasir":"Salah: Bukan kalimat tanya harga."}}],can_do_challenge:{statement:"Bisa memberikan petunjuk jika terjadi gempa bumi atau keadaan darurat di tempat kerja.",situation:"Rekan baru menanyakan apa yang harus dilakukan jika terjadi gempa bumi saat bekerja.",promptTask:"Berikan petunjuk bahwa dalam hal terjadi gempa, sembunyilah di bawah meja!",modelAnswer:"地震【じしん】の 場合は、机【つくえ】の 下【した】に 隠【かく】れて ください。",modelAnswerId:"Dalam hal terjadi gempa bumi, silakan bersembunyi di bawah meja.",culturalEtiquette:"Ucapkan dengan intonasi tenang, jelas, dan tunjuk arah meja yang paling kokoh.",skillUnlocked:["Menguasai klausul situasi darurat [N] no baai wa","Mampu merangkai syarat tunggal esensial sae... ba"]},pocket_summary:{keyFormula:"[N] の 場合は (jika terjadi) / [N] なら (kalau soal topik itu) / [N] さえ [V-ba] (asalkan)",coreWords:["じしん","ひなん","ばあい","あんぜん"],coreWarning:"Jangan gunakan kalimat sopan kaku di tengah sirine gempa; prioritaskan instruksi singkat penyelamatan nyawa.",quickDialogue:"A: 地震が起きたら？ → B: 地震の場合は机の下に入ります。"}},"les-n4-u12-02":{pedagogical_framework:{what:{summary:"Partikel monolog batin keraguan santun (~kana / ~kashira), ekspresi seruan batin penuh dambaan (~naa), dan partikel tanya kasual konfirmasi antarrekan (~kai / ~kane).",canDo:"Bisa mengekspresikan keraguan wajar secara santun saat berdiskusi bersama teman dan mengutarakan harapan.",targetPatterns:["[Bentuk Biasa] かな (ya ... / saya ragu apakah ... - monolog batin pria/netral)","[Bentuk Biasa] かしら (ya ... - feminin/lembut)","[Bentuk Biasa] なあ (sungguh ... ya / alangkah indahnya jika ...)","[Bentuk Biasa] かい？ (kah? - tanya kasual ramah pria/senior)","[Bentuk Biasa] かね (kira-kira begitu kah? - konfirmasi retoris)"],coreVocabSample:["どうかな","いいなあ","しんぱい","ごうかくする","てんき","あした"]},sensei_context:{sceneIntro:"Di balkon asrama saat malam hari menjelang pengumuman hasil ujian JLPT. Kenji dan Budi mengobrol santai sambil memandang bintang di langit.",dailyMission:'Gunakan partikel "~kana" untuk mengungkapkan monolog keraguan tanpa membebani lawan bicara, dan "~naa" untuk dambaan hati.',whyOrder:"Berbicara bahasa Jepang alami tidak hanya terdiri dari kalimat formal kaku. Monolog batin (hitorigoto) adalah kunci agar terdengar luwes dan akrab."},cultural_notes:{title:"Seni Monolog Batin (独り言 - Hitorigoto) dalam Percakapan Jepang",etiquette:'Orang Jepang sering bergumam sendiri: "Ashita ame kana..." (Besok hujan tidak ya...). Ini adalah cara halus memancing obrolan santai tanpa memaksa lawan bicara menjawab.',taboos:'Jangan menggunakan kata "~kana?" atau "~kai?" langsung kepada atasan di forum resmi, karena terkesan berbicara tanpa unggah-ungguh kesopanan.'},pronunciation_tips:{title:"Intonasi Menggantung Berbisik pada Monolog Batin",moraNote:'Pada frasa "Ikou kana...", suku kata akhir "na" diucapkan lembut dan melayang.',soundTip:'Pada kata "ii naa", panjangkan vokal [a] 2 mora untuk mengekspresikan dambaan tulus.'},common_pitfalls:[{title:'Memakai Partikel Kasual "Kana / Kai" Kepada Atasan',caseScenario:"Bertanya kepada manajer apakah besok ada rapat.",pitfallWarning:'"明日【あした】 会議【かいぎ】が あるかい？"',rightSolution:'"明日【あした】 会議【かいぎ】が ございますでしょうか。"',explanation:"Partikel かい dan かな adalah ragam kasual untuk monolog batin atau rekan akrab/bawahan. Kepada atasan, wajib menggunakan Keigo formal."},{title:'Tertukar Antara "Kana" (Monolog Batin) vs "Ka" (Pertanyaan Langsung Menginterogasi)',caseScenario:"Bergumam santai apakah toko sudah buka.",pitfallWarning:'"店【みせ】が 開【あ】いたか！" (Terdengar seperti membentak menginterogasi)',rightSolution:'"店【みせ】が 開【あ】いたかな。" (Santai dan ramah)',explanation:"Bentuk biasa + か terdengar sangat tajam dan kasar bagi orang Jepang. Menambahkan な (kana) melembutkannya menjadi monolog batin yang bersahabat."}],who_and_when:{situational_context:"Obrolan santai di kamar asrama, bergumam saat memilih menu makan siang di kantin, membicarakan peluang kelulusan ujian.",social_relations:"Digunakan sesama teman dekat sebaya atau senior kepada junior yang sudah akrab.",when_not_to_use:"Jangan gunakan dalam surat resmi, email bisnis, atau wawancara visa imigrasi."},scenario:{title:"Monolog Harapan Menjelang Pengumuman Ujian JLPT",setting:"Balkon asrama Tokyo, pukul 20.30",narrative:"Budi dan Kenji memandangi langit malam sambil saling berbagi rasa cemas dan harapan agar sama-sama lulus ujian N4."}},dialogue:[{id:"d1",speaker:"Kenji",speakerRole:"Teman Akrab",avatar:"🧑‍💻",jp:"ブディ、いよいよ 明日【あした】は Ｎ４の 合格【ごうかく】発表【はっぴょう】だね。",furigana:"ブディ、いよいよ 明日は Ｎ４の 合格発表だね。",romaji:"Budi, iyoiyo ashita wa N4 no goukaku happyou da ne.",idText:"Budi, akhirnya besok pagi pengumuman kelulusan ujian N4 ya."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ええ、受【う】かって いるかなあ。ちょっと 心配【しんぱい】です。",furigana:"ええ、受かって いるかなあ。ちょっと 心配です。",romaji:"Ee, ukatte iru kanaa. Chotto shinpai desu.",idText:"Iya, lulus tidak ya kira-kira. Agak cemas juga nih."},{id:"d3",speaker:"Kenji",speakerRole:"Teman Akrab",avatar:"🧑‍💻",jp:"あんなに 毎日【まいにち】 勉強【べんきょう】したんだから、大丈夫【だいじょうぶ】さ。手応【てごた】えは あったかい？",furigana:"あんなに 毎日 勉強したんだから、大丈夫さ。手応えは あったかい？",romaji:"Anna ni mainichi benkyou shita n dakara, daijoubu sa. Tegotae wa atta kai?",idText:"Kamu kan sudah belajar sekeras itu setiap hari, pasti aman. Kemarin ada rasa yakin tidak?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"読解【どっかい】は できたと 思【おも】うんですが、聴解【ちょうかい】が どうかな…。",furigana:"読解は できたと 思うんですが、聴解が どうかな…。",romaji:"Dokkai wa dekita to omou n desu ga, choukai ga dou kana...",idText:"Kalau bagian bacaan saya rasa bisa, tapi bagian menyimak bagaimana ya..."},{id:"d5",speaker:"Kenji",speakerRole:"Teman Akrab",avatar:"🧑‍💻",jp:"二人【ふたり】とも 合格【ごうかく】できたら、焼肉【やきにく】を 食【た】べに 行【い】きたいねえ。",furigana:"二人とも 合格できたら、焼肉を 食べに 行きたいねえ。",romaji:"Futari tomo goukaku dekitara, yakiniku o tabe ni ikitai nee.",idText:"Kalau kita berdua sama-sama lulus, ingin sekali pergi makan yakiniku ya."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いいですねえ！ 絶対【ぜったい】に 二人【ふたり】で 合格【ごうかく】したいなあ！",furigana:"いいですねえ！ 絶対に 二人で 合格したいなあ！",romaji:"Ii desu nee! Zettai ni futari de goukaku shitai naa!",idText:"Wah asyik sekali! Sungguh saya dambakan kita berdua pasti bisa lulus bersama!"}],vocab_breakdown:[{id:"vg-n4-00386",word:"〜ほど",reading:"〜ほど",romaji:"hodo",meaning:"sekitar ~, sampai tingkat ~",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"駅まで歩いて十分ほどかかりました。",furigana:"駅まで歩いて十分ほどかかりました。",romaji:"",idText:"Butuh waktu sekitar sepuluh menit berjalan kaki ke stasiun."}},{id:"vg-n4-00388",word:"〜だけ",reading:"〜だけ",romaji:"dake",meaning:"hanya ~, cuma ~",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"財布の中に千円だけ残っています。",furigana:"財布の中に千円だけ残っています。",romaji:"",idText:"Di dalam dompet hanya tersisa seribu yen saja."}},{id:"vg-n4-00389",word:"〜しか〜ない",reading:"〜しか〜ない",romaji:"shikanai",meaning:"hanya ~ (+ neg.)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"朝は時間がなくてパンを一つしか食べませんでした。",furigana:"朝は時間がなくてパンを一つしか食べませんでした。",romaji:"",idText:"Pagi hari karena tidak ada waktu, saya cuma makan satu roti saja."}},{id:"vg-n4-00390",word:"〜さえ",reading:"〜さえ",romaji:"sae",meaning:"bahkan ~; asalkan ~",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"忙しくて昼ごはんを食べる時間さえありませんでした。",furigana:"忙しくて昼ごはんを食べる時間さえありませんでした。",romaji:"",idText:"Karena sibuk, bahkan waktu untuk makan siang pun tidak ada."}},{id:"vg-n4-00391",word:"〜でも",reading:"〜でも",romaji:"demo",meaning:"bahkan ~; atau sesuatu seperti ~",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"お茶でも飲みながら少しおしゃべりしませんか。",furigana:"お茶でも飲みながら少しおしゃべりしませんか。",romaji:"",idText:"Maukah kita mengobrol sebentar sambil minum teh atau semacamnya?"}},{id:"vg-n4-00392",word:"〜ばかり",reading:"〜ばかり",romaji:"bakari",meaning:"hanya ~, terus ~",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"弟は勉強しないでゲームばかりしています。",furigana:"弟は勉強しないでゲームばかりしています。",romaji:"",idText:"Adik laki-laki saya main game terus tanpa belajar."}},{id:"vg-n4-00394",word:"〜中",reading:"〜じゅう",romaji:"juu",meaning:"seluruh ~, sepanjang ~",pos:"noun",nuance:"Akhiran yang menyatakan seluruh/sepanjang durasi atau area (dibaca 〜じゅう, misal 一日中/ichinichijuu). Dapat juga dibaca 〜ちゅう jika menyatakan sedang berlangsung (misal 授業中/jugyouchuu).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"昨日は一日中雨が降っていました。",furigana:"昨日は一日中雨が降っていました。",romaji:"",idText:"Kemarin hujan turun sepanjang hari."}},{id:"vg-n4-00468",word:"駐車場",reading:"ちゅうしゃじょう",romaji:"chuushajou",meaning:"tempat parkir",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"駅の近くの駐車場に車を止めて電車に乗りました。",furigana:"駅の近くの駐車場に車を止めて電車に乗りました。",romaji:"",idText:"Saya memarkir mobil di tempat parkir dekat stasiun lalu naik kereta."}},{id:"vg-n4-00472",word:"寺",reading:"てら",romaji:"tera",meaning:"kuil (Buddha)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"京都にある有名なお寺をいくつか見学しました。",furigana:"京都にある有名なお寺をいくつか見学しました。",romaji:"",idText:"Saya berkunjung melihat beberapa kuil Buddha terkenal yang ada di Kyoto."}},{id:"vg-n4-00551",word:"コンピューター",reading:"コンピューター",romaji:"konpyu-ta-",meaning:"komputer",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"毎日コンピューターを使ってレポートを作成しています。",furigana:"毎日コンピューターを使ってレポートを作成しています。",romaji:"",idText:"Setiap hari saya membuat laporan dengan menggunakan komputer."}}],explanations:[{id:"exp-1",grammarId:"gn4-00078",title:"Pola: 〜かな / 〜かしら",formula:"V/Adj plain / N + かな (netral/pria) / かしら (feminin)",meaning:"ya ... / acapkali (monolog keraguan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜かな / 〜かしら",idText:"ya ... / acapkali (monolog keraguan)"}],examples:[{jp:"彼は来るかな。",romaji:"",idText:"Dia datang ya... (bergumam)"},{jp:"明日は晴れるかしら。",romaji:"",idText:"Besok cerah ya kira-kira..."}]},{id:"exp-2",grammarId:"gn4-00079",title:"Pola: 〜なあ",formula:"V/Adj plain / N + なあ",meaning:"sungguh ... ya / ah ... (ekspresi kagum/keinginan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜なあ",idText:"sungguh ... ya / ah ... (ekspresi kagum/keinginan)"}],examples:[{jp:"日本語が上手くなりたいなあ。",romaji:"",idText:"Ingin sekali jadi pandai bahasa Jepang..."},{jp:"いい天気だなあ。",romaji:"",idText:"Cuacanya bagus sungguh ya."}]},{id:"exp-3",grammarId:"gn4-00080",title:"Pola: 〜かい / 〜かね",formula:"V/Adj plain / N + かい (ya/tidak) / かね (retorik/konfirmasi)",meaning:"... kah? (partikel tanya kasual/pria)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜かい / 〜かね",idText:"... kah? (partikel tanya kasual/pria)"}],examples:[{jp:"大丈夫かい？",romaji:"",idText:"Baik-baik saja?"},{jp:"そんなことがあるんだろうかね。",romaji:"",idText:"Memangnya ada hal seperti itu ya?"}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata yang tepat untuk ungkapan perasaan bimbang cemas.",sentencePrompt:"Istilah dalam bahasa Jepang untuk perasaan was-was atau rasa cemas adalah:",options:["心配【しんぱい】 (Rasa cemas/khawatir)","退屈【たいくつ】 (Rasa bosan)","複雑【ふくざつ】 (Rumit)","我慢【がまん】 (Menahan diri/sabar)"],correctAnswer:"心配【しんぱい】 (Rasa cemas/khawatir)",explanation:"心配 (shinpai) sering digandengkan dengan monolog batin keraguan (shinpai da naa).",diagnosticFeedback:{"退屈【たいくつ】 (Rasa bosan)":"Salah: 退屈 berarti merasa jenuh bosan.","複雑【ふくざつ】 (Rumit)":"Salah: 複雑 berarti strukturnya rumit.","我慢【がまん】 (Menahan diri/sabar)":"Salah: 我慢 berarti kesabaran menanggung beban."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Monolog Keraguan): Lengkapi kalimat bergumam santai apakah besok akan cerah.",sentencePrompt:"明日【あした】の 旅行【りょこう】、いい 天気【てんき】に（　　）かなあ。",options:["なる","なります","なって","なろう"],correctAnswer:"なる",explanation:"Pola monolog batin menggunakan [Bentuk Biasa (Futsuukei)] + かな (なるかな = kira-kira jadi cerah tidak ya).",diagnosticFeedback:{なります:"Salah: Bentuk masu jarang dipasangkan langsung dengan partikel monolog kana.",なって:"Salah: Bentuk te tidak bersambung ke kana.",なろう:"Salah: Bentuk kehendak tidak pas dengan fenomena cuaca alami."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Partikel Seruan Dambaan Hati): Pilihlah partikel yang tepat untuk menyatakan dambaan pergi ke Hokkaido.",sentencePrompt:"冬【ふゆ】に 北海道【ほっかいどう】へ 行【い】って みたいな（　　）。",options:["あ","い","え","よ"],correctAnswer:"あ",explanation:"Partikel なあ (naa) mengekspresikan dambaan, harapan tulus dari lubuk hati terdalam, atau kekaguman puitis.",diagnosticFeedback:{い:"Salah: bukan partikel seruan dambaan.",え:"Salah: bukan partikel dambaan hati.",よ:"Salah: よ berfungsi mengabarkan informasi kepada lawan bicara."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat monolog batin apakah bus sudah lewat.",sentencePrompt:'Susunlah kata-kata: "Kira-kira busnya sudah berangkat lewat belum ya?".',options:["バスは もう 行【い】って しまったかな","もう バスは しまったかな 行【い】って","行【い】って バスは もう しまったかな","しまったかな もう バスは 行【い】って"],correctAnswer:"バスは もう 行【い】って しまったかな",explanation:"Subjek (バスは) + Keterangan (もう) + V-te shimatta (行ってしまった) + Kana (kira-kira sudah... belum ya).",diagnosticFeedback:{"もう バスは しまったかな 行【い】って":"Salah susun verba terpotong.","行【い】って バスは もう しまったかな":"Salah urutan awal.","しまったかな もう バスは 行【い】って":"Salah penempatan partikel akhir di awal."},tokens:["バスは","もう","行【い】って","しまったかな"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah perbedaan suasana antara "何時ですか" vs "今何時かな".',sentencePrompt:'Pernyataan "今【いま】 何時【なんじ】かな" memiliki nuansa:',options:["Gumam monolog batin santai yang tidak mendesak lawan bicara untuk langsung menjawab saat itu juga","Pertanyaan formal yang menuntut jawaban resmi seketika dengan nada tinggi","Kalimat kemarahan karena seseorang datang terlambat","Perintah agar lawan bicara segera membelikan jam tangan"],correctAnswer:"Gumam monolog batin santai yang tidak mendesak lawan bicara untuk langsung menjawab saat itu juga",explanation:'Kata "~kana" melembutkan suasana menjadi monolog santai sehingga terdengar ramah dan tidak menodong.',diagnosticFeedback:{"Pertanyaan formal yang menuntut jawaban resmi seketika dengan nada tinggi":"Salah: Ini adalah kesan dari pertanyaan kaku formal.","Kalimat kemarahan karena seseorang datang terlambat":"Salah: Bukan kalimat kemarahan.","Perintah agar lawan bicara segera membelikan jam tangan":"Salah: Bukan instruksi permintaan barang."}}],can_do_challenge:{statement:"Bisa mengekspresikan keraguan wajar secara santun saat berdiskusi bersama teman.",situation:"Sedang memilih menu makan siang di kafetaria asrama bersama rekan kerja.",promptTask:"Katakan dengan nada bergumam santai bahwa kamu ragu apakah ramen atau kari yang lebih enak!",modelAnswer:"ラーメンと カレー、どちらが 美味【おい】しいかなあ。",modelAnswerId:"Ramen atau kari ya, kira-kira mana yang lebih enak ya.",culturalEtiquette:"Tatap daftar menu sambil tersenyum santai dengan nada berbisik ramah.",skillUnlocked:["Menguasai monolog batin santai via 〜かな / 〜かしら","Mampu mengekspresikan dambaan hati via 〜なあ"]},pocket_summary:{keyFormula:"[Bentuk Biasa] + かな (ragu batin) / [Bentuk Biasa] + なあ (dambaan hati) / [Bentuk Biasa] + かい (tanya akrab)",coreWords:["どうかな","いいなあ","しんぱい","あした"],coreWarning:"Gunakan かな hanya untuk suasana santai teman akrab/monolog; jangan gunakan di forum rapat resmi.",quickDialogue:"A: 明日雨かな？ → B: 晴れるといいね！"}}},t={"les-n4-u13-01":{pedagogical_framework:{what:{summary:"Konektor logis sebab-akibat (それで / だから = oleh karena itu / maka dari itu) dan penambahan argumen kumulatif berantai (それに / そのうえ = selain itu / ditambah lagi).",canDo:"Bisa memaparkan faktor keterlambatan pengiriman bahan baku secara sistematis kepada tim.",targetPatterns:["文１。それで、文２。 (Oleh karena itu / makanya / dampaknya ...)","文１。だから、文２。 (Karena itu / maka dari itu - inferensi logis)","文１。それに、文２。 (Selain itu / lagi pula / ditambah lagi)","文１。その上【うえ】、文２。 (Lebih dari itu / bahkan ditambah lagi)"],coreVocabSample:["げんりょう","はいたつ","おくれる","こうつう","じゅうたい","じょうほう"]},sensei_context:{sceneIntro:"Di ruang briefing operasional rantai pasok pabrik. Budi menjelaskan kepada manajer gudang mengapa truk muatan bahan baku terlambat tiba.",dailyMission:'Gunakan "Sore de" untuk menyambung rantai sebab-dampak dan "Sore ni" untuk menambahkan faktor pendukung.',whyOrder:"Pekerja industri dituntut mampu menyajikan laporan sebab-akibat (Gen'in to Kekka) secara runtut dan objektif agar solusi cepat diputuskan."},cultural_notes:{title:"Pelaporan Kronologi Kausalitas di Kantor Jepang (因果関係の論理的説明)",etiquette:'Saat memaparkan kendala teknis, urutkan: Fakta pertama -> "Sore de" (dampaknya) -> "Sore ni" (faktor pemberat tambahan). Alur ini sangat disukai manajer Jepang.',taboos:'Hindari memakai "Dakara!" dengan nada keras di awal kalimat kepada atasan karena terkesan mendikte atau menyalahkan pendengar.'},pronunciation_tips:{title:"Penekanan Jeda Koma pada Kata Sambung Paragraf",moraNote:"So-re-de (3 mora) dan So-re-ni (3 mora) diucapkan tegas dengan jeda 1 detik sebelum klausa kedua.",soundTip:'Ucapkan kata "sono ue" dengan artikulasi bersih tanpa membaurkan vokal o dan u.'},common_pitfalls:[{title:'Tertukar Antara "Sore de" (Sebab Alami) vs "Sore nara" (Pengandaian Kalau Begitu)',caseScenario:"Melaporkan bahwa hujan lebat sehingga proyek terhenti.",pitfallWarning:'"雨【あめ】が 降【ふ】りました。それなら、中止【ちゅうし】しました。"',rightSolution:'"雨【あめ】が 降【ふ】りました。それで、中止【ちゅうし】しました。"',explanation:'それなら berarti "kalau begitu keadaannya (kondisional)". Untuk menyatakan akibat nyata yang sudah terjadi, gunakan それで (makanya/akibatnya).'},{title:'Tertukar Antara "Sore ni" (Penambahan Kategori Sejenis) vs "Sore demo" (Pertentangan Walau Begitu)',caseScenario:"Memuji rekan kerja yang pintar dan ramah.",pitfallWarning:'"彼【かれ】は 頭【あたま】が いいです。それでも、親切【しんせつ】です。"',rightSolution:'"彼【かれ】は 頭【あたま】が いいです。それに、親切【しんせつ】です。"',explanation:"それに menambahkan kelebihan/faktor sejenis (positif + positif). それでも adalah pertentangan (walaupun begitu)."}],who_and_when:{situational_context:"Pemaparan evaluasi keterlambatan logistik, menjelaskan alasan memilih kos-kosan asrama, presentasi laporan penjualan.",social_relations:"Sangat lazim dipakai dalam komunikasi profesional sehari-hari di kantor.",when_not_to_use:'Jangan memakai "dakara" berulang-ulang dalam rapat formal di depan dewan direksi.'},scenario:{title:"Laporan Keterlambatan Kiriman Bahan Baku Logistik",setting:"Ruang koordinasi pengiriman pabrik, pukul 11.30",narrative:"Budi memaparkan bahwa truk mengalami pecah ban di jalan tol dan ditambah lagi jalanan macet parah sehingga bahan baku baru sampai siang nanti."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Gudang",avatar:"🧑‍💼",jp:"ブディさん、金属【きんぞく】原料【げんりょう】の トラックが まだ 到着【とうちゃく】しませんね。",furigana:"ブディさん、金属原料の トラックが まだ 到着しませんね。",romaji:"Budi-san, kinzoku genryou no torakku ga mada touchaku shimasen ne.",idText:"Budi-san, truk pengangkut bahan baku logam belum juga tiba ya."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい、高速【こうそく】道路【どうろ】で トンネル事故【じこ】が ありました。それで、通行【つうこう】止【ど】めに なっています。",furigana:"はい、高速道路で トンネル事故が ありました。それで、通行止めに なっています。",romaji:"Hai, kousokudouro de tonneru jiko ga arimashita. Sore de, tsuukoudome ni natte imasu.",idText:"Iya, tadi terjadi kecelakaan di terowongan jalan tol. Oleh karena itu, akses jalan ditutup sementara."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Gudang",avatar:"🧑‍💼",jp:"下【した】の 一般道【いっぱんどう】に 回【まわ】ったのですか。",furigana:"下の 一般道に 回ったのですか。",romaji:"Shita no ippandou ni mawatta no desu ka.",idText:"Apakah sopirnya memutar lewat jalan raya biasa di bawah?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ええ。それに、一般道【いっぱんどう】も 大雨【おおあめ】で 激【はげ】しく 渋滞【じゅうたい】して います。",furigana:"ええ。それに、一般道も 大雨で 激しく 渋滞して います。",romaji:"Ee. Sore ni, ippandou mo ooyuki de hageshiku juutai shite imasu.",idText:"Iya. Ditambah lagi, jalan raya biasa pun mengalami kemacetan parah akibat hujan lebat."},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Gudang",avatar:"🧑‍💼",jp:"なるほど。到着【とうちゃく】の 見込【みこ】み 時間【じかん】は 何時【なんじ】頃【ごろ】ですか。",furigana:"なるほど。到着の 見込み 時間は 何時頃ですか。",romaji:"Naruhodo. Touchaku no mikomi jikan wa nanji goro desu ka.",idText:"Begitu rupanya. Kira-kira estimasi waktu kedatangannya jam berapa?"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ドライバーからの 連絡【れんらく】では、午後【ごご】２時【にじ】に 到着【とうちゃく】する 予定【よてい】です！",furigana:"ドライバーからの 連絡では、午後２時に 到着する 予定です！",romaji:"Doraiba- kara no renraku de wa, gogo niji ni touchaku suru yotei desu!",idText:"Menurut kabar dari sopir, dijadwalkan akan tiba pada pukul 2 siang nanti!"}],vocab_breakdown:[{id:"vg-n4-00049",word:"橋を渡る",reading:"はしをわたる",romaji:"hashiwowataru",meaning:"menyeberangi jembatan",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"この長い橋を渡ると向こう側に公園があります。",furigana:"この長い橋を渡ると向こう側に公園があります。",romaji:"",idText:"Jika menyeberangi jembatan panjang ini, ada taman di seberangnya."}},{id:"vg-n4-00066",word:"調理",reading:"ちょうり",romaji:"chouri",meaning:"memasak, mengolah makanan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"新鮮な野菜を美味しく調理しました。",furigana:"新鮮な野菜を美味しく調理しました。",romaji:"",idText:"Saya mengolah sayuran segar menjadi masakan lezat."}},{id:"vg-n4-00132",word:"解決",reading:"かいけつ",romaji:"kaiketsu",meaning:"solusi, penyelesaian",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"みんなで力を合わせて問題を解決しました。",furigana:"みんなで力を合わせて問題を解決しました。",romaji:"",idText:"Kami menyatukan tenaga untuk menyelesaikan masalah tersebut."}},{id:"vg-n4-00164",word:"集合",reading:"しゅうごう",romaji:"shuugou",meaning:"kumpul, pertemuan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"明日の遠足の集合場所は学校の正門前です。",furigana:"明日の遠足の集合場所は学校の正門前です。",romaji:"",idText:"Tempat kumpul untuk piknik besok ada di depan gerbang utama sekolah."}},{id:"vg-n4-00439",word:"手伝う",reading:"てつだう",romaji:"tetsudau",meaning:"membantu",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"母が夕食を作っているのを台所で手伝いました。",furigana:"母が夕食を作っているのを台所で手伝いました。",romaji:"",idText:"Saya membantu ibu di dapur ketika sedang memasak makan malam."}},{id:"vg-n4-00672",word:"記録する",reading:"きろくする",romaji:"kirokusuru",meaning:"merekam, mendokumentasikan",pos:"verb-suru",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"毎日の体重と食べたものをノートに記録しています。",furigana:"毎日の体重と食べたものをノートに記録しています。",romaji:"",idText:"Saya terbiasa mendokumentasikan bobot raga serta menu asupan ke dalam jurnal."}},{id:"vg-n4-00765",word:"寝坊",reading:"ねぼう",romaji:"nebou",meaning:"bangun kesiangan, kesiangan bangun tidur",pos:"verb-suru",nuance:"Bisa berupa kata benda ataupun kata kerja (寝坊する) yang menyatakan tidak sengaja tertidur melebihi waktu bangun normal sehingga berakibat terlambat. Berbeda dengan 二度寝 (nidone / tidur kembali setelah sempat bangun) atau 夜更かし (yofukashi / begadang).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"目覚まし時計を合わせるのを忘れて今朝は寝坊してしまいました。",furigana:"目覚まし時計を合わせるのを忘れて今朝は寝坊してしまいました。",romaji:"",idText:"Karena lupa menyetel jam weker, pagi ini saya tidak sengaja bangun kesiangan."}},{id:"vg-n4-00850",word:"輸入",reading:"ゆにゅう",romaji:"yunyuu",meaning:"impor, pemasukan barang luar negeri",pos:"verb-suru",nuance:"Aktivitas mendatangkan komoditas dagang dari negara lain ke dalam negeri (輸入する). Lawan katanya adalah 輸出 (yushutsu - ekspor) yang berarti menjual atau mengirim barang keluar negeri.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本は多くの石油や天然ガスを外国から輸入しています。",furigana:"日本は多くの石油や天然ガスを外国から輸入しています。",romaji:"",idText:"Jepang mengimpor banyak minyak bumi dan gas alam dari luar negeri."}},{id:"vg-n4-00861",word:"ファックス",reading:"ファックス",romaji:"fakkusu",meaning:"faksimile, faks (mesin/dokumen)",pos:"verb-suru",nuance:"Mesin atau layanan pengiriman salinan dokumen tertulis melalui saluran telepon (ファックスする / ファックスを送る). Di lingkungan kantor Jepang, penggunaan faks masih kerap dijumpai untuk pemesanan barang dan dokumen resmi.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"急ぎの用事ですから、この書類をすぐに会社へファックスしてください。",furigana:"急ぎの用事ですから、この書類をすぐに会社へファックスしてください。",romaji:"",idText:"Karena ini urusan mendesak, tolong segera kirimkan dokumen ini ke kantor lewat faks."}},{id:"vg-n4-00868",word:"承知",reading:"しょうちする",romaji:"shouchisuru",meaning:"paham, maklum, menyetujui",pos:"verb-suru",nuance:"Ungkapan formal saat menerima permohonan atau memahami instruksi dalam dunia kerja (khususnya frasa '承知しました' / shouchi shimashita). Hindari pemakaian frasa kasual 了解 (ryoukai) kepada atasan bisnis karena dinilai kurang pantas.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"課長からのご指示の件、確かに承知いたしました。",furigana:"課長からのご指示の件、確かに承知いたしました。",romaji:"",idText:"Mengenai arahan dari kepala seksi, tentu saya sudah memahaminya dengan baik."}}],explanations:[{id:"exp-1",grammarId:"gn4-00061",title:"Pola: それで / だから",formula:"文1。それで/だから、文2。",meaning:"oleh karena itu / makanya / jadi",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"それで / だから",idText:"oleh karena itu / makanya / jadi"}],examples:[{jp:"昨日は体調が悪かった。それで、学校を休みました。",romaji:"",idText:"Kemarin kondisi badan saya tidak baik. Karena itu, tidak masuk sekolah."},{jp:"今日は試験がある。だから、緊張しています。",romaji:"",idText:"Hari ini ada ujian. Makanya saya gugup."}]},{id:"exp-2",grammarId:"gn4-00062",title:"Pola: それに / そのうえ",formula:"文1。それに/そのうえ、文2。",meaning:"selain itu / lagi pula / ditambah lagi",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"それに / そのうえ",idText:"selain itu / lagi pula / ditambah lagi"}],examples:[{jp:"あの店は安い。それに、美味しい。",romaji:"",idText:"Toko itu murah. Selain itu, enak juga."},{jp:"彼は頭がいい。そのうえ、スポーツも得意だ。",romaji:"",idText:"Dia pintar. Ditambah lagi, jago olahraga juga."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk kondisi jalan raya yang macet total.",sentencePrompt:"Istilah dalam bahasa Jepang untuk antrean kendaraan macet di jalan adalah:",options:["渋滞【じゅうたい】 (Macet jalan)","通行【つうこう】 (Lalu lintas lancar)","整備【せいび】 (Pemeliharaan)","制限【せいげん】 (Pembatasan)"],correctAnswer:"渋滞【じゅうたい】 (Macet jalan)",explanation:"渋滞 (juutai) adalah istilah untuk kemacetan volume kendaraan di jalan raya.",diagnosticFeedback:{"通行【つうこう】 (Lalu lintas lancar)":"Salah: 通行 berarti lewat melintas.","整備【せいび】 (Pemeliharaan)":"Salah: 整備 berarti servis atau perawatan mesin.","制限【せいげん】 (Pembatasan)":"Salah: 制限 berarti limit kuota."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Konektor Sebab-Akibat Logis): Lengkapi kalimat penghubung dampak sebab.",sentencePrompt:"朝【あさ】から 激【はげ】しい 雨【あめ】が 降【ふ】りました。（　　）、試合【しあい】は 中止【ちゅうし】に なりました。",options:["それで","それに","そのうえ","それなら"],correctAnswer:"それで",explanation:"文1 (Hujan lebat) + それで (Oleh karena itu / makanya) + 文2 (Pertandingan dibatalkan).",diagnosticFeedback:{それに:"Salah: それに dipakai untuk menambahkan faktor lain, bukan sebab-akibat langsung.",そのうえ:"Salah: そのうえ berarti ditambah lagi.",それなら:"Salah: それなら berarti kalau begitu kasusnya."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Konektor Penambahan Argumen): Pilihlah konjungsi yang tepat untuk menambahkan keunggulan apartemen.",sentencePrompt:"この アパートは 家賃【やちん】が 安【やす】いです。（　　）、駅【えき】からも 近【ちか】いです。",options:["それに","だから","それで","しかし"],correctAnswer:"それに",explanation:"Untuk menambahkan kelebihan sejenis (murah + dekat stasiun), gunakan konektor kumulatif それに atau その上.",diagnosticFeedback:{だから:"Salah: だから menyatakan kesimpulan logis, bukan penambahan fitur.",それで:"Salah: 駅からも近いです bukan akibat langsung dari sewa yang murah.",しかし:"Salah: しかし menyatakan pertentangan kontras."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai laporan kronologi kendala keterlambatan.",sentencePrompt:'Susunlah kata-kata: "Terjadi badai salju. Oleh karena itu, penerbangan pesawat dibatalkan".',options:["大雪【おおゆき】が 降【ふ】りました。 それで、 飛行機【ひこうき】が 欠航【けっこう】しました。","それで、 大雪【おおゆき】が 降【ふ】りました。 飛行機【ひこうき】が 欠航【けっこう】しました。","飛行機【ひこうき】が 欠航【けっこう】しました。 大雪【おおゆき】が 降【ふ】りました。 それで、","大雪【おおゆき】が 降【ふ】りました。 飛行機【ひこうき】が 欠航【けっこう】しました。 それで、"],correctAnswer:"大雪【おおゆき】が 降【ふ】りました。 それで、 飛行機【ひこうき】が 欠航【けっこう】しました。",explanation:"Fakta awal (大雪が降りました) + Konektor (それで、) + Akibat dampak (飛行機が欠航しました).",diagnosticFeedback:{"それで、 大雪【おおゆき】が 降【ふ】りました。 飛行機【ひこうき】が 欠航【けっこう】しました。":"Salah susun konektor di awal kalimat pertama.","飛行機【ひこうき】が 欠航【けっこう】しました。 大雪【おおゆき】が 降【ふ】りました。 それで、":"Salah urutan terbalik.","大雪【おおゆき】が 降【ふ】りました。 飛行機【ひこうき】が 欠航【けっこう】しました。 それで、":"Salah posisi konektor di ujung."},tokens:["大雪【おおゆき】が 降【ふ】りました。","それで、","飛行機【ひこうき】が","欠航【けっこう】しました。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Bedakan fungsi "それで" vs "だから".',sentencePrompt:'Perbedaan nuansa antara "それで" dan "だから" dalam pelaporan kerja adalah:',options:['"それで" fokus pada rantai kronologi akibat objektif, sedangkan "だから" mengandung desakan opini/kesimpulan pribadi pembicara','"だから" selalu bermakna sangkalan negatif','"それで" hanya boleh dipakai untuk cuaca hujan saja',"Keduanya dilarang digunakan dalam percakapan lisan"],correctAnswer:'"それで" fokus pada rantai kronologi akibat objektif, sedangkan "だから" mengandung desakan opini/kesimpulan pribadi pembicara',explanation:'それで memaparkan "lalu akibatnya terjadilah X secara wajar". だから berarti "oleh karena itu kesimpulan/tuntutan saya adalah Y".',diagnosticFeedback:{'"だから" selalu bermakna sangkalan negatif':"Salah: だから bisa afirmatif positif.",'"それで" hanya boleh dipakai untuk cuaca hujan saja':"Salah: Bisa untuk topik apa pun.","Keduanya dilarang digunakan dalam percakapan lisan":"Salah: Sangat sering dipakai dalam percakapan."}}],can_do_challenge:{statement:"Bisa memaparkan faktor keterlambatan pengiriman bahan baku secara sistematis.",situation:"Ditanya oleh pengawas produksi mengapa pengiriman barang dari pabrik rekanan molor.",promptTask:"Jelaskan bahwa jalan tol macet, oleh karena itu barang baru tiba pukul 2 siang!",modelAnswer:"道路【どうろ】が 渋滞【じゅうたい】して いました。それで、２時【にじ】に 到着【とうちゃく】します。",modelAnswerId:"Jalanan mengalami kemacetan. Oleh karena itu, barang akan tiba pada pukul 2 siang.",culturalEtiquette:"Sampaikan fakta kendala dengan tenang tanpa nada panik atau menyalahkan pihak luar.",skillUnlocked:["Menguasai konektor sebab-akibat objektif Sore de","Mampu menyambungkan faktor kumulatif Sore ni"]},pocket_summary:{keyFormula:"文1。 それで、 文2 (sebab -> dampak) / 文1。 それに / その上、 文2 (penambahan faktor sejenis)",coreWords:["げんりょう","はいたつ","じゅうたい","おくれる"],coreWarning:"Gunakan それで untuk akibat wajar; gunakan それに untuk menambahkan informasi pelengkap.",quickDialogue:"A: なんで遅れた？ → B: 渋滞でした。それで遅れました。"}},"les-n4-u13-02":{pedagogical_framework:{what:{summary:"Sebab objektif tak terduga via bentuk Te/De, inklusi multi-faktor (~dakedenaku ~mo = bukan hanya ... tetapi juga ...), dan penyebab berskala formal (~no tame ni).",canDo:"Bisa membuat laporan kecelakaan kerja sederhana dengan rincian sebab-akibat berantai.",targetPatterns:["[Verba-te] / [Adjektiva-te] / [Kata Benda] で (karena sebab objektif di luar kendali)","[Kata Benda / Verba Kamus] だけでなく [Kata Benda] も (bukan hanya ... melainkan juga ...)","[Kata Benda] の ために / [Verba-ta] ために (disebabkan oleh / karena faktor skala besar)"],coreVocabSample:["じこ","ゆか","すべる","ぬれる","あぶない","たいさく"]},sensei_context:{sceneIntro:"Di ruang keselamatan kerja pabrik setelah jam kerja. Tanaka membimbing Budi mengisi lembar laporan insiden nyaris celaka (Hiyari-Hatto) terkait genangan oli di lantai.",dailyMission:"Gunakan bentuk 〜て/で untuk menjelaskan sebab objektif insiden dan 〜だけでなく〜も untuk merinci dampaknya.",whyOrder:"Pabrik di Jepang mewajibkan laporan nyaris celaka (ヒヤリ・ハット). Pembelajar harus mampu menghubungkan sebab fisik dan dampak keselamatan secara akurat."},cultural_notes:{title:"Pelaporan Insiden Nyaris Celaka (ヒヤリ・ハット - Hiyari Hatto)",etiquette:"Di industri manufaktur, insiden kecil (terpeleset karena lantai basah) wajib dilaporkan bukan untuk dihukum, melainkan untuk mencegah kecelakaan fatal di masa depan.",taboos:"Jangan menggunakan kata sambung kemauan diri (seperti 〜から / 〜ので) yang bernuansa permohonan pribadi saat menulis laporan sebab fisik teknis."},pronunciation_tips:{title:'Intonasi Runtut Multi-Faktor "Dakedenaku ... mo"',moraNote:"Dakedenaku memiliki 5 mora datar tanpa intonasi mengayun.",soundTip:'Tekankan partikel "mo" di klausa kedua untuk mempertegas inklusi faktor tambahan.'},common_pitfalls:[{title:"Memakai Kalimat Perintah atau Kehendak Setelah Sebab Bentuk-Te",caseScenario:"Mengatakan karena berbahaya maka jangan lari menggunakan te-form.",pitfallWarning:'"危【あぶ】なくて、走【はし】るな！"',rightSolution:'"危【あぶ】ないから、走【はし】るな！"',explanation:"Klausa sebab berbentuk -Te/De HANYA bisa diikuti oleh akibat alami objektif atau perasaan (kaget, cemas, tidak bisa), TIDAK BOLEH diikuti oleh perintah atau ajakan."},{title:'Tertukar Antara "Tame ni" Alasan Penyebab vs "Tame ni" Tujuan Aksi',caseScenario:'Menganalisis kalimat "Koutsuu jiko no tame ni okuremashita".',pitfallWarning:'"Tame ni" diartikan demi/untuk tujuan kecelakaan.',rightSolution:'"Tame ni" di sini adalah sebab-alasan: "Terlambat diakibatkan oleh kecelakaan lalu lintas".',explanation:"Jika diikuti oleh peristiwa tak terduga/musibah, 〜のために berfungsi sebagai konjungsi kausalitas objektif (disebabkan oleh)."}],who_and_when:{situational_context:"Penyusunan lembar laporan K3 (Hiyari Hatto), menjelaskan keterlambatan kereta karena badai salju, pemaparan dampak polusi lingkungan.",social_relations:"Ragam tertulis formal yang sangat diandalkan dalam administrasi pabrik dan kepolisian.",when_not_to_use:'Jangan gunakan bentuk te-sebab kaku untuk alasan egois (seperti "karena malas saya tidur").'},scenario:{title:"Penyusunan Lembar Laporan K3 Nyaris Celaka",setting:"Ruang K3 pabrik perakitan, pukul 16.30",narrative:"Budi melaporkan bahwa lantai basah karena tetesan oli pendingin, bukan hanya licin tetapi juga membahayakan operator konveyor."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Pengawas K3",avatar:"🧑‍💼",jp:"ブディさん、さっき 通路【つうろ】で 何【なに】か 危険【きけん】な ことが ありましたか。",furigana:"ブディさん、さっき 通路で 何か 危険な ことが ありましたか。",romaji:"Budi-san, sakki tsuuro de nanika kiken na koto ga arimashita ka.",idText:"Budi-san, tadi di lorong apakah ada kejadian yang berbahaya?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい。油【あぶら】が 漏【も】れて、床【ゆか】が 滑【すべ】りやすく なって いました。",furigana:"はい。油が 漏れて、床が 滑りやすく なって いました。",romaji:"Hai. Abura ga morete, yuka ga suberiyasuku natte imashita.",idText:"Iya. Tadi ada oli bocor menetes, sehingga lantai menjadi sangat licin."},{id:"d3",speaker:"Tanaka",speakerRole:"Pengawas K3",avatar:"🧑‍💼",jp:"怪我【けが】は なかったですか。転【ころ】びませんでしたか。",furigana:"怪我は なかったですか。転びませんでしたか。",romaji:"Kega wa nakatta desu ka. Korobimasen deshita ka.",idText:"Tidak ada luka apa pun kan? Kamu tidak sampai terjatuh?"},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"手【て】すりを 掴【つか】んで 無事【ぶじ】でした。でも、私【わたし】だけでなく 他【ほか】の 作業員【さぎょういん】も 危【あぶ】ないです。",furigana:"手すりを 掴んで 無事でした。でも、私だけでなく 他の 作業員も 危ないです。",romaji:"Tesuri o tsukande buji deshita. Demo, watashi dakedenaku hoka no sagyouin mo abunai desu.",idText:"Saya sempat berpegangan pada pagar pembatas sehingga selamat. Namun, bukan hanya saya, pekerja lain pun terancam bahaya."},{id:"d5",speaker:"Tanaka",speakerRole:"Pengawas K3",avatar:"🧑‍💼",jp:"油【あぶら】の ために 転倒【てんとう】事故【じこ】が 起【お】きたら 大変【たいへん】です。すぐ 清掃【せいそう】しましょう！",furigana:"油の ために 転倒事故が 起きたら 大変です。すぐ 清掃しましょう！",romaji:"Abura no tame ni tentou jiko ga okitara taihen desu. Sugu seisou shimashou!",idText:"Kalau sampai terjadi kecelakaan terpeleset akibat oli ini, akibatnya bisa fatal. Mari kita segera bersihkan!"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"はい！ 吸着【きゅうちゅう】マットを 持【も】ってきて、床【ゆか】を 拭【ふ】き取【と】ります。",furigana:"はい！ 吸着マットを 持ってきて、床を 拭き取ります。",romaji:"Hai! Kyuuchaku matto o motte kite, yuka o fukitorimasu.",idText:"Baik! Saya akan membawakan matras penyerap minyak dan mengelap tuntas lantainya."}],vocab_breakdown:[{id:"vg-n4-00595",word:"水道",reading:"すいどう",romaji:"suidou",meaning:"air ledeng; PDAM",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"水道の蛇口をしっかり閉めて水を止めました。",furigana:"水道の蛇口をしっかり閉めて水を止めました。",romaji:"",idText:"Saya memutar kran air ledeng dengan rapat untuk menghentikan aliran air."}},{id:"vg-n4-00613",word:"近所",reading:"きんじょ",romaji:"kinjo",meaning:"lingkungan sekitar; tetangga",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"近所の人に会ったら笑顔であいさつをします。",furigana:"近所の人に会ったら笑顔であいさつをします。",romaji:"",idText:"Saya tersenyum menyapa setiap kali berpapasan dengan tetangga sekitar."}},{id:"vg-n4-00733",word:"課長",reading:"かちょう",romaji:"kachou",meaning:"kepala seksi, manajer seksi (jabatan manajerial)",pos:"noun",nuance:"Posisi manajemen madya di kantor Jepang yang memimpin satu seksi (課 / ka). Urutan hierarki umum perusahaan Jepang: 社長 (shachou / direktur utama) > 部長 (buchou / manajer divisi) > 課長 (kachou / manajer seksi) > 係長 (kakarichou / ketua tim). Di kantor, bawahan memanggil atasannya langsung dengan jabatannya (misal: 田中課長 / Tanaka Kachou).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"来週の出張について課長に相談しました。",furigana:"来週の出張について課長に相談しました。",romaji:"",idText:"Saya berkonsultasi dengan kepala seksi mengenai perjalanan dinas minggu depan."}},{id:"vg-n4-00736",word:"エスカレーター",reading:"エスカレーター",romaji:"esukareetaa",meaning:"eskalator, tangga berjalan",pos:"noun",nuance:"Tangga berjalan bertenaga listrik di stasiun, pusat perbelanjaan, atau bandara. Budaya etiket di Jepang: di daerah Tokyo (Kanto), orang yang diam berdiri di sisi kiri, sedangkan di Osaka (Kansai), orang berdiri di sisi kanan untuk memberi jalan bagi yang terburu-buru. Berbeda dengan エレベーター (erebeetaa / lift vertikal).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"大きな荷物があるので、階段ではなくエスカレーターを使いましょう。",furigana:"大きな荷物があるので、階段ではなくエスカレーターを使いましょう。",romaji:"",idText:"Karena membawa barang bawaan besar, mari kita gunakan eskalator bukan tangga biasa."}},{id:"vg-n4-00752",word:"会議室",reading:"かいぎしつ",romaji:"kaigishitsu",meaning:"ruang rapat, ruang konferensi",pos:"noun",nuance:"Ruangan kantor atau fasilitas yang dikhususkan untuk mengadakan rapat, musyawarah, atau presentasi formal. Berbeda dengan 教室 (kyoushitsu / ruang kelas belajar) atau 応接室 (ousetsushitsu / ruang khusus menyambut tamu kehormatan).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"午後からの新商品についての打ち合わせは三階の会議室で行います。",furigana:"午後からの新商品についての打ち合わせは三階の会議室で行います。",romaji:"",idText:"Pertemuan mengenai produk baru mulai siang hari akan dilakukan di ruang rapat lantai tiga."}},{id:"vg-n4-00770",word:"客",reading:"きゃく",romaji:"kyaku",meaning:"tamu, pelanggan, pengunjung",pos:"noun",nuance:"Bisa berarti tamu yang datang bertandang ke rumah maupun konsumen di tempat usaha. Dalam dunia pelayanan atau etiket bertamu, selalu ditambahkan prefiks penghormatan menjadi お客さん (okyakusan) atau bentuk resmi sopan お客様 (okyakusama). Berlawanan dengan 店員 (ten'in / pelayan toko).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"セールが始まったのでデパートに朝から大勢の客が並びました。",furigana:"セールが始まったのでデパートに朝から大勢の客が並びました。",romaji:"",idText:"Karena obral diskon dimulai, banyak pelanggan mengantre di toserba sejak pagi."}},{id:"vg-n4-00785",word:"～員",reading:"～いん",romaji:"~in",meaning:"anggota ~, pegawai ~, staf ~ (akhiran personel)",pos:"noun",nuance:"Sufiks pembentuk kata benda yang menunjukkan pegawai, staf, atau anggota dari suatu organisasi atau lembaga. Contoh amat populer: 会社員 (kaishain / pegawai kantor), 店員 (ten'in / staf toko), 銀行員 (ginkouin / pegawai bank), dan 駅員 (eki'in / petugas stasiun). Berbeda dengan ～家 yang merujuk pada praktisi profesi mandiri.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"大学を卒業した後は地元の銀行で銀行員として働く予定です。",furigana:"大学を卒業した後は地元の銀行で銀行員として働く予定です。",romaji:"",idText:"Setelah lulus dari universitas, saya berencana bekerja sebagai pegawai bank di bank daerah setempat."}},{id:"vg-n4-00820",word:"火事",reading:"かじ",romaji:"kaji",meaning:"kebakaran",pos:"noun",nuance:"Bencana musibah kebakaran rumah atau bangunan. Berbeda dengan 火 (hi) yang sekadar unsur api biasa. Jika terjadi kebakaran, orang akan berteriak '火事だ！' untuk meminta pertolongan.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"近所で火事が発生して、消防車が何台も急行しました。",furigana:"近所で火事が発生して、消防車が何台も急行しました。",romaji:"",idText:"Terjadi kebakaran di lingkungan sekitar, dan beberapa mobil pemadam bergegas datang."}},{id:"vg-n4-00822",word:"彼ら",reading:"かれら",romaji:"karera",meaning:"mereka",pos:"noun",nuance:"Kata ganti orang ketiga jamak ('mereka'). Umumnya merujuk pada kelompok laki-laki atau campuran laki-laki dan perempuan. Jika semuanya perempuan, sering kali digunakan 彼女たち (kanojotachi).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"彼らは放課後いつもグラウンドでサッカーの練習をしています。",furigana:"彼らは放課後いつもグラウンドでサッカーの練習をしています。",romaji:"",idText:"Mereka selalu berlatih sepak bola di lapangan setelah pulang sekolah."}},{id:"vg-n4-00852",word:"お金持ち",reading:"かねもち; おかねもち",romaji:"kanemochi / okanemochi",meaning:"orang kaya, hartawan",pos:"noun",nuance:"Menyebut orang yang memiliki banyak harta atau kekayaan finansial. Penambahan awalan お (o-) pada お金持ち membuat sebutan terasa lebih sopan dan santun dalam percakapan sehari-hari dibandingkan hanya 金持ち.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"あの広い庭がある立派な屋敷はお金持ちの家です。",furigana:"あの広い庭がある立派な屋敷はお金持ちの家です。",romaji:"",idText:"Rumah megah yang memiliki halaman luas itu adalah rumah orang kaya."}}],explanations:[{id:"exp-1",grammarId:"gn4-00063",title:"Pola: 〜て/〜で (sebab/alasan)",formula:"Vて / Adj-くて / N + で",meaning:"karena ... / akibat ... (sebab-alasan via te-form)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜て/〜で (sebab/alasan)",idText:"karena ... / akibat ... (sebab-alasan via te-form)"}],examples:[{jp:"風邪を引いて、学校を休みました。",romaji:"",idText:"Karena masuk angin, saya tidak masuk sekolah."},{jp:"お金がなくて、買えない。",romaji:"",idText:"Karena tidak punya uang, tidak bisa beli."}]},{id:"exp-2",grammarId:"gn4-00081",title:"Pola: 〜だけでなく〜も",formula:"N/Vる + だけでなく + N/V + も",meaning:"bukan hanya ... tapi juga ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜だけでなく〜も",idText:"bukan hanya ... tapi juga ..."}],examples:[{jp:"彼は英語だけでなくフランス語も話せます。",romaji:"",idText:"Dia bukan hanya bisa bahasa Inggris, tapi juga Prancis."},{jp:"この店は安いだけでなく、おいしいもです。",romaji:"",idText:"Toko ini bukan hanya murah, tapi juga enak."}]},{id:"exp-3",grammarId:"gn4-00088",title:"Pola: 〜ために (sebab — bukan tujuan)",formula:"V-た / N + の + ために",meaning:"karena ... / disebabkan oleh ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ために (sebab — bukan tujuan)",idText:"karena ... / disebabkan oleh ..."}],examples:[{jp:"台風のために、電車が止まりました。",romaji:"",idText:"Karena topan, kereta berhenti."},{jp:"病気のために、試験を受けられませんでした。",romaji:"",idText:"Karena sakit, tidak bisa mengikuti ujian."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata yang tepat untuk insiden terpeleset dan terjatuh di lantai basah.",sentencePrompt:"Istilah dalam keselamatan K3 untuk insiden terpeleset jatuh adalah:",options:["転倒【てんとう】 (Terpeleset jatuh)","衝突【しょうとつ】 (Tabrakan)","切断【せつだん】 (Terpotong)","墜落【ついらく】 (Jatuh dari ketinggian)"],correctAnswer:"転倒【てんとう】 (Terpeleset jatuh)",explanation:"転倒 (tentou) adalah jenis kecelakaan kerja berupa terpeleset atau tersandung di permukaan lantai.",diagnosticFeedback:{"衝突【しょうとつ】 (Tabrakan)":"Salah: 衝突 adalah tabrakan antar-benda/kendaraan.","切断【せつだん】 (Terpotong)":"Salah: 切断 adalah luka terpotong pisau/mesin.","墜落【ついらく】 (Jatuh dari ketinggian)":"Salah: 墜落 adalah jatuh terhempas dari tempat tinggi."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Multi-Faktor): Lengkapi kalimat bukan hanya bahasa Jepang tapi juga budaya yang dipelajari.",sentencePrompt:"日本【にほん】では 言葉【ことば】（　　）、文化【ぶんか】も 勉強【べんきょう】して います。",options:["だけでなく","だけで","ばかりで","とおりに"],correctAnswer:"だけでなく",explanation:'Pola [A] だけでなく [B] も menyatakan "bukan hanya A melainkan juga B".',diagnosticFeedback:{だけで:"Salah: だけで berarti hanya dengan.",ばかりで:"Salah: ばかりで berarti melulu penuh dengan.",とおりに:"Salah: とおりに berarti sesuai instruksi."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Sebab Alami Bentuk Te): Pilihlah bentuk yang tepat untuk rasa kaget mendengar berita kecelakaan.",sentencePrompt:"事故【じこ】の ニュースを（　　）、びっくりしました。",options:["聞【き】いて","聞【き】くから","聞【き】くので","聞【き】くなら"],correctAnswer:"聞【き】いて",explanation:"Untuk perasaan spontan alami emosional (kaget, cemas, senang), klausa penyebab wajib berbentuk sambung -te: 聞いて びっくりしました.",diagnosticFeedback:{聞くから:"Kurang tepat: Kara lebih sering untuk keputusan kehendak, bukan reaksi psikologis kaget spontan.",聞くので:"Kurang pas disandingkan dengan bikkuri shimashita.",聞くなら:"Salah: Ini adalah bentuk pengandaian.","聞【き】くから":'Pilihan "聞【き】くから" keliru karena tidak selaras dengan kaidah pola gn4-00063.',"聞【き】くので":'Jebakan Partikel: Pilihan "聞【き】くので" tidak tepat untuk peran gramatikal kalimat ini.',"聞【き】くなら":'Pilihan "聞【き】くなら" keliru karena tidak selaras dengan kaidah pola gn4-00063.'}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat keterlambatan akibat kecelakaan di jalan tol.",sentencePrompt:'Susunlah kata-kata: "Terjadi keterlambatan yang disebabkan oleh kecelakaan lalu lintas".',options:["交通事故【こうつうじこ】の ために 電車【でんしゃ】が 遅【おく】れました。","電車【でんしゃ】が 交通事故【こうつうじこ】の ために 遅【おく】れました。","遅【おく】れました 電車【でんしゃ】が 交通事故【こうつうじこ】の ために。","ために 交通事故【こうつうじこ】の 電車【でんしゃ】が 遅【おく】れました。"],correctAnswer:"交通事故【こうつうじこ】の ために 電車【でんしゃ】が 遅【おく】れました。",explanation:"Sebab objektif (交通事故のために) + Subjek dampak (電車が) + Verba (遅れました).",diagnosticFeedback:{"電車【でんしゃ】が 交通事故【こうつうじこ】の ために 遅【おく】れました。":"Dapat dimengerti tetapi urutan baku kausalitas menempatkan alasan di depan.","遅【おく】れました 電車【でんしゃ】が 交通事故【こうつうじこ】の ために。":"Salah susun predikat di depan.","ために 交通事故【こうつうじこ】の 電車【でんしゃ】が 遅【おく】れました。":"Salah posisi kata depan."},tokens:["交通事故【こうつうじこ】の","ために","電車【でんしゃ】が","遅【おく】れました"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Mengapa kalimat "危なくて、走るな！" dianggap salah secara tata bahasa Jepang?',sentencePrompt:'Kalimat "危なくて、走るな！" keliru secara kaidah bahasa Jepang karena:',options:["Klausa sebab berbentuk -Te (危なくて) tidak boleh diikuti oleh kalimat perintah atau larangan (走るな)","Karena kata 走る tidak boleh diubah ke bentuk larangan","Karena kata 危ない hanya boleh dipakai di laboratorium kimia","Karena partikelnya seharusnya menggunakan を"],correctAnswer:"Klausa sebab berbentuk -Te (危なくて) tidak boleh diikuti oleh kalimat perintah atau larangan (走るな)",explanation:"Sebab berbentuk -Te terikat pada akibat keadaan alami. Jika kalimat kedua berupa perintah, permohonan, atau larangan, wajib menggunakan から: 危ないから、走るな！",diagnosticFeedback:{"Karena kata 走る tidak boleh diubah ke bentuk larangan":"Salah: 走るな adalah bentuk yang sah.","Karena kata 危ない hanya boleh dipakai di laboratorium kimia":"Salah: 危ない dipakai di mana saja.","Karena partikelnya seharusnya menggunakan を":"Salah: Bukan persoalan partikel."}}],can_do_challenge:{statement:"Bisa membuat laporan kecelakaan kerja sederhana dengan rincian sebab-akibat.",situation:"Melaporkan bahwa oli pendingin menetes sehingga lantai lorong menjadi licin berbahaya.",promptTask:"Laporkan bahwa lantai licin karena oli bocor dan berbahaya bagi semua orang!",modelAnswer:"油【あぶら】が 漏【も】れて 床【ゆか】が 滑【すべ】ります。とても 危険【きけん】です。",modelAnswerId:"Oli menetes sehingga lantai menjadi licin. Kondisi ini sangat berbahaya.",culturalEtiquette:"Tunjuk ke arah genangan oli dan pasang segitiga kerucut pengaman (corn) sebelum meninggalkan lokasi.",skillUnlocked:["Menguasai deskripsi kausalitas objektif via te-form","Mampu merinci multi-faktor via dakedenaku... mo"]},pocket_summary:{keyFormula:"[V-te / Adj-te / N-de] (sebab objektif) / [N] だけでなく [N] も (bukan hanya tapi juga) / [N] のために (disebabkan oleh)",coreWords:["じこ","ゆか","すべる","ぬれる"],coreWarning:"Sebab bentuk-te tidak boleh diikuti perintah/larangan; gunakan から jika ingin melarang (危ないから走るな).",quickDialogue:"A: なんで遅刻？ → B: 事故のために電車が遅れました。"}}},r={"les-n4-u14-01":{pedagogical_framework:{what:{summary:"Membedakan penampilan visual sekilas (~sou da: batang verba masu/adjektiva + sou da = kelihatannya akan/terlihat) vs laporan kabar dari sumber pihak ketiga (~sou da: bentuk biasa futsuukei + sou da = katanya / kabarnya).",canDo:"Bisa memperingatkan rekan bahwa tali derek tampak akan putus dan menyampaikan prakiraan cuaca.",targetPatterns:["[Verba Masu-stem] そうだ / そうです (kelihatannya akan segera terjadi - visual)","[I-Adj / Na-Adj stem] そうだ (tampaknya berkarakteristik - visual)","[Bentuk Biasa Futsuukei] そうだ / そうです (katanya / menurut kabar berita - hearsay)","切【き】れそうだ (tampaknya akan putus!)"],coreVocabSample:["きれそう","おちそう","あめがふりそう","てんきよほう","うわさ","きく"]},sensei_context:{sceneIntro:"Di dermaga gudang bongkar muat kargo peti kemas. Budi mengamati tali derek derek crane yang berserabut tipis saat mengangkat peti kargo berat.",dailyMission:'Gunakan "Kiresou desu!" untuk memperingatkan bahaya visual seketika, dan "~sou desu" untuk meneruskan berita resmi.',whyOrder:'Pembedaan dua jenis "Sou da" (visual vs hearsay) adalah ujian kompetensi krusial di JLPT N4 dan penentu keselamatan kerja di lapangan.'},cultural_notes:{title:"Ketelitian Peringatan Bahaya Berdasar Penglihatan Visual (危険予知 - Kiken Yochi)",etiquette:'Ketika melihat benda yang tampak akan patah atau jatuh, berteriaklah dengan bentuk visual: "Kiresou desu!" atau "Ochisou desu!". Ini memberi peringatan 2 detik sebelum musibah terjadi.',taboos:'Jangan pernah mengatakan "Kireta sou desu" jika talinya BELUM putus. Bentuk lampau + sou da berarti kamu menyampaikan kabar gosip bahwa talinya sudah putus.'},pronunciation_tips:{title:"Perbedaan Intonasi Batang Masu + Sou vs Kalimat Lengkap + Sou",moraNote:"Ochi-sou (3 mora) = visual akan jatuh. Ochiru-sou (4 mora) = kabarnya akan jatuh.",soundTip:'Pada visual peringatan darurat, ucapkan kata "Kiresou desu!" dengan nada tinggi mendesak.'},common_pitfalls:[{title:'Tertukar Antara "Sou da" Visual (Masu-stem) vs "Sou da" Kabar (Bentuk Kamus)',caseScenario:'Melihat awan mendung gelap dan ingin bilang "kelihatannya akan turun hujan".',pitfallWarning:'"雨【あめ】が 降【ふ】る そうです。" (Artinya: Menurut ramalan cuaca katanya akan hujan)',rightSolution:'"雨【あめ】が 降【ふ】り そうです。" (Benar pengamatan mata: Kelihatannya mau hujan)',explanation:"Batang masu (降り) + そうです = penilaian langsung dari mata sendiri. Bentuk kamus (降る) + そうです = kabar dari pihak ketiga/berita TV."},{title:'Salah Bentuk Sifat "Ii" (Bagus) Menjadi Sou da Visual',caseScenario:"Mengatakan bahwa barang ini kelihatannya bagus/berkualitas.",pitfallWarning:'"いい そうです (ii sou desu)"',rightSolution:'"よさそうです (yosa sou desu)"',explanation:"Kata sifat いい berubah secara khusus menjadi よさそう (yosasou desu) saat bergabung dengan visual sou da."}],who_and_when:{situational_context:"Peringatan tali derek mesin pabrik, menilai makanan lezat dari tampilan etalase, menyampaikan ramalan cuaca TV kepada rekan.",social_relations:"Sangat sering dipakai supervisor teknik dan rekan kerja di lapangan.",when_not_to_use:"Jangan memakai visual sou da pada warna atau status yang sudah jelas faktanya (tidak ada: akasou desu)."},scenario:{title:"Peringatan Tali Derek Crane yang Tampak Mau Putus",setting:"Area dermaga logistik nomor 4, pukul 14.30",narrative:"Budi melihat serabut tali kawat derek mulai meregang saat mengangkat kontainer dan segera memperingatkan Kenji."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ケンジさん、危【あぶ】ない！ その ワイヤーが 切【き】れそうです！",furigana:"ケンジさん、危ない！ その ワイヤーが 切れそうです！",romaji:"Kenji-san, abunai! Sono waiya- ga kiresou desu!",idText:"Kenji-san, awas bahaya! Tali kawat baja itu kelihatannya tampak mau putus!"},{id:"d2",speaker:"Kenji",speakerRole:"Operator Crane",avatar:"🧑‍💻",jp:"えっ？ ストップ！ クレーンを 一旦【いったん】 止【と】めるぞ！",furigana:"えっ？ ストップ！ クレーンを 一旦 止めるぞ！",romaji:"E? Sutoppu! Kure-n o ittan tomeru zo!",idText:"Eh? Berhenti! Saya akan segera hentikan laju crane-nya!"},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"荷物【にもつ】が 下【した】に 落【お】ちそうでした。間一髪【かんいっぱつ】でしたね。",furigana:"荷物が 下に 落ちそうでした。間一髪でしたね。",romaji:"Nimotsu ga shita ni ochisou deshita. Kan'ippatsu deshita ne.",idText:"Muatan barangnya tadi tampak nyaris mau jatuh ke bawah. Nyaris sekali ya."},{id:"d4",speaker:"Kenji",speakerRole:"Operator Crane",avatar:"🧑‍💻",jp:"よく 気【き】づいてくれたね。天気【てんき】予報【よほう】によると、午後【ごご】から 強風【きょうふう】が 吹【ふ】く そうだよ。",furigana:"よく 気づいてくれたね。天気予報によると、午後から 強風が 吹く そうだよ。",romaji:"Yoku kizuite kureta ne. Tenki yohou ni yoru to, gogo kara kyoufuu ga fuku sou da yo.",idText:"Bagus sekali kamu memperhatikannya. Menurut prakiraan cuaca, kabarnya mulai siang ini angin kencang akan bertiup."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"風【かぜ】が 強【つよ】くなったら、作業【さぎょう】を 中止【ちゅうし】した ほうが よさそうですね。",furigana:"風が 強くなったら、作業を 中止した ほうが よさそうですね。",romaji:"Kaze ga tsuyoku nattara, sagyou o chuushi shita hou ga yosasou desu ne.",idText:"Jika angin semakin kencang, kelihatannya lebih baik pekerjaan dihentikan sementara ya."},{id:"d6",speaker:"Kenji",speakerRole:"Operator Crane",avatar:"🧑‍💻",jp:"そうだね。ワイヤーを 新【あたら】しい ものに 交換【こうかん】して、安全【あんぜん】を 確保【かくほ】しよう。",furigana:"そうだね。ワイヤーを 新しい ものに 交換して、安全を 確保しよう。",romaji:"Sou da ne. Waiya- o atarashii mono ni koukan shite, anzen o kakuho shiyou.",idText:"Betul sekali. Mari kita ganti kabel kawatnya dengan yang baru dan pastikan kondisi aman."}],vocab_breakdown:[{id:"vg-n4-01241",word:"降り出す",reading:"ふりだす",romaji:"furidasu",meaning:"mulai turun hujan",pos:"verb-u",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"その上雨が降り出している。",furigana:"その上雨が降り出している。",romaji:"",idText:"Besides, it's starting to rain."}},{id:"vg-n4-00004",word:"動物",reading:"どうぶつ",romaji:"doubutsu",meaning:"hewan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"動物園でいろいろな動物を見ました。",furigana:"動物園でいろいろな動物を見ました。",romaji:"",idText:"Saya melihat berbagai macam hewan di kebun binatang."}},{id:"vg-n4-00037",word:"風",reading:"かぜ",romaji:"kaze",meaning:"angin",pos:"noun",nuance:"風 (かぜ) = angin. 風が強い = angin kencang. HATI-HATI: 風邪 (かぜ) = flu — beda kanji!",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"今日は風が強いです。",furigana:"今日は風が強いです。",romaji:"",idText:"Hari ini anginnya kencang."}},{id:"vg-n4-00080",word:"味",reading:"あじ",romaji:"aji",meaning:"rasa",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"このスープはとてもやさしい味がします。",furigana:"このスープはとてもやさしい味がします。",romaji:"",idText:"Sup ini memiliki rasa yang sangat lembut dan lezat."}},{id:"vg-n4-00120",word:"区役所",reading:"くやくしょ",romaji:"kuyakusho",meaning:"kantor kecamatan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"住民票をもらうために区役所へ行きました。",furigana:"住民票をもらうために区役所へ行きました。",romaji:"",idText:"Saya pergi ke kantor kecamatan untuk mengambil surat keterangan kependudukan."}},{id:"vg-n4-00134",word:"選手",reading:"せんしゅ",romaji:"senshu",meaning:"pemain, atlet",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"彼は高校を代表する優秀な野球選手です。",furigana:"彼は高校を代表する優秀な野球選手です。",romaji:"",idText:"Dia adalah pemain bisbol berbakat yang mewakili SMA."}},{id:"vg-n4-00150",word:"知人",reading:"ちじん",romaji:"chijin",meaning:"kenalan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"京都に住んでいる知人を訪ねました。",furigana:"京都に住んでいる知人を訪ねました。",romaji:"",idText:"Saya mengunjungi seorang kenalan yang tinggal di Kyoto."}},{id:"vg-n4-00167",word:"返事",reading:"へんじ",romaji:"henji",meaning:"jawaban, balasan",pos:"noun",nuance:"返事 = jawaban/balasan. 返事する = membalas. メールの返事 = balasan email.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"メールの返事をまだしていません。",furigana:"メールの返事をまだしていません。",romaji:"",idText:"Saya belum membalas emailnya."}},{id:"vg-n4-00292",word:"レジ",reading:"レジ",romaji:"reji",meaning:"kasir",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"スーパーのレジでお金を払いました。",furigana:"スーパーのレジでお金を払いました。",romaji:"",idText:"Saya membayar belanjaan di kasir supermarket."}},{id:"vg-n4-00352",word:"選挙",reading:"せんきょ",romaji:"senkyo",meaning:"pemilihan umum",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"来月市長を決める大切な選挙が行われます。",furigana:"来月市長を決める大切な選挙が行われます。",romaji:"",idText:"Bulan depan akan diadakan pemilu penting untuk menentukan walikota."}}],explanations:[{id:"exp-1",grammarId:"gn4-00053",title:"Pola: 〜そうだ (様態 — penampilan)",formula:"V-ます語幹 / Adj-i語幹 / Adj-na + そうだ",meaning:"kelihatannya ... / sepertinya ... (dari penglihatan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜そうだ (様態 — penampilan)",idText:"kelihatannya ... / sepertinya ... (dari penglihatan)"}],examples:[{jp:"空が暗い。雨が降りそうです。",romaji:"",idText:"Langitnya gelap. Sepertinya mau hujan."},{jp:"あのケーキはおいしそうですね。",romaji:"",idText:"Kue itu kelihatannya enak ya."}]},{id:"exp-2",grammarId:"gn4-00087",title:"Pola: 〜そうだ (伝聞 — hearsay)",formula:"V/Adj plain (bukan 語幹) + そうだ",meaning:"katanya ... / konon ... (laporan tidak langsung)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜そうだ (伝聞 — hearsay)",idText:"katanya ... / konon ... (laporan tidak langsung)"}],examples:[{jp:"天気予報によると、明日は晴れるそうです。",romaji:"",idText:"Menurut ramalan cuaca, katanya besok cerah."},{jp:"田中さんは来月結婚するそうですよ。",romaji:"",idText:"Katanya Tanaka-san menikah bulan depan."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah kata yang tepat untuk ramalan cuaca resmi di televisi.",sentencePrompt:"Istilah dalam bahasa Jepang untuk prakiraan cuaca resmi adalah:",options:["天気【てんき】予報【よほう】 (Prakiraan cuaca)","気象【きしょう】事故 (Kecelakaan cuaca)","空模様【そらもよう】 (Pemandangan langit)","注意報【ちゅういほう】 (Peringatan dini)"],correctAnswer:"天気【てんき】予報【よほう】 (Prakiraan cuaca)",explanation:"天気予報 (tenki yohou) adalah sumber rujukan kabar yang lazim dipasangkan dengan 〜によると ... そうです.",diagnosticFeedback:{"気象事故 (Kecelakaan cuaca)":"Salah: Bukan istilah prakiraan cuaca.","空模様 (Pemandangan langit)":"Salah: 空模様 adalah kondisi visual awan di langit.","注意報 (Peringatan dini)":"Salah: 注意報 adalah status waspada bencana.","気象【きしょう】事故 (Kecelakaan cuaca)":'Pilihan "気象【きしょう】事故 (Kecelakaan cuaca)" keliru karena tidak selaras dengan kaidah pola gn4-00053.',"空模様【そらもよう】 (Pemandangan langit)":'Pilihan "空模様【そらもよう】 (Pemandangan langit)" keliru karena tidak selaras dengan kaidah pola gn4-00053.',"注意報【ちゅういほう】 (Peringatan dini)":'Pilihan "注意報【ちゅういほう】 (Peringatan dini)" keliru karena tidak selaras dengan kaidah pola gn4-00053.'}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Visual Kelihatannya Mau): Lengkapi kalimat tombol yang tampak akan copot.",sentencePrompt:"ボタンが 今【いま】にも 取【と】れ（　　）です。",options:["そう","らしい","よう","とおり"],correctAnswer:"そう",explanation:"Untuk pengamatan visual langsung mata kepala sendiri terhadap benda yang tampak mau terjadi seketika (今にも), gunakan Masu-stem + そうです (取れそうです).",diagnosticFeedback:{らしい:"Salah: らしい menyatakan dugaan dari kabar orang lain.",よう:"Salah: よう berpasangan dengan bentuk kamus (取れるようです).",とおり:"Salah: とおり berarti sesuai patokan."}},{id:"drill-3",type:"trap_detect",instruction:'Langkah 3 (Pola Kabar Berita Hearsay): Pilihlah bentuk yang tepat untuk "katanya besok libur".',sentencePrompt:"田中【たなか】さんの 話【はなし】では、明日【あした】は 会社【かいしゃ】が 休【やす】み（　　）です。",options:["だそう","そう","なさそう","よさそう"],correctAnswer:"だそう",explanation:"Dalam kabar dari pihak ketiga (Hearsay), Kata Benda (休み) dan Adjektiva-na wajib menyertakan だ sebelum そうです: 休みだそうです.",diagnosticFeedback:{そう:"Salah: Tanpa だ, kata benda tidak bisa langsung ke kabar hearsay.",なさそう:"Salah: Ini bentuk visual sangkalan.",よさそう:"Salah: Ini bentuk visual bagus."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat sumber berita cuaca bahwa besok akan hujan lebat.",sentencePrompt:'Susunlah kata-kata: "Menurut ramalan cuaca, kabarnya besok akan turun hujan lebat".',options:["天気【てんき】予報【よほう】に よると、 明日【あした】は 大雨【おおあめ】が 降【ふ】るそうです。","明日【あした】は 大雨【おおあめ】が 降【ふ】るそうです。 天気【てんき】予報【よほう】に よると、","よると、 天気【てんき】予報【よほう】に 明日【あした】は 大雨【おおあめ】が 降【ふ】るそうです。","降【ふ】るそうです。 天気【てんき】予報【よほう】に よると、 明日【あした】は 大雨【おおあめ】が"],correctAnswer:"天気【てんき】予報【よほう】に よると、 明日【あした】は 大雨【おおあめ】が 降【ふ】るそうです。",explanation:"Sumber kabar (天気予報によると、) + Fakta (明日は大雨が) + Hearsay (降るそうです).",diagnosticFeedback:{"明日【あした】は 大雨【おおあめ】が 降【ふ】るそうです。 天気【てんき】予報【よほう】に よると、":"Kurang tepat: Sumber kabar diletakkan di pembuka kalimat.","よると、 天気【てんき】予報【よほう】に 明日【あした】は 大雨【おおあめ】が 降【ふ】るそうです。":"Salah susun partikel.","降【ふ】るそうです。 天気【てんき】予報【よほう】に よると、 明日【あした】は 大雨【おおあめ】が":"Salah posisi predikat."},tokens:["天気【てんき】予報【よほう】に","よると、","明日【あした】は 大雨【おおあめ】が","降【ふ】るそうです。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Bedakan makna "雨が降りそうだ" vs "雨が降るそうだ".',sentencePrompt:'Perbedaan mendasar antara "雨【あめ】が 降【ふ】りそうだ" dan "雨【あめ】が 降【ふ】るそうだ" adalah:',options:['"降りそうだ" dinilai langsung oleh mata sendiri melihat awan gelap, sedangkan "降るそうだ" adalah kabar dari berita TV atau orang lain',"Keduanya memiliki arti yang persis sama",'"降りそうだ" berarti hujan sudah selesai kemarin sore','"降るそうだ" adalah perintah agar hujan segera turun'],correctAnswer:'"降りそうだ" dinilai langsung oleh mata sendiri melihat awan gelap, sedangkan "降るそうだ" adalah kabar dari berita TV atau orang lain',explanation:"Masu-stem + そうだ = dugaan visual mata sendiri. Kamus-form + そうだ = informasi kabar dari pihak luar (hearsay).",diagnosticFeedback:{"Keduanya memiliki arti yang persis sama":"Salah: Sumber informasinya sangat berbeda.",'"降りそうだ" berarti hujan sudah selesai kemarin sore':"Salah: Bukan waktu lampau.",'"降るそうだ" adalah perintah agar hujan segera turun':"Salah: Bukan kalimat perintah."}}],can_do_challenge:{statement:"Bisa memperingatkan rekan bahwa tali derek tampak akan putus.",situation:"Melihat tali kawat crane bergetar hebat dan serabut kawatnya mulai renggang putus.",promptTask:"Peringatkan rekan kerjamu dengan segera bahwa talinya tampak mau putus!",modelAnswer:"危【あぶ】ない！ その ワイヤーが 切【き】れそうです！",modelAnswerId:"Awas bahaya! Tali kawat itu kelihatannya mau putus!",culturalEtiquette:"Ucapkan dengan lantang tegas dan lambaikan tangan tanda peringatan darurat.",skillUnlocked:["Menguasai ekspresi visual seketika Masu-stem + sou da","Mampu membedakan laporan kabar Hearsay Futsuukei + sou da"]},pocket_summary:{keyFormula:"[V-Masu stem] + そうだ (kelihatannya mau - visual) vs [Bentuk Biasa] + そうだ (katanya - kabar)",coreWords:["きれそう","おちそう","てんきよほう","うわさ"],coreWarning:"Ame ga furisou = lihat langit mendung; Ame ga furu sou = dengar dari ramalan cuaca TV.",quickDialogue:"A: 雨降りそうだね。 → B: うん、傘を持っていこう！"}},"les-n4-u14-02":{pedagogical_framework:{what:{summary:"Inferensi sensorik dan dugaan berdasar bukti nyata (~you da / ~mitai da), metafora perumpamaan (~no you da), kesan karakteristik tipikal (~rashii), dan perkiraan sopan (~deshou / ~darou).",canDo:"Bisa menyimpulkan anomali suhu ruang pendingin gudang berdasarkan bukti tetesan es.",targetPatterns:["[Bentuk Biasa / N+no] ようだ / ようです (tampaknya / sepertinya berdasar bukti)","[Bentuk Biasa / N] みたいだ (tampaknya - kasual)","[Kata Benda] の ように / の ような (bagaikan / seperti halnya)","[Kata Benda / Bentuk Biasa] らしい (katanya / tampak berkarakteristik khas)","[Bentuk Biasa] でしょう / だろう (mungkin / barangkali)"],coreVocabSample:["おんど","れいとうこ","こおり","とける","げんいん","ちょうし"]},sensei_context:{sceneIntro:"Di depan pintu ruang penyimpanan beku (Reitouko) logistik makanan. Budi mendapati tetesan air es di dekat engsel dan menyimpulkan suhunya naik.",dailyMission:'Gunakan frasa "~you desu" saat menyimpulkan anomali fisik berdasarkan petunjuk visual nyata yang ada di depan mata.',whyOrder:'Di industri mutu (Quality Control), teknisi tidak boleh hanya berasumsi kosong. Pola "You da / Mitai da" menghubungkan fakta bukti konkret dengan kesimpulan logis.'},cultural_notes:{title:"Penarikan Kesimpulan Berbasis Bukti (状況証拠からの推量)",etiquette:'Ketika menemukan anomali mesin, laporkan bukti fisiknya terlebih dahulu: "Es mencair di lantai, kelihatannya suhu naik" (Kouri ga tokete imasu node, ondo ga agatta you desu).',taboos:'Jangan menggunakan kata "rashii" jika buktinya ada di depan matamu sendiri. Rashii lebih ditujukan pada desas-desus atau karakteristik khas.'},pronunciation_tips:{title:'Intonasi Pembuktian Halus "You desu" vs "Mitai desu"',moraNote:"You desu (4 mora) berintonasi datar sopan; Mitai desu (5 mora) lebih santai.",soundTip:'Pada kata "deshou", naikkan nada sedikit jika bernada konfirmasi ramah.'},common_pitfalls:[{title:'Salah Partikel Kata Benda Sebelum "You da" (Wajib Partikel No)',caseScenario:"Mengatakan seseorang tampak seperti dokter.",pitfallWarning:'"医者【いしゃ】 ようです。"',rightSolution:'"医者【いしゃ】の ようです。"',explanation:"Kata benda wajib disambung dengan partikel の sebelum ようだ: 医者のようです (tampaknya seorang dokter)."},{title:'Tertukar Antara "Rashii" (Karakteristik Alami) vs "You da" (Kemiripan Metafora)',caseScenario:"Memuji anak laki-laki yang bersikap ksatria dan jantan.",pitfallWarning:'"男【おとこ】の ようです。"',rightSolution:'"男【おとこ】らしいです。"',explanation:"〜らしい berarti memiliki sifat/karakteristik sejati yang selayaknya (Otokorashii = jantan selayaknya pria sejati). Kalau Otoko no you da berarti mirip pria padahal bukan pria."}],who_and_when:{situational_context:"Pemeriksaan anomali ruang beku, mendeteksi kerusakan suara motor listrik, memuji kinerja rekan yang sangat profesional.",social_relations:"Ragam standar teknis yang sangat dihormati atasan dan rekan kerja.",when_not_to_use:"Jangan menyimpulkan hal-hal mutlak yang faktanya sudah 100% terbukti di atas kertas."},scenario:{title:"Deteksi Anomali Suhu Ruang Penyimpanan Beku",setting:"Gudang beku bahan makanan, pukul 15.00",narrative:"Budi melihat es di dinding ruang pendingin mencair dan menyimpulkan bersama Sakura bahwa pengatur suhu mengalami gangguan."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"サクラさん、冷凍庫【れいとうこ】の ドアの 下【した】を 見【み】てください。水【みず】が 垂【た】れて います。",furigana:"サクラさん、冷凍庫の ドアの 下を 見てください。水が 垂れて います。",romaji:"Sakura-san, reitouko no doa no shita o mite kudasai. Mizu ga tarete imasu.",idText:"Sakura-san, tolong lihat ke bagian bawah pintu ruang beku. Airnya tampak menetes."},{id:"d2",speaker:"Sakura",speakerRole:"Senior Logistik",avatar:"👩‍🏫",jp:"あら、本当【ほんとう】ね。中【なか】の 氷【こおり】が 溶【と】けて いるみたいね。",furigana:"あら、本当ね。中の 氷が 溶けて いるみたいね。",romaji:"Ara, hontou ne. Naka no koori ga tokete iru mitai ne.",idText:"Wah, betul sekali ya. Tampaknya es di dalam sedang mencair."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"温度計【おんどけい】を 見【み】ると、マイナス５度【ごど】に 上【あ】がって いるようです。",furigana:"温度計を 見ると、マイナス５度に 上がって いるようです。",romaji:"Ondokei o miru to, mainasu godo ni agatte iru you desu.",idText:"Melihat termometernya, sepertinya suhu telah naik menjadi minus 5 derajat."},{id:"d4",speaker:"Sakura",speakerRole:"Senior Logistik",avatar:"👩‍🏫",jp:"本来【ほんらい】は マイナス１８度【じゅうはちど】の はずよね。冷却【れいきゃく】機【き】の 故障【こしょう】でしょうね。",furigana:"本来は マイナス１８度の はずよね。冷却機の 故障でしょうね。",romaji:"Honrai wa mainasu juuhachido no hazu yo ne. Reikyakuki no koshou deshou ne.",idText:"Seharusnya normalnya minus 18 derajat kan ya. Barangkali mesin pendinginnya mengalami kerusakan."},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"商品【しょうひん】が 傷【いた】む 前【まえ】に、予備【よび】の 倉庫【そうこ】へ 移【うつ】した ほうが よさそうです。",furigana:"商品が 傷む 前に、予備の 倉庫へ 移した ほうが よさそうですね。",romaji:"Shouhin ga itamu mae ni, yobi no souko e utsushita hou ga yosasou desu ne.",idText:"Sebelum produknya rusak membusuk, sepertinya lebih baik dipindahkan ke gudang cadangan."},{id:"d6",speaker:"Sakura",speakerRole:"Senior Logistik",avatar:"👩‍🏫",jp:"的確【てきかく】な 判断【はんだん】ね！ プロらしい 動【うご】き方【かた】です。すぐ やりましょう！",furigana:"的確な 判断ね！ プロらしい 動き方です。すぐ やりましょう！",romaji:"Tekikaku na handan ne! Puro rashii ugokikata desu. Sugu yarimashou!",idText:"Keputusan yang sangat tepat! Tindakan yang sangat profesional. Mari segera kita kerjakan!"}],vocab_breakdown:[{id:"vg-n4-00805",word:"小鳥",reading:"ことり",romaji:"kotori",meaning:"burung kecil",pos:"noun",nuance:"Burung berukuran kecil seperti burung pipit, kenari, atau burung gereja. Sering digambarkan sedang berkicau riang (鳴く) di pepohonan atau dipelihara di dalam sangkar.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"朝窓を開けると、庭の木で小鳥がきれいな声で鳴いていました。",furigana:"朝窓を開けると、庭の木で小鳥がきれいな声で鳴いていました。",romaji:"",idText:"Saat membuka jendela di pagi hari, seekor burung kecil berkicau merdu di dahan pohon pekarangan."}},{id:"vg-n4-00806",word:"鏡",reading:"かがみ",romaji:"kagami",meaning:"cermin; kaca rias",pos:"noun",nuance:"Benda kaca yang memantulkan bayangan diri. Paling sering digunakan dalam ungkapan 鏡を見る (bercermin) saat merapikan penampilan atau berdandan. Secara kiasan juga digunakan untuk menyebut teladan atau cerminan (contoh: 生徒の鏡 = teladan murid).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"出かける前に鏡を見て、髪型や服の乱れを整えました。",furigana:"出かける前に鏡を見て、髪型や服の乱れを整えました。",romaji:"",idText:"Sebelum bepergian, saya melihat ke cermin untuk merapikan tatanan rambut dan pakaian."}},{id:"vg-n4-00816",word:"冷房",reading:"れいぼう",romaji:"reibou",meaning:"pendingin ruangan; AC penyejuk",pos:"noun",nuance:"Pengaturan suhu sejuk/dingin pada mesin penyejuk udara saat cuaca panas. Lawan katanya adalah 暖房 (danbou / penghangat ruangan saat musim dingin). Alat pendingin dan pemanas secara keseluruhan disebut エアコン (eakon).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"今日は猛暑なので、部屋の冷房をつけて涼しくしましょう。",furigana:"今日は猛暑なので、部屋の冷房をつけて涼しくしましょう。",romaji:"",idText:"Karena hari ini panas terik, mari nyalakan pendingin ruangan agar sejuk."}},{id:"vg-n4-00890",word:"汽車",reading:"きしゃ",romaji:"kisha",meaning:"kereta api (uap), kereta lokomotif",pos:"noun",nuance:"Kereta api yang digerakkan oleh tenaga uap lokomotif. Di masa kini lebih banyak dijumpai sebagai wahana wisata cagar budaya. Berbeda dengan 電車 (densha) yang bergerak dengan daya aliran listrik dan menjadi moda utama perkotaan modern.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"博物館の広場に昔走っていた黒い汽車が展示されています。",furigana:"博物館の広場に昔走っていた黒い汽車が展示されています。",romaji:"",idText:"Di lapangan museum dipamerkan kereta api uap hitam yang beroperasi di masa lalu."}},{id:"vg-n4-00954",word:"味",reading:"あじ",romaji:"aji",meaning:"rasa",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"このチーズはピリッとした味がする。",furigana:"このチーズはピリッとした味がする。",romaji:"",idText:"Keju ini memiliki rasa yang tajam."}},{id:"vg-n4-00970",word:"石",reading:"いし",romaji:"ishi",meaning:"batu",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私にはこの石は持ち上がらない。",furigana:"私にはこの石は持ち上がらない。",romaji:"",idText:"I cannot lift this stone."}},{id:"vg-n4-01046",word:"校長",reading:"こうちょう",romaji:"kouchou",meaning:"kepala sekolah",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"校長が先生の後ろから入ってきた。",furigana:"校長が先生の後ろから入ってきた。",romaji:"",idText:"Kepala sekolah masuk setelah guru."}},{id:"vg-n4-01123",word:"西洋",reading:"せいよう",romaji:"seiyou",meaning:"negara-negara barat",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"それらは西洋の風呂よりずっといいです。",furigana:"それらは西洋の風呂よりずっといいです。",romaji:"",idText:"Mereka much better than Western baths."}},{id:"vg-n4-01163",word:"中学校",reading:"ちゅうがっこう",romaji:"chuugakkou",meaning:"sekolah menengah pertama; sekolah menengah",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この歌を聞くと私の中学校時代を思い出します。",furigana:"この歌を聞くと私の中学校時代を思い出します。",romaji:"",idText:"This song reminds me of my junior high school days."}},{id:"vg-n4-01186",word:"動物園",reading:"どうぶつえん",romaji:"doubutsuen",meaning:"kebun binatang",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"コンドルは動物園では決して育たない。",furigana:"コンドルは動物園では決して育たない。",romaji:"",idText:"Condors have never bred in zoos."}}],explanations:[{id:"exp-1",grammarId:"gn4-00054",title:"Pola: 〜ようだ / 〜みたいだ",formula:"V/Adj plain / N + ようだ / みたいだ",meaning:"tampaknya ... / sepertinya ... (kesimpulan dari bukti)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ようだ / 〜みたいだ",idText:"tampaknya ... / sepertinya ... (kesimpulan dari bukti)"}],examples:[{jp:"彼は風邪を引いたようです。",romaji:"",idText:"Sepertinya dia masuk angin."},{jp:"彼女は疲れているみたいです。",romaji:"",idText:"Sepertinya dia lelah."}]},{id:"exp-2",grammarId:"gn4-00082",title:"Pola: 〜ようだ (metafora)",formula:"N + の + ようだ / N + のように + V",meaning:"seperti ... (metafora/persamaan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜ようだ (metafora)",idText:"seperti ... (metafora/persamaan)"}],examples:[{jp:"彼は魚のように泳ぎます。",romaji:"",idText:"Dia berenang seperti ikan."},{jp:"夢のような出来事でした。",romaji:"",idText:"Itu adalah kejadian yang seperti mimpi."}]},{id:"exp-3",grammarId:"gn4-00085",title:"Pola: 〜らしい",formula:"V/Adj plain / N + らしい",meaning:"katanya ... / tampaknya ... (hearsay/inferensi)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜らしい",idText:"katanya ... / tampaknya ... (hearsay/inferensi)"}],examples:[{jp:"明日は台風が来るらしいです。",romaji:"",idText:"Katanya besok akan ada topan."},{jp:"彼はとても男らしい人です。",romaji:"",idText:"Dia orang yang sangat jantan."}]},{id:"exp-4",grammarId:"gn4-00055",title:"Pola: 〜でしょう / 〜だろう",formula:"V/Adj plain / N + でしょう (polite) / だろう (plain)",meaning:"mungkin ... / sepertinya ... (perkiraan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜でしょう / 〜だろう",idText:"mungkin ... / sepertinya ... (perkiraan)"}],examples:[{jp:"明日は雨が降るでしょう。",romaji:"",idText:"Besok mungkin hujan."},{jp:"彼もきっと来るだろう。",romaji:"",idText:"Dia juga pasti datang."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk alat penunjuk derajat temperatur suhu.",sentencePrompt:"Alat pengukur suhu ruangan dalam bahasa Jepang disebut:",options:["温度計【おんどけい】 (Termometer)","体重計【たいじゅうけい】 (Timbangan badan)","時計【とけい】 (Jam dinding)","計算機【けいさんき】 (Kalkulator)"],correctAnswer:"温度計【おんどけい】 (Termometer)",explanation:"温度計 (ondokei) adalah alat penunjuk derajat suhu udara/ruangan.",diagnosticFeedback:{"体重計【たいじゅうけい】 (Timbangan badan)":"Salah: 体重計 adalah timbangan berat badan.","時計【とけい】 (Jam dinding)":"Salah: 時計 adalah penunjuk waktu jam.","計算機【けいさんき】 (Kalkulator)":"Salah: 計算機 adalah mesin hitung kalkulator."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Sambung Kata Benda Sebelum You da): Lengkapi kalimat perumpamaan wajah anak mirip ayahnya.",sentencePrompt:"彼【かれ】の 顔【かお】は お父【とう】さん（　　）ようです。",options:["の","な","に","で"],correctAnswer:"の",explanation:"Kata benda wajib disisipi partikel の sebelum kata ようだ (お父さんのようです = bagaikan/mirip ayahnya).",diagnosticFeedback:{な:"Salah: な untuk kata sifat-na.",に:"Salah: に digunakan setelah you (〜のように).",で:"Salah: で bukan penyambung kata benda ke you."}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Pola Karakteristik Sejati Rashii): Pilihlah kata yang mencerminkan sikap profesional sejati.",sentencePrompt:"彼【かれ】の 仕事【しごと】は いつも 丁寧【ていねい】で、本当【ほんとう】に プロ（　　）です。",options:["らしい","みたい","そう","よう"],correctAnswer:"らしい",explanation:"[Kata Benda] + らしい mengekspresikan bahwa objek memiliki esensi karakteristik sejati yang membanggakan (プロらしい = profesional sejati).",diagnosticFeedback:{みたい:"Kurang tepat: みたい berarti sekadar menyerupai dari luar.",そう:"Salah: そう tidak melekat langsung ke kata benda profesi.",よう:"Salah: Harus memakai の (プロのようです)."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kesimpulan inferensi dari suara sirene ambulans di kejauhan.",sentencePrompt:'Susunlah kata-kata: "Mendengar suara sirene, sepertinya terjadi kecelakaan di dekat sini".',options:["サイレンが 聞【き】こえます。 近【ちか】くで 事故【じこ】が あった ようです。","近【ちか】くで 事故【じこ】が サイレンが 聞【き】こえます。 ようです。 あった","あった ようです。 サイレンが 聞【き】こえます。 近【ちか】くで 事故【じこ】が","サイレンが 聞【き】こえます。 ようです。 あった 近【ちか】くで 事故【じこ】が"],correctAnswer:"サイレンが 聞【き】こえます。 近【ちか】くで 事故【じこ】が あった ようです。",explanation:"Bukti sensorik (サイレンが聞こえます) + Kesimpulan logis (近くで事故があったようです).",diagnosticFeedback:{"近【ちか】くで 事故【じこ】が サイレンが 聞【き】こえます。 ようです。 あった":"Salah susun.","あった ようです。 サイレンが 聞【き】こえます。 近【ちか】くで 事故【じこ】が":"Salah posisi klausa pembuktian.","サイレンが 聞【き】こえます。 ようです。 あった 近【ちか】くで 事故【じこ】が":"Salah susun verba terpotong."},tokens:["サイレンが 聞【き】こえます。","近【ちか】くで 事故【じこ】が","あった","ようです。"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Bedakan fungsi "子どもらしい" vs "子どものようだ".',sentencePrompt:'Pernyataan "あの子は 子どもらしいね" memiliki arti:',options:["Anak itu bertingkah laku ceria, jujur, dan polos selayaknya seorang anak kecil yang wajar","Orang dewasa yang berpakaian seperti anak-anak saat pesta kostum","Anak tersebut sangat membangkang kepada orang tuanya","Anak tersebut adalah seorang boneka mainan"],correctAnswer:"Anak itu bertingkah laku ceria, jujur, dan polos selayaknya seorang anak kecil yang wajar",explanation:"〜らしい memuji sifat hakiki yang ideal sesuai jati dirinya (seorang anak yang berperilaku manis selayaknya anak-anak).",diagnosticFeedback:{"Orang dewasa yang berpakaian seperti anak-anak saat pesta kostum":"Salah: Ini adalah 子どものようだ (metafora orang dewasa bersikap seperti anak).","Anak tersebut sangat membangkang kepada orang tuanya":"Salah: Tidak ada arti membangkang.","Anak tersebut adalah seorang boneka mainan":"Salah: Bukan boneka."}}],can_do_challenge:{statement:"Bisa menyimpulkan anomali suhu ruang pendingin berdasarkan bukti tetesan es.",situation:"Melihat air menetes dari pintu ruang beku logistik dan melaporkannya kepada teknisi.",promptTask:"Laporkan bahwa es di dalam mencair dan sepertinya suhunya telah naik!",modelAnswer:"氷【こおり】が 溶【と】けて、温度【おんど】が 上【あ】がって いるようです。",modelAnswerId:"Esnya mencair, dan sepertinya suhu pendinginnya telah naik.",culturalEtiquette:"Tunjuk ke termometer indikator dan sampaikan bukti faktual dengan lugas.",skillUnlocked:["Menguasai inferensi berbasis bukti konkrets via 〜ようだ / 〜みたいだ","Mampu membedakan karakteristik sejati via 〜らしい"]},pocket_summary:{keyFormula:"[Bentuk Biasa / N+no] + ようだ (inferensi bukti) / [N] らしい (karakteristik sejati) / [Bentuk Biasa] でしょう (perkiraan)",coreWords:["おんど","れいとうこ","こおり","とける"],coreWarning:"Kata benda sebelum you da wajib menyertakan no (Sensei no you da).",quickDialogue:"A: 水が垂れてるよ。 → B: 氷が溶けているようですね。"}}},u={"les-n4-u15-01":{pedagogical_framework:{what:{summary:"Kepastian logis deduktif berdasar jadwal/fakta (~hazu da = seharusnya / semestinya) dan keyakinan mustahil yang bertolak belakang (~hazu ga nai = tidak mungkin / mustahil terjadi).",canDo:"Bisa memastikan bahwa suku cadang cadangan seharusnya sudah tersimpan di gudang.",targetPatterns:["[Bentuk Biasa / N+no / Na-Adj+na] はずだ / はずです (seharusnya / semestinya pasti)","[Bentuk Biasa / N+no] はずが ない / はずは ありません (tidak mungkin ... / mustahil ...)","昨日【きのう】 届【とど】いた はずです (seharusnya sudah sampai kemarin)"],coreVocabSample:["よてい","ほぞん","ざいこ","かくにん","まちがいない","はず"]},sensei_context:{sceneIntro:"Di gudang suku cadang perakitan. Budi dan Tanaka mencari kotak baut cadangan yang sudah dipesan minggu lalu.",dailyMission:'Gunakan "~hazu desu" untuk menegaskan kepastian logis berdasar dokumen pemesanan dan jadwal kedatangan.',whyOrder:"Di tempat kerja, membedakan perkiraan samar (tabun / deshou) dengan kepastian logis berdasar bukti (hazu da) sangat penting untuk akurasi inventaris."},cultural_notes:{title:"Kepastian Berdasarkan Fakta Logis (論理的確信の表現)",etiquette:'Mengatakan "Todokerareta hazu desu" (Seharusnya sudah diantarkan) didasarkan pada data faktual (misal ada resi bukti kirim), bukan sekadar tebakan kosong.',taboos:'Jangan menggunakan "hazu ga nai!" secara ketus jika lawan bicara adalah atasan, karena mengesankan kamu menuduh atasan berbicara bohong.'},pronunciation_tips:{title:'Intonasi Keyakinan Mantap "Hazu desu"',moraNote:"Ha-zu-de-su terdiri dari 4 mora datar tanpa nada mengambang.",soundTip:'Pada sangkalan mustahil "hazu ga arimasen", beri sedikit penekanan pada suku kata "hazu ga".'},common_pitfalls:[{title:'Salah Partikel Penyambung Kata Benda Sebelum "Hazu da"',caseScenario:"Mengatakan bahwa hari ini seharusnya hari libur.",pitfallWarning:'"今日【きょう】は 休【やす】み はずです。"',rightSolution:'"今日【きょう】は 休【やす】みの はずです。"',explanation:"Kata benda wajib disambung dengan partikel の sebelum hazu: 休みの はずです (seharusnya hari libur)."},{title:'Tertukar Antara "Hazu da" (Deduksi Logis) vs "Tsumori da" (Niat Pribadi)',caseScenario:"Mengatakan bahwa kereta seharusnya berangkat jam 9.",pitfallWarning:'"電車【でんしゃ】は ９時【くじ】に 出【で】る つもりです。"',rightSolution:'"電車【でんしゃ】は ９時【くじ】に 出【で】る はずです。"',explanation:"Tsumori adalah niat tekad pribadi manusia. Untuk jadwal transportasi atau fakta sistemik, gunakan 〜はずです."}],who_and_when:{situational_context:"Pengecekan stok suku cadang gudang, mengonfirmasi jam kedatangan tamu penting, memverifikasi kuitansi pembayaran.",social_relations:"Sangat sering diucapkan supervisor dan staf saat mencocokkan data inventaris.",when_not_to_use:"Jangan gunakan hazu da untuk hal yang hasilnya sama sekali tidak memiliki dasar acuan informasi."},scenario:{title:"Pencarian Kotak Baut Cadangan di Gudang Logistik",setting:"Rak penyimpanan barang nomor 3, pukul 10.15",narrative:"Budi memeriksa sistem komputer dan memastikan kepada Tanaka bahwa kotak baut seharusnya sudah tersimpan di rak C."}},dialogue:[{id:"d1",speaker:"Tanaka",speakerRole:"Supervisor Gudang",avatar:"🧑‍💼",jp:"ブディさん、予備【よび】の ボルトは どこに ありますか。見当【みあ】たりませんね。",furigana:"ブディさん、予備の ボルトは どこに ありますか。見当たりませんね。",romaji:"Budi-san, yobi no boruto wa doko ni arimasu ka. Miatarimasen ne.",idText:"Budi-san, baut cadangannya ada di mana ya? Tidak tampak terlihat nih."},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"パソコンの 在庫【ざいこ】データでは、棚【たな】Ｃに 保管【ほかん】されて いるはずです。",furigana:"パソコンの 在庫データでは、棚Ｃに 保管されて いるはずです。",romaji:"Pasokon no zaiko de-ta de wa, tana C ni hokan sarete iru hazu desu.",idText:"Menurut data inventaris di komputer, seharusnya tersimpan rapi di rak C."},{id:"d3",speaker:"Tanaka",speakerRole:"Supervisor Gudang",avatar:"🧑‍💼",jp:"棚【たな】Ｃを 見【み】たけれど、空【から】の 箱【はこ】しか ないよ。",furigana:"棚Ｃを 見たけれど、空の 箱しか ないよ。",romaji:"Tana C o mita keredo, kara no hako shika nai yo.",idText:"Saya sudah cek rak C, tapi yang ada cuma kotak kosong saja lho."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"そんなはずは ありません。昨日【きのう】 納品【のうひん】書【しょ】に サインを したはずです！",furigana:"そんなはずは ありません。昨日 納品書に サインを したはずです！",romaji:"Sonna hazu wa arimasen. Kinou nouhinsho ni sain o shita hazu desu!",idText:"Mustahil tidak ada! Kemarin saya yakin semestinya sudah menandatangani surat tanda terima barang!"},{id:"d5",speaker:"Tanaka",speakerRole:"Supervisor Gudang",avatar:"🧑‍💼",jp:"あ！ あそこの 受入【うけいれ】検査【けんさ】コーナーに 置【お】いて あるじゃないか！",furigana:"あ！ あそこの 受入検査コーナーに 置いて あるじゃないか！",romaji:"A! Asoko no ukeire kensa ko-na- ni oite aru janai ka!",idText:"Ah! Bukankah kotak barangnya ditaruh di area uji inspeksi penerimaan sebelah sana?!"},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"本当【ほんとう】ですね！ 検査【けんさ】が 終【お】わったら、すぐ 定位置【ていいち】に しまって おきます。",furigana:"本当ですね！ 検査が 終わったら、すぐ 定位置に しまって おきます。",romaji:"Hontou desu ne! Kensa ga owattara, sugu teiichi ni shimatte okimasu.",idText:"Betul sekali ya! Begitu inspeksi selesai, akan segera saya simpan terlebih dahulu di posisi bakunya."}],vocab_breakdown:[{id:"vg-n4-00398",word:"召し上がる",reading:"めしあがる",romaji:"meshiagaru",meaning:"makan/minum (bentuk hormat)",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"どうぞ温かいうちにこの料理を召し上がってください。",furigana:"どうぞ温かいうちにこの料理を召し上がってください。",romaji:"",idText:"Silakan nikmati hidangan ini selagi masih hangat."}},{id:"vg-n4-00399",word:"ご覧になる",reading:"ごらんになる",romaji:"goranninaru",meaning:"melihat (bentuk hormat)",pos:"verb-u",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Perhatikan bentuk konjugasi kata kerja ini.",exampleSentence:{jp:"こちらの新しいカタログをどうぞご覧になってください。",furigana:"こちらの新しいカタログをどうぞご覧になってください。",romaji:"",idText:"Silakan melihat-lihat katalog produk baru kami sebelah sini."}},{id:"vg-n4-00704",word:"うかがう",reading:"うかがう",romaji:"ukagau",meaning:"berkunjung; bertanya; mendengar (ragam merendah / kenjougo)",pos:"verb-u",nuance:"Kata kerja ragam merendahkan diri (謙譲語 / kenjougo) dengan tiga fungsi utama: (1) pengganti 行く/来る saat bertamu ke rumah/kantor pihak yang dihormati, (2) pengganti 聞く saat bertanya atau mendengar kabar, (3) pengganti 尋ねる saat mengajukan pertanyaan kepada atasan/klien.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"明日、午後三時に先生の研究室へうかがってもよろしいでしょうか。",furigana:"明日、午後三時に先生の研究室へうかがってもよろしいでしょうか。",romaji:"",idText:"Bolehkah saya berkunjung ke ruang kerja Sensei besok pada pukul tiga sore?"}},{id:"vg-n4-00741",word:"致す",reading:"いたす",romaji:"itasu",meaning:"melakukan, mengerjakan (ragam merendahkan diri / kenjougo)",pos:"verb-u",nuance:"Bentuk kenjougo (謙譲語 / humble speech) dari kata kerja する (suru / melakukan). Sangat produktif dalam pola keigo: お + akar kata kerja + いたします (contoh: お願いいたします / mohon bantuannya; ご案内いたします / saya akan memandu Anda; よろしくお願いいたします). Jangan pernah gunakan untuk aksi orang lain / lawan bicara.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"それでは、私が会議の準備を担当させていただきます。よろしくお願いいたします。",furigana:"それでは、私が会議の準備を担当させていただきます。よろしくお願いいたします。",romaji:"",idText:"Kalau begitu, izinkan saya yang menangani persiapan rapat. Mohon kerja samanya."}},{id:"vg-n4-00746",word:"申し上げる",reading:"もうしあげる",romaji:"moushiageru",meaning:"menyampaikan, mengatakan (bentuk merendah)",pos:"verb-ru",nuance:"Merupakan ragam bahasa merendahkan diri (kenjougo) tingkat tinggi dari 言う (iu) atau 申す (mousu). Digunakan untuk menyampaikan pesan atau pernyataan secara santun kepada atasan atau pelanggan. Berbeda dengan おっしゃる yang merupakan bentuk penghormatan (sonkeigo) untuk tindakan pihak lawan bicara.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"皆様の温かいご支援に心からお礼を申し上げます。",furigana:"皆様の温かいご支援に心からお礼を申し上げます。",romaji:"",idText:"Saya menyampaikan terima kasih yang tulus atas dukungan hangat Anda sekalian."}},{id:"vg-n4-00827",word:"伺う",reading:"うかがう",romaji:"ukagau",meaning:"berkunjung; bertanya; mendengar (bentuk merendah / kenjougo)",pos:"verb-u",nuance:"Bentuk verba merendah (kenjougo) serbaguna untuk 3 kata: 1) 行く / 来る (berkunjung ke kediaman/kantor orang yang dihormati), 2) 聞く (bertanya kepada atasan/guru), 3) 聞く (mendengar kabar/penjelasan). Dipakai untuk perbuatan diri sendiri.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"明日の午後二時にお宅へ伺ってもよろしいでしょうか。",furigana:"明日の午後二時にお宅へ伺ってもよろしいでしょうか。",romaji:"",idText:"Bolehkah saya berkunjung ke rumah Anda besok pukul dua siang?"}},{id:"vg-n4-00841",word:"おいでになる",reading:"おいでになる",romaji:"oideninaru",meaning:"ada; pergi; datang (ragam hormat / sonkeigo)",pos:"verb-u",nuance:"Bentuk penghormatan tinggi (sonkeigo) yang menggantikan tiga kata kerja sekaligus: 居る (ada), 行く (pergi), dan 来る (datang). Setara tingkat kehalusannya dengan いらっしゃる. Hanya dipakai untuk subjek orang yang dihormati.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"部長はただいま社長室においでになりますので、少々お待ちください。",furigana:"部長はただいま社長室においでになりますので、少々お待ちください。",romaji:"",idText:"Bapak Kepala Bagian saat ini sedang berada di ruang direktur, mohon tunggu sebentar."}},{id:"vg-n4-00974",word:"いらっしゃる",reading:"いらっしゃる",romaji:"irassharu",meaning:"(dengan hormat) menjadi; untuk datang atau pergi",pos:"verb-u",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"いらっしゃるを使います。",furigana:"いらっしゃるを使います。",romaji:"",idText:"Menggunakan (respectful) to be; to come or to go."}},{id:"vg-n4-01039",word:"決して",reading:"けっして",romaji:"kesshite",meaning:"tidak pernah",pos:"adverb",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"これは決して小さなことではない。",furigana:"これは決して小さなことではない。",romaji:"",idText:"It's no small matter."}},{id:"vg-n4-01197",word:"なさる",reading:"なさる",romaji:"nasaru",meaning:"(dengan hormat) untuk melakukan",pos:"verb-u",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"ステーキの焼き方はどうなさいますか。",furigana:"ステーキの焼き方はどうなさいますか。",romaji:"",idText:"How would you like your steak?"}}],explanations:[{id:"exp-1",grammarId:"gn4-00083",title:"Pola: 〜はずだ",formula:"V/Adj plain / N + の + はずだ",meaning:"seharusnya ... / mestinya ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜はずだ",idText:"seharusnya ... / mestinya ..."}],examples:[{jp:"彼はもう着いているはずです。",romaji:"",idText:"Seharusnya dia sudah sampai."},{jp:"今日は休みのはずでしたが、会社に来ました。",romaji:"",idText:"Seharusnya hari ini libur, tapi saya ke kantor."}]},{id:"exp-2",grammarId:"gn4-00084",title:"Pola: 〜はずがない",formula:"V/Adj plain / N + の + はずがない",meaning:"tidak mungkin ... / mustahil ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜はずがない",idText:"tidak mungkin ... / mustahil ..."}],examples:[{jp:"あんなに練習したのに、失敗するはずがない。",romaji:"",idText:"Padahal sudah latihan sebanyak itu, tidak mungkin gagal."},{jp:"彼がそんなことを言うはずがありません。",romaji:"",idText:"Tidak mungkin dia mengatakan hal seperti itu."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk data persediaan barang di gudang.",sentencePrompt:"Stok atau persediaan barang yang tersimpan dalam bahasa Jepang disebut:",options:["在庫【ざいこ】 (Stok persediaan)","注文【ちゅうもん】 (Pemesanan)","配達【はいたつ】 (Pengantaran)","領収【りょうしゅう】 (Penerimaan uang)"],correctAnswer:"在庫【ざいこ】 (Stok persediaan)",explanation:"在庫 (zaiko) adalah jumlah kuantitas stok barang yang masih tersimpan di gudang.",diagnosticFeedback:{"注文【ちゅうもん】 (Pemesanan)":"Salah: 注文 adalah order pemesanan.","配達【はいたつ】 (Pengantaran)":"Salah: 配達 adalah distribusi kirim barang.","領収【りょうしゅう】 (Penerimaan uang)":"Salah: 領収 adalah tanda terima pembayaran."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Kepastian Deduktif): Lengkapi kalimat kepastian kedatangan paket.",sentencePrompt:"荷物【にもつ】は 午前中【ごぜんちゅう】に（　　）はずですが、まだ 来【き】ません。",options:["届【とど】く","届【とど】いて","届【とど】きそう","届【とど】け"],correctAnswer:"届【とど】く",explanation:"Pola kepastian logis deduktif berdasar jadwal adalah [Verba Bentuk Kamus/Biasa] + はずです (届くはずです).",diagnosticFeedback:{届いて:"Salah: Bentuk te tidak bersambung langsung ke hazu desu.",届きそう:"Salah: Ini bentuk visual (tampaknya mau sampai).",届け:"Salah: Ini bentuk perintah.","届【とど】いて":'Pilihan "届【とど】いて" keliru karena tidak selaras dengan kaidah pola gn4-00083.',"届【とど】きそう":'Pilihan "届【とど】きそう" keliru karena tidak selaras dengan kaidah pola gn4-00083.',"届【とど】け":'Pilihan "届【とど】け" keliru karena tidak selaras dengan kaidah pola gn4-00083.'}},{id:"drill-3",type:"trap_detect",instruction:'Langkah 3 (Pola Sangkalan Mustahil): Pilihlah frasa yang bermakna "tidak mungkin / mustahil terjadi".',sentencePrompt:"真面目【まじめ】な ケンジさんが 嘘【うそ】を つく（　　）が ありません。",options:["はず","わけ","こと","もの"],correctAnswer:"はず",explanation:"[Bentuk Biasa] + はずが ありません / はずが ない menyatakan keyakinan bahwa hal itu mustahil terjadi berdasarkan karakter seseorang.",diagnosticFeedback:{わけ:"Kurang tepat dalam pola ini (meski wake ga nai mirip, hazu ga nai adalah pola inti N4).",こと:"Salah: koto ga arimasen bermakna belum pernah mengalami.",もの:"Salah: bukan idiom sangkalan kemustahilan ini."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat kepastian bahwa kunci ada di saku tas.",sentencePrompt:'Susunlah kata-kata: "Seharusnya kunci tersimpan di dalam tas".',options:["鍵【かぎ】は カバンの 中【なか】に 入【はい】って いるはずです","カバンの 中【なか】に 鍵【かぎ】は いるはずです 入【はい】って","入【はい】って 鍵【かぎ】は カバンの 中【なか】に いるはずです","いるはずです カバンの 中【なか】に 鍵【かぎ】は 入【はい】って"],correctAnswer:"鍵【かぎ】は カバンの 中【なか】に 入【はい】って いるはずです",explanation:"Topik (鍵は) + Lokasi (カバンの中に) + V-te iru (入って) + Hazu desu (seharusnya ada).",diagnosticFeedback:{"カバンの 中【なか】に 鍵【かぎ】は いるはずです 入【はい】って":"Salah susun verba terpotong.","入【はい】って 鍵【かぎ】は カバンの 中【なか】に いるはずです":"Salah urutan awal kalimat.","いるはずです カバンの 中【なか】に 鍵【かぎ】は 入【はい】って":"Salah susun predikat di depan."},tokens:["鍵【かぎ】は","カバンの 中【なか】に","入【はい】って","いるはずです"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Bedakan fungsi "来るでしょう" vs "来るはずです".',sentencePrompt:'Perbedaan mendasar antara "来るでしょう" dan "来るはずです" adalah:',options:['"来るはずです" didukung bukti jadwal atau kesepakatan logis, sedangkan "来るでしょう" hanyalah perkiraan tebakan tanpa bukti kuat',"Keduanya memiliki kepastian yang sama 100%",'"来るはずです" berarti orang tersebut dilarang datang','"来るでしょう" adalah bentuk permohonan santun agar orang tersebut datang'],correctAnswer:'"来るはずです" didukung bukti jadwal atau kesepakatan logis, sedangkan "来るでしょう" hanyalah perkiraan tebakan tanpa bukti kuat',explanation:"〜はずだ menuntut adanya dasar fakta penalaran (misal: ada tiket, ada jadwal tertulis). 〜でしょう hanyalah dugaan perkiraan intuitif.",diagnosticFeedback:{"Keduanya memiliki kepastian yang sama 100%":"Salah: Tingkat kepastiannya berbeda.",'"来るはずです" berarti orang tersebut dilarang datang':"Salah: Tidak ada arti larangan.",'"来るでしょう" adalah bentuk permohonan santun agar orang tersebut datang':"Salah: Bukan permohonan."}}],can_do_challenge:{statement:"Bisa memastikan bahwa suku cadang cadangan seharusnya sudah tersimpan di gudang.",situation:"Ditanya oleh manajer perakitan di mana keberadaan komponen mesin yang dibutuhkan.",promptTask:"Tegaskan bahwa seharusnya barang tersebut sudah tiba dan disimpan di gudang!",modelAnswer:"部品【ぶひん】は 倉庫【そうこ】に 届【とど】いて いるはずです。",modelAnswerId:"Komponen suku cadang seharusnya sudah sampai di gudang.",culturalEtiquette:"Tunjukkan lembar tanda terima barang atau layar monitor komputer sebagai bukti sah.",skillUnlocked:["Menguasai penegasan deduktif berdasar data via 〜はずだ","Mampu menyangkal kemustahilan via 〜はずがない"]},pocket_summary:{keyFormula:"[Bentuk Biasa / N+no / Na+na] + はずだ (seharusnya pasti) / はずがない (mustahil)",coreWords:["よてい","ほぞん","ざいこ","かくにん"],coreWarning:"Kata benda wajib menggunakan partikel no sebelum hazu (Yasumi no hazu desu).",quickDialogue:"A: 部品はどこ？ → B: 届いているはずです！"}},"les-n4-u15-02":{pedagogical_framework:{what:{summary:"Pertanyaan tertanam dua pilihan (~kadouka = apakah ... atau tidak), klausa pertanyaan kata tanya (疑問詞 + ~ka = di mana/kapan/siapa yang ...), dan pengutipan isi pikiran (~to omou / ~to iu).",canDo:"Bisa mengonfirmasi apakah klien bisnis jadi berkunjung atau tidak besok pagi.",targetPatterns:["[Bentuk Biasa] かどうか (apakah ... atau tidak)","[Kata Tanya (itsu/doko/dare/nani)] + [Bentuk Biasa] か (klausul pertanyaan tertanam)","[Bentuk Biasa] と 思【おも】います (berpikir bahwa ...)","[Kalimat] と 言【い】って いました (berkata bahwa ...)"],coreVocabSample:["かくにん","よてい","訪問【ほうもん】","しらべる","まにあう","じかん"]},sensei_context:{sceneIntro:"Di meja administrasi kantor. Sakura meminta Budi menelepon perwakilan mitra bisnis untuk memastikan apakah besok jadi berkunjung atau ditunda.",dailyMission:'Gunakan frasa "~kadouka kakunin shite kudasai" untuk koordinasi jadwal kerja yang belum pasti.',whyOrder:"Koordinasi operasional bisnis di Jepang membutuhkan ketelitian mutlak. Pembelajar harus mampu menyisipkan pertanyaan ke dalam kalimat koordinasi (Embedded Question)."},cultural_notes:{title:"Konfirmasi Jadwal Kerja (アポイントの事前確認)",etiquette:'Sebelum tamu penting datang, staf Jepang selalu melakukan re-konfirmasi santun: "Ashita gokairai kudasaru kadouka kakunin itashimasu" untuk menghindari salah jadwal.',taboos:"Dalam klausul tertanam, jangan menambahkan です atau ます di depan か/かどうか (misal: 行きますかどうか - salah!). Wajib memakai bentuk biasa (Futsuukei): 行くかどうか."},pronunciation_tips:{title:'Artikulasi Klausul Tertanam "Kadouka"',moraNote:"Ka-do-u-ka terdiri dari 4 mora berirama mengalir halus.",soundTip:"Beri penekanan sedikit pada kata tanya penanda (itsu / doko / dare) di depan klausa."},common_pitfalls:[{title:'Memasukkan Bentuk Masu Sebelum "Kadouka"',caseScenario:"Mengonfirmasi apakah besok akan datang rapat.",pitfallWarning:'"明日【あした】 来【き】ます かどうか 教【おし】えて ください。"',rightSolution:'"明日【あした】 来【く】る かどうか 教【おし】えて ください。"',explanation:"Klausul tertanam sebelum か / かどうか WAJIB menggunakan bentuk biasa (Futsuukei): 来るかどうか."},{title:'Tertukar Antara "Kadouka" (Apakah Ya/Tidak) vs "Kata Tanya + Ka" (Di Mana/Kapan/Siapa)',caseScenario:"Menanyakan kapan rapat dimulai.",pitfallWarning:'"いつ 会議【かいぎ】が 始【はじ】まる かどうか 知【し】りません。"',rightSolution:'"いつ 会議【かいぎ】が 始【はじ】まるか 知【し】りません。"',explanation:"Jika sudah ada kata tanya (いつ, どこ, だれ, 何), gunakan akhiran 〜か (tanpa douka). かどうか hanya untuk pertanyaan ya/tidak (apakah jadi atau tidak)."}],who_and_when:{situational_context:"Konfirmasi janji temu klien kantor, mengecek jam kereta terakhir tiba, menanyakan apakah obat sudah diminum atau belum.",social_relations:"Sangat sering diucapkan dalam koordinasi tim kantor dan instruksi kerja sehari-hari.",when_not_to_use:"Jangan memakai kadouka jika faktanya sudah pasti 100% terjadi."},scenario:{title:"Konfirmasi Kunjungan Klien Bisnis Besok Pagi",setting:"Meja resepsionis kantor, pukul 16.00",narrative:"Sakura meminta Budi mengonfirmasi via email atau telepon apakah rombongan klien jadi datang pukul 10 besok pagi."}},dialogue:[{id:"d1",speaker:"Sakura",speakerRole:"Senior Kantor",avatar:"👩‍🏫",jp:"ブディさん、明日【あした】 お客様【きゃくさま】が 来【こ】られる かどうか 確認【かくにん】しましたか。",furigana:"ブディさん、明日 お客様が 来られる かどうか 確認しましたか。",romaji:"Budi-san, ashita okyaku-sama ga korareru kadouka kakunin shimashita ka.",idText:"Budi-san, apakah kamu sudah mengonfirmasi apakah besok pelanggan jadi berkunjung atau tidak?"},{id:"d2",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"先【さっき】 メールで お問【と】い合【あ】わせした ところです。まだ お返事【へんじ】は 届【とど】いて いません。",furigana:"さっき メールで お問い合わせした ところです。まだ お返事は 届いて いません。",romaji:"Sakki me-ru de otoiawase shita tokoro desu. Mada ohenji wa todoite imasen.",idText:"Tadi saya baru saja mengajukan pertanyaan konfirmasi via email. Balasannya belum masuk."},{id:"d3",speaker:"Sakura",speakerRole:"Senior Kantor",avatar:"👩‍🏫",jp:"何人【なんにん】で 来【く】るか 分【わ】からないと、お茶【ちゃ】の 準備【じゅんび】が できませんね。",furigana:"何人で 来るか 分からないと、お茶の 準備が できませんね。",romaji:"Nannin de kuru ka wakaranai to, ocha no junbi ga dekimasen ne.",idText:"Kalau kita tidak tahu berapa orang yang akan datang, kita tidak bisa menyiapkan sajian tehnya ya."},{id:"d4",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"電話【でんわ】を かけて、何時【なんじ】頃【ごろ】 着【つ】くか 聞【き】いて みましょうか。",furigana:"電話を かけて、何時頃 着くか 聞いて みましょうか。",romaji:"Denwa o kakete, nanji goro tsuku ka kiite mimashou ka.",idText:"Bagaimana kalau saya coba menelepon dan menanyakan kira-kira jam berapa mereka akan tiba?"},{id:"d5",speaker:"Sakura",speakerRole:"Senior Kantor",avatar:"👩‍🏫",jp:"そうしてくれると 助【たす】かります。部屋【へや】を 予約【よやく】できる かどうかも 大切【たいせつ】ですからね。",furigana:"そうしてくれると 助かります。部屋を 予約できる かどうかも 大切ですからね。",romaji:"Sou shite kureru to tasukarimasu. Heya o yoyaku dekiru kadouka mo taisetsu desu kara ne.",idText:"Kalau kamu bersedia begitu sangat membantu. Karena kepastian apakah kita bisa mereservasi ruangan atau tidak juga sangat penting."},{id:"d6",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"承知【しょうち】しました！ すぐ 確認【かくにん】して 報告【ほうこく】いたします。",furigana:"承知しました！ すぐ 確認して 報告いたします。",romaji:"Shouchi shimashita! Sugu kakunin shite houkoku itashimasu.",idText:"Saya pahami! Akan segera saya pastikan dan laporkan hasilnya."}],vocab_breakdown:[{id:"vg-n4-00710",word:"非常に",reading:"ひじょうに",romaji:"hijou ni",meaning:"sangat, amat, luar biasa",pos:"adverb",nuance:"Kata keterangan tingkat tinggi yang menyatakan 'sangat' dalam konteks formal, resmi, atau tertulis. Jauh lebih sopan dan elegan dibanding とても (totemo / umum sehari-hari) atau すごく (sugoku / kasual lisan).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"今回のプロジェクトは会社にとって非常に重要です。",furigana:"今回のプロジェクトは会社にとって非常に重要です。",romaji:"",idText:"Proyek kali ini sangat penting bagi perusahaan."}},{id:"vg-n4-00081",word:"味噌",reading:"みそ",romaji:"miso",meaning:"miso",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"朝ごはんに温かい味噌汁を飲みました。",furigana:"朝ごはんに温かい味噌汁を飲みました。",romaji:"",idText:"Saya minum sup miso hangat untuk sarapan pagi."}},{id:"vg-n4-00115",word:"関連",reading:"かんれん",romaji:"kanren",meaning:"hubungan, kaitan",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"この二つの事件には深い関連があります。",furigana:"この二つの事件には深い関連があります。",romaji:"",idText:"Terdapat kaitan erat di antara kedua kejadian ini."}},{id:"vg-n4-00186",word:"〜様",reading:"〜さま",romaji:"sama",meaning:"sapaan hormat (Tuan/Nyonya)",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"田中様からお電話が入っております。",furigana:"田中様からお電話が入っております。",romaji:"",idText:"Ada panggilan telepon masuk dari Tuan Tanaka."}},{id:"vg-n4-00290",word:"マナー",reading:"マナー",romaji:"mana-",meaning:"sopan santun, etiket",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"電車の中では携帯電話のマナーを守りましょう。",furigana:"電車の中では携帯電話のマナーを守りましょう。",romaji:"",idText:"Mari patuhi etiket menggunakan telepon genggam di dalam kereta."}},{id:"vg-n4-00405",word:"お〜になる",reading:"お〜になる",romaji:"oninaru",meaning:"pola kata kerja hormat",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"先生はもう新しい本をお読みになりましたか。",furigana:"先生はもう新しい本をお読みになりましたか。",romaji:"",idText:"Apakah bapak guru sudah membaca buku yang baru?"}},{id:"vg-n4-00448",word:"世界",reading:"せかい",romaji:"sekai",meaning:"dunia",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"世界にはいろいろな言語や文化が存在します。",furigana:"世界にはいろいろな言語や文化が存在します。",romaji:"",idText:"Di dunia ini terdapat bermacam-macam bahasa dan kebudayaan."}},{id:"vg-n4-00449",word:"世話",reading:"せわ",romaji:"sewa",meaning:"perawatan; menjaga",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"日本にいる間ホストファミリーにお世話になりました。",furigana:"日本にいる間ホストファミリーにお世話になりました。",romaji:"",idText:"Selama berada di Jepang saya sangat dirawat dan dibantu oleh keluarga angkat."}},{id:"vg-n4-00470",word:"映画館",reading:"えいがかん",romaji:"eigakan",meaning:"bioskop",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"週末に友達と映画館へ行ってアニメを見ました。",furigana:"週末に友達と映画館へ行ってアニメを見ました。",romaji:"",idText:"Pada akhir pekan saya pergi ke bioskop bersama teman untuk menonton anime."}},{id:"vg-n4-00572",word:"下着",reading:"したぎ",romaji:"shitagi",meaning:"pakaian dalam",pos:"noun",nuance:"Digunakan secara luas dalam percakapan kerja dan keseharian.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"デパートの衣料品売り場で暖かい冬用の下着を買いました。",furigana:"デパートの衣料品売り場で暖かい冬用の下着を買いました。",romaji:"",idText:"Saya membeli pakaian dalam musim dingin yang hangat di bagian pakaian toserba."}}],explanations:[{id:"exp-1",grammarId:"gn4-00049",title:"Pola: 〜かどうか",formula:"V/Adj plain / N + かどうか",meaning:"apakah ... atau tidak",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜かどうか",idText:"apakah ... atau tidak"}],examples:[{jp:"彼が来るかどうか分かりません。",romaji:"",idText:"Saya tidak tahu apakah dia akan datang atau tidak."},{jp:"合格したかどうかまだ確認していません。",romaji:"",idText:"Belum mengonfirmasi apakah lulus atau tidak."}]},{id:"exp-2",grammarId:"gn4-00050",title:"Pola: 疑問詞〜か (kata tanya embedded)",formula:"疑問詞 (いつ/どこ/だれ/なに/どう/なぜ等) + V/Adj plain + か",meaning:"di mana/kapan/siapa/apa (embedded question)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"疑問詞〜か (kata tanya embedded)",idText:"di mana/kapan/siapa/apa (embedded question)"}],examples:[{jp:"どこに行くかまだ決めていません。",romaji:"",idText:"Saya belum memutuskan mau ke mana."},{jp:"何時に始まるか知っていますか。",romaji:"",idText:"Apakah kamu tahu jam berapa mulainya?"}]},{id:"exp-3",grammarId:"gn4-00047",title:"Pola: 〜と思う / 〜と言う",formula:"V/Adj plain / N + と + 思う / 言う",meaning:"berpikir bahwa ... / berkata bahwa ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜と思う / 〜と言う",idText:"berpikir bahwa ... / berkata bahwa ..."}],examples:[{jp:"明日は雨が降ると思います。",romaji:"",idText:"Saya pikir besok akan hujan."},{jp:"彼は「来られない」と言いました。",romaji:"",idText:'Dia berkata "tidak bisa datang".'}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk kunjungan resmi ke kantor mitra.",sentencePrompt:"Istilah dalam bahasa Jepang untuk kunjungan resmi bertamu ke perusahaan mitra adalah:",options:["訪問【ほうもん】 (Kunjungan resmi)","出発【しゅっぱつ】 (Keberangkatan)","到着【とうちゃく】 (Kedatangan)","見学【けんがく】 (Studi tur)"],correctAnswer:"訪問【ほうもん】 (Kunjungan resmi)",explanation:"訪問 (houmon) adalah istilah resmi bisnis untuk aksi berkunjung ke kantor rekanan.",diagnosticFeedback:{"出発【しゅっぱつ】 (Keberangkatan)":"Salah: 出発 adalah berangkat pergi.","到着【とうちゃく】 (Kedatangan)":"Salah: 到着 adalah tiba sampai.","見学【けんがく】 (Studi tur)":"Salah: 見学 adalah melihat-lihat orientasi pabrik."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Apakah Jadi Atau Tidak): Lengkapi kalimat konfirmasi apakah bisa datang atau tidak.",sentencePrompt:"明日【あした】の パーティーに（　　）かどうか、返事【へんじ】を ください。",options:["来【く】る","来【き】ます","来【こ】ない","来【き】て"],correctAnswer:"来【く】る",explanation:"Sebelum pola かどうか, verba wajib berwujud bentuk kamus/biasa (Futsuukei): 来るかどうか.",diagnosticFeedback:{来ます:"Salah: Bentuk masu tidak boleh ditaruh sebelum kadouka.",来ない:"Kurang tepat: Bentuk positif netral yang lazim mewakili dua opsi.",来て:"Salah: Bentuk te tidak bersambung ke kadouka.","来【き】ます":'Jebakan Konjugasi: Bentuk predikat "来【き】ます" tidak sesuai dengan kala waktu atau tingkat kesantunan.',"来【こ】ない":'Jebakan Konjugasi: Bentuk predikat "来【こ】ない" tidak sesuai dengan kala waktu atau tingkat kesantunan.',"来【き】て":'Pilihan "来【き】て" keliru karena tidak selaras dengan kaidah pola gn4-00049.'}},{id:"drill-3",type:"trap_detect",instruction:"Langkah 3 (Klausul Kata Tanya): Pilihlah penutup klausul pertanyaan tertanam yang benar.",sentencePrompt:"鍵【かぎ】を どこに 置【お】いた（　　）忘【わす】れて しまいました。",options:["か","かどうか","のに","ので"],correctAnswer:"か",explanation:"Jika klausul mengandung kata tanya (どこ doko = di mana), penutup klausul tertanam adalah partikel 〜か (bukan kadouka).",diagnosticFeedback:{かどうか:"Salah: かどうか tidak berpasangan dengan kata tanya seperti doko/itsu/dare.",のに:"Salah: のに bermakna padahal.",ので:"Salah: ので bermakna karena."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai kalimat pemeriksaan apakah ukuran baju pas atau tidak.",sentencePrompt:'Susunlah kata-kata: "Coba pakailah untuk memastikan apakah ukurannya pas atau tidak".',options:["サイズが 合【あ】うかどうか 着【き】て みてください","着【き】て みてください サイズが 合【あ】うかどうか","合【あ】うかどうか サイズが 着【き】て みてください","サイズが 着【き】て みてください 合【あ】うかどうか"],correctAnswer:"サイズが 合【あ】うかどうか 着【き】て みてください",explanation:"Subjek (サイズが) + Pertanyaan tertanam (合うかどうか) + V-te mi kudasai (着てみてください).",diagnosticFeedback:{"着【き】て みてください サイズが 合【あ】うかどうか":"Salah susun terbalik.","合【あ】うかどうか サイズが 着【き】て みてください":"Salah urutan partikel subjek.","サイズが 着【き】て みてください 合【あ】うかどうか":"Salah posisi instruksi."},tokens:["サイズが","合【あ】うかどうか","着【き】て","みてください"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Bedakan fungsi "来るか知っていますか" vs "来るかどうか知っていますか".',sentencePrompt:'Kapan kita menggunakan "来るかどうか知っていますか"?',options:["Ketika pertanyaannya adalah pilihan biner ya/tidak: apakah orang tersebut akan datang atau tidak datang","Ketika kita ingin menanyakan jam berapa orang tersebut datang","Ketika kita melarang orang tersebut untuk datang","Ketika orang tersebut sudah pasti 100% datang"],correctAnswer:"Ketika pertanyaannya adalah pilihan biner ya/tidak: apakah orang tersebut akan datang atau tidak datang",explanation:"かどうか adalah representasi pilihan biner bivalen (datang atau tidak datang / ya atau tidak).",diagnosticFeedback:{"Ketika kita ingin menanyakan jam berapa orang tersebut datang":"Salah: Ini menggunakan kata tanya 何時に来るか.","Ketika kita melarang orang tersebut untuk datang":"Salah: Ini bukan kalimat larangan.","Ketika orang tersebut sudah pasti 100% datang":"Salah: Tidak ada keraguan jika sudah pasti."}}],can_do_challenge:{statement:"Bisa mengonfirmasi apakah klien bisnis jadi berkunjung atau tidak besok pagi.",situation:"Diminta oleh atasan memastikan jadwal kunjungan mitra perusahaan.",promptTask:"Katakan bahwa kamu akan mengonfirmasi apakah tamu jadi datang atau tidak besok!",modelAnswer:"明日【あした】 お客様【きゃくさま】が 来【こ】られる かどうか 確認【かくにん】します。",modelAnswerId:"Saya akan mengonfirmasi apakah besok pelanggan jadi berkunjung atau tidak.",culturalEtiquette:"Gunakan bentuk hormat Korareru/Irassharu untuk tamu dan bungkukkan badan dengan santun.",skillUnlocked:["Menguasai pertanyaan tertanam biner via 〜かどうか","Mampu merangkai klausa kata tanya tertanam gimonshi + 〜か"]},pocket_summary:{keyFormula:"[Bentuk Biasa] + かどうか (apakah ya/tidak) / [Kata Tanya] + [Bentuk Biasa] + か (di mana/kapan/siapa)",coreWords:["かくにん","よてい","ほうもん","しらべる"],coreWarning:"Gunakan bentuk biasa sebelum kadouka (Iku kadouka); jangan gunakan bentuk masu (Ikimasu kadouka).",quickDialogue:"A: 明日来る？ → B: 来るかどうか確認します。"}},"les-n4-u15-03":{pedagogical_framework:{what:{summary:"Penjelasan halus penuh empati (~ndesu / ~nodesu), nominalisasi klausa aksi (~no wa / ~koto wa), penanda topik pembahasan (~ni tsuite), serta fondasi etika Keigo tempat kerja.",canDo:"Bisa menyapa tamu kantor dengan sopan dan menjelaskan agenda rapat perwakilan perusahaan.",targetPatterns:["[Bentuk Biasa / N+na] んです / のです (penjelasan latar belakang / alasan halus)","[Verba Kamus] のは / ことが [Adjektiva] (nominalisasi: hal melakukan verba adalah...)","[Kata Benda] について (mengenai / tentang topik pembahasan)","いらっしゃいませ / よろしく お願【ねが】いいたします (fondasi salam santun kerja)"],coreVocabSample:["かいぎ","ぎだい","せつめい","ごあんない","たんとう","もうします"]},sensei_context:{sceneIntro:"Di lobi resepsionis kantor pusat Tokyo. Budi menyambut kedatangan delegasi bisnis dari Osaka dan mengantarkan mereka menuju ruang rapat eksekutif.",dailyMission:"Gunakan fondasi ragam sopan, salam Keigo dasar, dan 〜について untuk menyajikan agenda kerja hari ini.",whyOrder:"Pelajaran pamungkas N4 adalah jembatan emas menuju level N3 dan dunia kerja profesional Jepang: penguasaan nominalisasi dan fondasi etika komunikasi bisnis."},cultural_notes:{title:"Etika Penyambutan Tamu Perusahaan Jepang (来客応対の基本マナー)",etiquette:'Saat menyambut tamu kantor di lobi, ucapkan: "Irasshaimase. O-machi shite orimashita" (Selamat datang, kami telah menantikan kehadiran Anda) sambil membungkuk 45 derajat (Saikeirei).',taboos:'Jangan pernah mengatakan nama diri sendiri dengan imbuhan "-san" kepada klien luar. Katakan: "Tantou no Budi to moushimasu" (Saya Budi yang bertugas). Eksternalitas Uchi-Soto wajib ditegakkan.'},pronunciation_tips:{title:"Intonasi Rendah Santun pada Frasa Keigo Dasar",moraNote:"O-mou-shi-ma-su terdiri dari 6 mora teratur dengan aksen merendah hormat.",soundTip:'Pada partikel penjelasan "...n desu", jangan menekan huruf n terlalu tajam seperti mendengus.'},common_pitfalls:[{title:'Salah Menyebut Nama Sendiri dengan Akhiran "-San" di Hadapan Klien Luar',caseScenario:"Memperkenalkan diri kepada tamu perusahaan rekanan.",pitfallWarning:'"私【わたし】は ブディさんです。"',rightSolution:'"担当【たんとう】の ブディと 申【もう】します。"',explanation:'Di Jepang, menyebut diri sendiri dengan "-san" adalah kesalahan etika memalukan. Gunakan nama polos + と申します (to moushimasu) untuk merendahkan diri.'},{title:'Lupa Menyisipkan "Na" untuk Kata Benda Sebelum "N desu"',caseScenario:"Menjelaskan alasan sakit kepala.",pitfallWarning:'"風邪【かぜ】んです。"',rightSolution:'"風邪【かぜ】なんです。"',explanation:"Kata Benda dan Kata Sifat-Na wajib menambahkan な sebelum んです: 風邪なんです (karena saya sedang masuk angin)."}],who_and_when:{situational_context:"Menyambut tamu mitra bisnis di lobi kantor, memaparkan topik agenda rapat, menjelaskan alasan pribadi secara halus.",social_relations:"Sangat esensial dalam hubungan bisnis eksternal dan komunikasi profesional.",when_not_to_use:"Jangan memakai ragam Keigo formal tinggi ini saat bergurau bersama adik kandung di rumah."},scenario:{title:"Penyambutan Tamu Delegasi Bisnis di Lobi Kantor",setting:"Lobi lantai 1 kantor pusat, pukul 09.45",narrative:"Budi menyapa perwakilan perusahaan mitra dengan salam hormat, memperkenalkan diri sebagai staf pendamping, dan memandu tamu ke ruang rapat."}},dialogue:[{id:"d1",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"いらっしゃいませ。本日【ほんじつ】の ご案内【あんない】を 担当【たんとう】いたします ブディと 申【もう】します。",furigana:"いらっしゃいませ。本日の ご案内を 担当いたします ブディと 申します。",romaji:"Irasshaimase. Honjitsu no go-annai o tantou itashimasu Budi to moushimasu.",idText:"Selamat datang. Saya Budi yang bertugas memandu agenda kunjungan Bapak/Ibu pada hari ini."},{id:"d2",speaker:"Matsumoto",speakerRole:"Tamu Klien Bisnis",avatar:"🧑‍💼",jp:"松本【まつもと】商事【しょうじ】の 松本【まつもと】です。今日【きょう】は どうぞ よろしく お願【ねが】いします。",furigana:"松本商事の 松本です。今日は どうぞ よろしく お願いします。",romaji:"Matsumoto Shouji no Matsumoto desu. Kyou wa douzo yoroshiku onegai shimasu.",idText:"Saya Matsumoto dari Matsumoto Corporation. Hari ini mohon kerja samanya selalu."},{id:"d3",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"お待ちして おりました。三階【さんがい】の 第一【だいいち】 会議室【かいぎしつ】へ ご案内【あんない】いたします。",furigana:"お待ちして おりました。３階の 第１ 会議室へ ご案内いたします。",romaji:"Omachi shite orimashita. Sangai no daiichi kaigishitsu e go-annai itashimasu.",idText:"Kami telah menantikan kehadiran Anda. Mari saya antarkan menuju ruang rapat nomor 1 di lantai 3."},{id:"d4",speaker:"Matsumoto",speakerRole:"Tamu Klien Bisnis",avatar:"🧑‍💼",jp:"今日【きょう】の 会議【かいぎ】では、主【おも】に どんな 議題【ぎだい】を 話【はな】し合【あ】うんですか。",furigana:"今日の 会議では、主に どんな 議題を 話し合うんですか。",romaji:"Kyou no kaigi de wa, omo ni donna gidai o hanashiau n desu ka.",idText:"Dalam rapat hari ini, utamanya topik agenda apa yang akan kita diskusikan bersama?"},{id:"d5",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"新【あたら】しい 輸出【ゆしゅつ】計画【けいかく】について ご説明【せつめい】する 予定【よてい】なんです。",furigana:"新しい 輸出計画について ご説明する 予定なんです。",romaji:"Atarashii yushutsu keikaku ni tsuite go-setsumei suru yotei na n desu.",idText:"Rencananya adalah kami akan memaparkan penjelasan mengenai rencana ekspor yang baru."},{id:"d6",speaker:"Matsumoto",speakerRole:"Tamu Klien Bisnis",avatar:"🧑‍💼",jp:"ブディさんは 日本語【にほんご】が とても 流暢【りゅうちょう】ですね。素晴らしい ですよ。",furigana:"ブディさんは 日本語が とても 流暢ですね。素晴らしい ですよ。",romaji:"Budi-san wa nihongo ga totemo ryuuchou desu ne. Subarashii desu yo.",idText:"Budi-san bahasa Jepangnya sangat fasih ya. Sungguh sangat luar biasa."},{id:"d7",speaker:"Budi",speakerRole:"Pembelajar Indonesia",avatar:"🙋‍♂️",jp:"ありがとうございます！ 日本語【にほんご】を 勉強【べんきょう】するのは 本当【ほんとう】に 楽【たの】しいです。",furigana:"ありがとうございます！ 日本語を 勉強するのは 本当に 楽しいです。",romaji:"Arigatou gozaimasu! Nihongo o benkyou suru no wa hontou ni tanoshii desu.",idText:"Terima kasih banyak atas pujiannya! Belajar bahasa Jepang sungguh merupakan hal yang sangat menyenangkan bagi saya."}],vocab_breakdown:[{id:"vg-n4-00711",word:"お宅",reading:"おたく",romaji:"otaku",meaning:"rumah (orang lain, bentuk sopan/hormat); keluarga Anda",pos:"noun",nuance:"Bentuk sonkeigo (hormat) untuk rumah orang lain, dengan awalan お- pada 宅 (taku). Jangan gunakan untuk rumah sendiri (untuk rumah sendiri gunakan 家/ie atau 拙宅/settaku). Catatan: kata ini juga bisa menjadi panggilan ganti orang kedua 'Anda', dan dalam kultur pop berkembang menjadi istilah penggemar berat (otaku).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"先生のお宅にご招待いただき、本当にありがとうございました。",furigana:"先生のお宅にご招待いただき、本当にありがとうございました。",romaji:"",idText:"Terima kasih banyak telah mengundang saya ke kediaman Sensei."}},{id:"vg-n4-00776",word:"壁",reading:"かべ",romaji:"kabe",meaning:"dinding, tembok, penghalang",pos:"noun",nuance:"Merujuk pada permukaan tegak dinding di dalam gedung maupun metafora batasan rintangan berat dalam kehidupan (seperti 言葉の壁 / rintangan bahasa). Berbeda dengan 塀 (hei) yang khusus bermakna tembok pagar pembatas di luar pekarangan.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"部屋の白い壁に家族旅行で撮った記念の写真を飾りました。",furigana:"部屋の白い壁に家族旅行で撮った記念の写真を飾りました。",romaji:"",idText:"Saya memasang foto kenang-kenangan perjalanan keluarga di dinding putih kamar."}},{id:"vg-n4-00876",word:"お子さん",reading:"おこさん",romaji:"okosan",meaning:"anak (milik orang lain, bentuk sopan)",pos:"noun",nuance:"Bentuk sonkeigo yang sangat sopan untuk menyebut anak kepunyaan orang lain atau mitra bicara. Berbeda dengan 子供 (kodomo) atau うちの子 (uchi no ko) yang dipakai khusus untuk merujuk anak sendiri di depan orang luar.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"田中さんのお子さんは今年無事に小学校へ入学されましたか。",furigana:"田中さんのお子さんは今年無事に小学校へ入学されましたか。",romaji:"",idText:"Apakah anak Anda, Tuan Tanaka, tahun ini sudah masuk sekolah dasar dengan lancar?"}},{id:"vg-n4-00880",word:"～様",reading:"～さま",romaji:"~sama",meaning:"tuan ~, nyonya ~, yang terhormat ~ (panggilan sangat hormat)",pos:"noun",nuance:"Sufiks kehormatan paling tinggi setelah nama orang (お客様, 田中様) atau tujuan surat resmi. Jauh lebih hormat daripada sufiks ～さん (san). Dipakai khusus untuk pelanggan, mitra bisnis, atau orang berkedudukan tinggi.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"ホテルの係員が「佐藤様、いらっしゃいませ」と笑顔で迎えました。",furigana:"ホテルの係員が「佐藤様、いらっしゃいませ」と笑顔で迎えました。",romaji:"",idText:"Petugas hotel menyambut dengan senyuman, 'Selamat datang, Tuan Sato'."}},{id:"vg-n4-00881",word:"ご存じ",reading:"ごぞんじ",romaji:"gozonji",meaning:"mengetahui, kenal (bentuk hormat)",pos:"noun",nuance:"Bentuk penghormatan sonkeigo dari kata 知っている (tahu/kenal) yang dialamatkan pada lawan bicara (seperti ご存じですか). Jangan digunakan untuk menyebut tindakan diri sendiri; untuk diri sendiri pakailah bentuk merendah 存じております (zonjite orimasu).",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"来週の月曜日に会議が開かれることをご存じでしょうか。",furigana:"来週の月曜日に会議が開かれることをご存じでしょうか。",romaji:"",idText:"Apakah Anda mengetahui bahwa rapat akan diselenggarakan pada hari Senin pekan depan?"}},{id:"vg-n4-01079",word:"下着",reading:"したぎ",romaji:"shitagi",meaning:"pakaian dalam",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"私は新しい下着が気に入っている。",furigana:"私は新しい下着が気に入っている。",romaji:"",idText:"I'm pleased with my new underwear."}},{id:"vg-n4-01088",word:"ジャム",reading:"ジャム",romaji:"jamu",meaning:"selai",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"イチゴはジャムに作られる。",furigana:"イチゴはジャムに作られる。",romaji:"",idText:"Strawberries are made into jam."}},{id:"vg-n4-01090",word:"習慣",reading:"しゅうかん",romaji:"shuukan",meaning:"adat; sopan santun",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"その習慣は中国で始まった。",furigana:"その習慣は中国で始まった。",romaji:"",idText:"The custom originated in China."}},{id:"vg-n4-01124",word:"世界",reading:"せかい",romaji:"sekai",meaning:"dunia",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"愛の力は世界を動かす。",furigana:"愛の力は世界を動かす。",romaji:"",idText:"Love makes the world go round."}},{id:"vg-n4-01208",word:"ねだん",reading:"ねだん",romaji:"nedan",meaning:"harga",pos:"noun",nuance:"Kosakata level N4: perbendaharaan kata penting untuk pemahaman standar JLPT.",particleTip:"Gunakan bersama partikel yang tepat.",exampleSentence:{jp:"このラジオの値段はいくらですか。",furigana:"このラジオの値段はいくらですか。",romaji:"",idText:"Berapa harga radio ini?"}}],explanations:[{id:"exp-1",grammarId:"gn4-00048",title:"Pola: 〜んです / 〜のです",formula:"V/Adj plain + んです / のです",meaning:"... (itu) ... (penjelasan/alasan)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜んです / 〜のです",idText:"... (itu) ... (penjelasan/alasan)"}],examples:[{jp:"今日は来られないんです。用事があって。",romaji:"",idText:"Hari ini saya tidak bisa datang. Ada keperluan."},{jp:"どうしたんですか。顔色が悪いですよ。",romaji:"",idText:"Ada apa? Mukamu pucat."}]},{id:"exp-2",grammarId:"gn4-00051",title:"Pola: 〜の (nominalisasi)",formula:"V/Adj plain + の + は/が/を",meaning:"hal ... / tindakan ... (nominalisasi)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜の (nominalisasi)",idText:"hal ... / tindakan ... (nominalisasi)"}],examples:[{jp:"歌うのが好きです。",romaji:"",idText:"Saya suka bernyanyi."},{jp:"彼が走っているのを見ました。",romaji:"",idText:"Saya melihat dia sedang berlari."}]},{id:"exp-3",grammarId:"gn4-00052",title:"Pola: 〜こと (nominalisasi)",formula:"V/Adj plain + こと + は/が/を/etc.",meaning:"hal ... / fakta bahwa ... (nominalisasi)",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜こと (nominalisasi)",idText:"hal ... / fakta bahwa ... (nominalisasi)"}],examples:[{jp:"毎日練習することが大切です。",romaji:"",idText:"Berlatih setiap hari adalah hal yang penting."},{jp:"彼女が結婚することを知りました。",romaji:"",idText:"Saya tahu bahwa dia akan menikah."}]},{id:"exp-4",grammarId:"gn4-00006",title:"Pola: 〜について",formula:"N + について + V/Adj",meaning:"tentang ... / mengenai ...",nuanceNotes:"Digunakan untuk memperjelas wacana dan tingkat kesantunan.",patternLogic:"Perhatikan urutan kata dan perubahan bentuk sebelum pola ini.",particleNotes:"Perhatikan partikel penghubung yang menyertai pola ini.",formVariations:[{label:"Bentuk Standar",jp:"〜について",idText:"tentang ... / mengenai ..."}],examples:[{jp:"環境問題について話し合いました。",romaji:"",idText:"Kami berdiskusi tentang masalah lingkungan."},{jp:"日本の文化についてもっと知りたいです。",romaji:"",idText:"Saya ingin tahu lebih banyak tentang budaya Jepang."}]}],drills:[{id:"drill-1",type:"vocab_context",instruction:"Langkah 1 (Konsep Kata): Pilihlah istilah yang tepat untuk topik/agenda pokok bahasan dalam rapat.",sentencePrompt:"Pokok bahasan atau agenda yang didiskusikan dalam rapat resmi disebut:",options:["議題【ぎだい】 (Agenda bahasan)","宿題【しゅくだい】 (PR sekolah)","問題【もんだい】 (Soal ujian)","話題【わだい】 (Bahan gosip)"],correctAnswer:"議題【ぎだい】 (Agenda bahasan)",explanation:"議題 (gidai) adalah agenda materi resmi yang diangkat untuk dimusyawarahkan dalam forum rapat.",diagnosticFeedback:{"宿題【しゅくだい】 (PR sekolah)":"Salah: 宿題 adalah pekerjaan rumah murid.","問題【もんだい】 (Soal ujian)":"Salah: 問題 adalah problem atau butir soal.","話題【わだい】 (Bahan gosip)":"Salah: 話題 adalah topik obrolan tren."}},{id:"drill-2",type:"cloze",instruction:"Langkah 2 (Pola Topik Bahasan): Lengkapi kalimat memaparkan sejarah kebudayaan Jepang.",sentencePrompt:"今日【きょう】は 日本【にほん】の 文化【ぶんか】（　　）発表【はっぴょう】します。",options:["について","にとって","として","によって"],correctAnswer:"について",explanation:'Pola [Kata Benda] + について menyatakan "mengenai / tentang topik pembahasan" (日本の文化について).',diagnosticFeedback:{にとって:"Salah: にとって berarti menurut penilaian sudut pandang.",として:"Salah: として berarti dalam kedudukan sebagai.",によって:"Salah: によって berarti disebabkan oleh."}},{id:"drill-3",type:"trap_detect",instruction:'Langkah 3 (Pola Nominalisasi No wa): Lengkapi kalimat nominalisasi "membuat kue adalah hal yang menyenangkan".',sentencePrompt:"お菓子【かし】を 作【つく】る（　　）は、とても 楽【たの】しいです。",options:["の","な","に","と"],correctAnswer:"の",explanation:"Partikel の berfungsi menominalisasikan (mengubah kata kerja menjadi kata benda): 作るのは = hal membuat kue.",diagnosticFeedback:{な:"Salah: な tidak bisa menominalisasikan kata kerja.",に:"Salah: bukan partikel nominalisasi subjek.",と:"Salah: と adalah partikel pengutip."}},{id:"drill-4",type:"reorder",instruction:"Langkah 4 (Susun Kalimat): Rangkai perkenalan diri santun kepada tamu bisnis di kantor.",sentencePrompt:'Susunlah kata-kata: "Saya Budi yang bertugas memandu Anda".',options:["ご案内【あんない】を 担当【たんとう】いたします ブディと 申【もう】します","担当【たんとう】いたします ご案内【あんない】を 申【もう】します ブディと","ブディと 申【もう】します ご案内【あんない】を 担当【たんとう】いたします","申【もう】します ブディと 担当【たんとう】いたします ご案内【あんない】を"],correctAnswer:"ご案内【あんない】を 担当【たんとう】いたします ブディと 申【もう】します",explanation:"Objek tugas (ご案内を) + Verba merendah (担当いたします) + Nama diri merendah (ブディと申します).",diagnosticFeedback:{"担当【たんとう】いたします ご案内【あんない】を 申【もう】します ブディと":"Salah susun.","ブディと 申【もう】します ご案内【あんない】を 担当【たんとう】いたします":"Kurang alami urutan perkenalannya.","申【もう】します ブディと 担当【たんとう】いたします ご案内【あんない】を":"Salah posisi kata kerja merendah."},tokens:["ご案内【あんない】を","担当【たんとう】いたします","ブディと","申【もう】します"],correctOrder:["0","1","2","3"]},{id:"drill-5",type:"response",instruction:'Langkah 5 (Analisis Nuansa): Analisislah fungsi partikel "~n desu" dalam kalimat "新しい計画を説明する予定なんです".',sentencePrompt:'Penggunaan akhiran "〜なんです" dalam kalimat tersebut memberikan nuansa:',options:["Menjelaskan latar belakang konteks agenda secara ramah, komunikatif, dan membagikan informasi dengan empati","Menolak berbicara dengan tamu karena sedang sibuk","Memerintahkan tamu untuk segera membaca dokumen dalam diam","Menunjukkan rasa marah karena tamu banyak bertanya"],correctAnswer:"Menjelaskan latar belakang konteks agenda secara ramah, komunikatif, dan membagikan informasi dengan empati",explanation:"Akhiran 〜んです / 〜のです berfungsi menjembatani pemahaman antar-bicara dengan memaparkan konteks latar belakang secara hangat dan bersahabat.",diagnosticFeedback:{"Menolak berbicara dengan tamu karena sedang sibuk":"Salah: Justru sangat menyambut.","Memerintahkan tamu untuk segera membaca dokumen dalam diam":"Salah: Bukan instruksi dingin.","Menunjukkan rasa marah karena tamu banyak bertanya":"Salah: Bukan ekspresi kemarahan."}}],can_do_challenge:{statement:"Bisa menyapa tamu kantor dengan sopan dan menjelaskan agenda rapat perwakilan perusahaan.",situation:"Menyambut tamu dari kantor rekanan di lobi kantor perusahaan.",promptTask:"Sambut tamu dengan hormat dan katakan bahwa kamu yang bertugas memandu rapat hari ini!",modelAnswer:"いらっしゃいませ。本日【ほんじつ】の ご案内【あんない】を 担当【たんとう】いたします ブディと 申【もう】します。",modelAnswerId:"Selamat datang. Saya Budi yang bertugas memandu kunjungan Bapak/Ibu pada hari ini.",culturalEtiquette:"Bungkukkan badan 45 derajat (Saikeirei) dengan tangan terkatup rapi di depan tubuh.",skillUnlocked:["Menguasai fondasi perkenalan Keigo bisnis diri sendiri via と申します","Mampu menominalisasikan klausa via 〜のは / 〜こと, dan topik via 〜について"]},pocket_summary:{keyFormula:"[N] について (tentang) / [V-Kamus] のは [Adj] (nominalisasi) / [Bentuk Biasa+na] んです (alasan empati) / と申します (Keigo perkenalan)",coreWords:["かいぎ","ぎだい","せつめい","ごあんない"],coreWarning:"Jangan menyebut diri sendiri dengan akhiran san di hadapan klien (Budi to moushimasu, bukan Budi-san desu).",quickDialogue:"A: 議題は？ → B: 輸出計画についてです。"}}};export{r as a,t as b,i as c,e as d,n as e,a as f,u};
